Object.assign(window.TEM8_DICTIONARY, {"wounds":{"oxford":{"phon":"wuːnd","pos":"noun","senses":[{"en":"an injury to part of the body, especially one in which a hole is made in the skin using a weapon （","cn":"身体上的）伤，伤口；（武器造成的）伤"},{"en":"mental or emotional pain caused by sth unpleasant that has been said or done to you （","cn":"心灵上的）伤，创伤"}]},"media":{"uk":"media/uk/wound__gb_2.mp3","us":"media/us/wound__us_2.mp3"}},"woven":{"collins":{"senses":[{"pos":"","cn":"","en":"Woven is a past participle of weave."}]},"media":{"uk":"media/uk/woven__gb_1.mp3","us":"media/us/woven__us_1.mp3"}},"worship":{"media":{"uk":"media/uk/worship__gb_1.mp3","us":"media/us/worship__us_1.mp3"},"oxford":{"phon":"ˈwɜːʃɪp","pos":"noun","senses":[{"en":"the practice of showing respect for God or a god, by saying prayers, singing with others, etc.; a ceremony for this","cn":"（对上帝或神的）崇拜，敬仰，礼拜","g":"[uncountable]","ex":{"en":"an act/a place of worship","cn":"礼拜；礼拜场所"}},{"en":"a strong feeling of love and respect for somebody/something","cn":"崇拜；崇敬；爱慕","g":"[uncountable]","ex":{"en":"What she feels for him is akin to worship.","cn":"她对他的感觉近似于爱慕。"}},{"en":"a polite way of addressing or referring to a magistrate or mayor","cn":"（对治安官或市长的尊称）阁下","g":"[countable]","lab":"British English, formal，，"},{"en":"to show respect for God or a god, especially by saying prayers, singing, etc. with other people in a religious building","cn":"崇敬，崇拜（上帝或神）；（尤指在宗教场所）做礼拜","g":"[transitive]","lab":"North American English","ex":{"en":"The Mayans built jungle pyramids to worship their gods.","cn":"玛雅人在丛林里建起了金字塔来膜拜他们的神。"},"pos":"verb"},{"en":"to go to a service in a religious building","cn":"到宗教场所参加礼拜","g":"[intransitive]","ex":{"en":"We worship at St Mary's.","cn":"我们在圣马利教堂做礼拜。"},"pos":"verb"},{"en":"to love and admire somebody very much, especially so much that you cannot see their faults","cn":"热爱；爱慕，崇拜（尤指达到看不到缺点的地步）","g":"[transitive]","ex":{"en":"She worships her children.","cn":"她极度疼爱自己的儿女。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"敬奉(神)","en":"If you worship a god, you show your respect to the god, for example by saying prayers.","ex":{"en":"I enjoy going to church and worshipping God.","cn":"我喜欢去教堂做礼拜。"}},{"pos":"VERB 动词","cn":"崇拜;景仰;热爱","en":"If you worship someone or something, you love them or admire them very much.","ex":{"en":"She had worshipped him for years","cn":"她仰慕他已有多年。"}}]},"examples":[{"en":"She worships the ground he walks on.","cn":"她对他的爱达到痴迷的程度。"},{"en":"We worship at St Mary's.","cn":"我们在圣玛利教堂做礼拜。"}]},"workforce":{"media":{"uk":"media/uk/workforce__gb_1.mp3","us":"media/us/workforce__us_1.mp3"},"oxford":{"phon":"ˈwɜːkfɔːs","pos":"noun","senses":[{"en":"all the people who work for a particular company, organization, etc.","cn":"全体员工","lab":"British English","ex":{"en":"The factory has a 1 000-strong workforce.","cn":"这家工厂的职工多达千人。"}},{"en":"all the people in a country or an area who are available for work","cn":"（国家或行业等的）劳动力，劳动大军，劳动人口","ex":{"en":"A quarter of the local workforce is/are unemployed.","cn":"本地四分之一的劳动力都失业了。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(某一国家或地区的)劳动力，劳动人口","en":"The workforce is the total number of people in a country or region who are physically able to do a job and are available for work.","ex":{"en":"...a country where half the workforce is unemployed.","cn":"有一半劳动力失业的国家"}},{"pos":"N-COUNT 可数名词","cn":"(某公司的)全体员工，职工总数","en":"The workforce is the total number of people who are employed by a particular company.","ex":{"en":"...an employer of a very large workforce.","cn":"雇用了大量员工的雇主"}}]},"examples":[{"en":"A quarter of the local workforce is/are unemployed.","cn":"本地四分之一的劳动力都失业了。"},{"en":"The factory has a 1 000-strong workforce.","cn":"这家工厂的职工多达千人。"}]},"wonder":{"media":{"uk":"media/uk/wonder__gb_1.mp3","us":"media/us/wonder__us_1.mp3"},"oxford":{"phon":"ˈwʌndə(r)","pos":"verb","senses":[{"en":"to think about something and try to decide what is true, what will happen, what you should do, etc.","cn":"想知道；想弄明白；琢磨","g":"[transitive, intransitive]","ex":{"en":"‘Why do you want to know?’ ‘No particular reason. I was just wondering.’","cn":"“你为什么想要知道？”“没有特殊原因。我就是想搞清楚。”"}},{"en":"used as a polite way of asking a question or asking somebody to do something","cn":"（礼貌地提问或请人做事时说）","g":"[transitive]","ex":{"en":"I wonder if you can help me.","cn":"不知您是否能帮我的忙？"}},{"en":"to be very surprised by something","cn":"感到诧异；非常惊讶","g":"[intransitive, transitive]","lab":"British English, informal，，","ex":{"en":"She wondered at her own stupidity.","cn":"她没想到自己竟会这样愚蠢。"}},{"en":"a feeling of surprise and pleasure that you have when you see or experience something beautiful, unusual or unexpected","cn":"惊讶；惊奇；惊异；惊叹","g":"[uncountable]","ex":{"en":"He retained a childlike sense of wonder.","cn":"他仍然有一种孩子般的好奇感。"},"pos":"noun"},{"en":"something that fills you with surprise and pleasure","cn":"奇迹；奇观；奇事；奇妙之处","g":"[countable]","ex":{"en":"The temple, built in 1403, is an architectural wonder.","cn":"这座庙建于 1403 年，是建筑史上的奇迹。"},"pos":"noun"},{"en":"a person who is very clever at doing something; a person or thing that seems very good or effective","cn":"能人；奇才；有特效的东西","g":"[singular]","lab":"informal","ex":{"en":"Dita, you're a wonder! I would never have thought of doing that.","cn":"蒂塔，你真神了！我从来想不到那样做。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"感到疑惑;纳闷儿;想弄明白","en":"If you wonder about something, you think about it, either because it interests you and you want to know more about it, or because you are worried or suspicious about it.","ex":{"en":"I wondered what that noise was","cn":"我纳闷儿那是什么声音。"}},{"pos":"VERB 动词","cn":"(对…)大为吃惊，惊叹","en":"If you wonder at something, you are very surprised about it or think about it in a very surprised way.","ex":{"en":"He liked to sit and wonder at all that had happened","cn":"他喜欢坐着对发生的一切惊叹不已。"}},{"pos":"N-SING 单数名词","cn":"奇事;怪事","en":"If you say that it is a wonder that something happened, you mean that it is very surprising and unexpected.","ex":{"en":"It's a wonder that it took almost ten years","cn":"这差不多用了10年的时间，真是桩奇事。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"惊叹;惊奇;惊异","en":"Wonder is a feeling of great surprise and pleasure that you have, for example when you see something that is very beautiful, or when something happens that you thought was impossible.","ex":{"en":"'That's right!' Bobby exclaimed in wonder. 'How did you remember that?'","cn":"“对呀！”博比惊奇地叫道。“你是怎么想起那件事的？”"}},{"pos":"N-COUNT 可数名词","cn":"奇迹;奇观;奇事","en":"A wonder is something that causes people to feel great surprise or admiration.","ex":{"en":"...a lecture on the wonders of space and space exploration.","cn":"关于宇宙奇观和太空探险的讲座"}},{"pos":"ADJ 形容词","cn":"神奇的;奇妙的;有奇效的","en":"If you refer, for example, to a young man as a wonder boy, or to a new product as a wonder drug, you mean that they are believed by many people to be very good or very effective.","ex":{"en":"Mickelson was hailed as the wonder boy of American golf","cn":"米克尔森被誉为美国高尔夫球界的神奇小子。"}},{"pos":"PHRASE 短语","cn":"昙花一现的人(或事物);惊艳一时的人(或事物)","en":"If you say that someone or something is a nine-day wonder or a one-day wonder, you disapprove of the fact that they are attracting so much interest and attention, because you think that their popularity will only last for a very short time.","ex":{"en":"Harry dismissed his old friend's speech as 'a nine-day wonder'","cn":"哈里对老朋友的讲话不屑一顾，称之“火不了多久”。"}},{"pos":"PHRASE 短语","cn":"(用于礼貌地请人做事、征求意见或打听消息时)不知…，请问…","en":"You can say 'I wonder' if you want to be very polite when you are asking someone to do something, or when you are asking them for their opinion or for information.","ex":{"en":"I was just wondering if you could help me","cn":"不知您是否能帮我个忙。"}},{"pos":"PHRASE 短语","cn":"难怪；怪不得；不足为怪","en":"If you say 'no wonder', 'little wonder', or 'small wonder', you mean that something is not surprising.","ex":{"en":"No wonder my brother wasn't feeling well","cn":"难怪我兄弟感觉不舒服了。"}},{"pos":"PHRASE 短语","cn":"（表示找出某事的原因）难怪，怪不得","en":"You can say 'No wonder' when you find out the reason for something that has been puzzling you for some time.","ex":{"en":"Brad was Jane's brother! No wonder he reminded me so much of her!","cn":"布拉德是简的兄弟！怪不得他老是让我想起她呢！"}},{"pos":"PHRASE 短语","cn":"创造奇迹;产生奇迹","en":"If you say that a person or thing works wonders or does wonders, you mean that they have a very good effect on something.","ex":{"en":"A few moments of relaxation can work wonders","cn":"放松一会儿就可以收到奇效。"}}]},"examples":[{"en":"‘Why do you want to know?’ ‘No particular reason. I was just wondering.’ “","cn":"你为什么想要知道？” “没有特殊原因。我就是想搞清楚。”"},{"en":"‘I've cleaned my room.’ ‘Wonders will never cease!’ “","cn":"我把我的房间打扫干净了。” “怎么太阳从西边出来了！”"}]},"world-class":{"oxford":{"phon":"ˌwɜːld ˈklɑːs","pos":"adjective","senses":[{"en":"as good as the best in the world","cn":"世界级的；世界一流的","ex":{"en":"a world-class athlete","cn":"世界一流的运动员"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"世界级的；世界一流的","en":"A world-class sports player, performer, or organization is one of the best in the world.","ex":{"en":"He was determined to become a world-class player.","cn":"他决心成为世界级选手。"}}]},"media":{"uk":"media/uk/world_class_1_gb_1.mp3","us":"media/us/world_class_1_us_1.mp3"},"examples":[{"en":"a world-class athlete","cn":"世界一流的运动员"},{"en":"a world-class tennis champion","cn":"世界级网球冠军"}]},"workout":{"media":{"uk":"media/uk/workout__gb_1.mp3","us":"media/us/workout__us_1.mp3"},"oxford":{"phon":"ˈwɜːkaʊt","pos":"noun","senses":[{"en":"a period of physical exercise that you do to keep fit","cn":"锻炼","ex":{"en":"She does a 20-minute workout every morning.","cn":"她每天早晨做运动 20 分钟。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"体育锻炼;体育训练","en":"A workout is a period of physical exercise or training.","ex":{"en":"Give your upper body a workout by using handweights.","cn":"用哑铃来锻炼上身。"}}]},"examples":[{"en":"She does a 20-minute workout every morning.","cn":"她每天早晨做运动 20 分钟。"},{"en":"a daily workout in the gym","cn":"在健身房的日常锻炼"}]},"wording":{"oxford":{"phon":"ˈwɜːdɪŋ","pos":"noun","senses":[{"en":"the words that are used in a piece of writing or speech, especially when they have been carefully chosen","cn":"措辞；用词","ex":{"en":"The wording was deliberately ambiguous.","cn":"这里的措辞故意模棱两可。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"措辞;用词","en":"The wording of a piece of writing or a speech are the words used in it, especially when these are chosen to have a particular effect.","ex":{"en":"The two sides failed to agree on the wording of a final report","cn":"双方未能就最终报告的措辞达成一致。"}}]},"media":{"uk":"media/uk/wording__gb_1.mp3","us":"media/us/wording__us_1.mp3"},"examples":[{"en":"The wording was deliberately ambiguous.","cn":"这里的措辞故意模棱两可。"},{"en":"the exact wording of the contract","cn":"合同的确切措辞"}]},"worst":{"oxford":{"phon":"wɜːst","pos":"adjective","senses":[{"en":"of the poorest quality or lowest standard; worse than any other person or thing of a similar kind","cn":"最差的；最坏的；最糟的","ex":{"en":"It was by far the worst speech he had ever made.","cn":"这是他迄今发表过的最差的演讲。"}},{"en":"most badly or seriously","cn":"最坏；最糟；最严重","ex":{"en":"He was voted the worst dressed celebrity.","cn":"大家一致认为他是衣着最差的名人。"},"pos":"adverb"},{"en":"the most serious or unpleasant thing that could happen; the part, situation, possibility, etc. that is worse than any other","cn":"（可能发生的）最严重的事；最坏的部分（或情况、可能性等）","ex":{"en":"When they did not hear from her, they feared the worst.","cn":"他们听不到她的消息时，唯恐发生了最坏的事。"},"pos":"noun"},{"en":"to defeat somebody in a fight, a contest or an argument","cn":"（在打斗、比赛或辩论中）打败，战胜","ex":{"en":"She couldn't bear to be worsted in a fight.","cn":"她无法忍受输掉比赛。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"","cn":"(bad 的最高级)","en":"Worst is the superlative of bad ."},{"pos":"","cn":"(badly的最高级)","en":"Worst is the superlative of badly ."},{"pos":"N-SING 单数名词","cn":"最坏的事;最糟的情况","en":"The worst is the most unpleasant or unfavourable thing that could happen or does happen.","ex":{"en":"Though mine safety has much improved, miners' families still fear the worst","cn":"尽管矿井的安全状况有了很大改善，矿工的家属仍然害怕最糟的情况会发生。"}},{"pos":"","cn":"(用于构成以 bad 和 badly 开头的复合形容词的最高级，如badly-affected的最高级是worst-affected)","en":"Worst is used to form the superlative of compound adjectives beginning with 'bad' and 'badly'. For example, the superlative of 'badly-affected' is 'worst-affected'."},{"pos":"PHRASE 短语","cn":"最糟糕的是","en":"You say worst of all to indicate that what you are about to mention is the most unpleasant or has the most disadvantages out of all the things you are mentioning.","ex":{"en":"The people most closely affected are the passengers who were injured and, worst of all, those who lost relatives.","cn":"受影响最大的是受伤的乘客，那些失去亲人的乘客尤为甚。"}},{"pos":"PHRASE 短语","cn":"在最坏的情况下","en":"You use at worst or at the worst to indicate that you are mentioning the worst thing that might happen in a situation.","ex":{"en":"At best Nella would be an invalid; at worst she would die","cn":"内拉往好里说会落下残疾，往坏处说可能会生命不保。"}},{"pos":"PHRASE 短语","cn":"在（心情、境况）最糟糕的时候","en":"When someone is at their worst, they are as unpleasant, bad, or unsuccessful as it is possible for them to be.","ex":{"en":"This was their mother at her worst. Her voice was strident, she was ready to be angry at anyone.","cn":"这是他们的母亲情绪最坏之时，她说话咄咄逼人，随时会对任何人发火。"}},{"pos":"PHRASE 短语","cn":"如果发生最坏的情况（if worst comes to worst 主要用于美国英语）","en":"You use if the worst comes to the worst to say what you might do if a situation develops in the most unfavourable way possible. The form if worst comes to worst is also used, mainly in American English.","ex":{"en":"If the worst comes to the worst I guess I can always ring Jean","cn":"到了一筹莫展的时候，我想我总还是能给琼打电话。"}},{"pos":"PHRASE 短语","cn":"不择手段；使出一切手段;有什么手段尽管使出来","en":"If someone does their worst, they do everything unpleasant that they can possibly do. You can say 'do your worst' to show someone that you are not frightened of what they may do.","ex":{"en":"I think it was dangerous to say: look, we've got an army now — do your worst.","cn":"我觉得要是说“瞧，我们现在有一大群人——你有什么手段尽管使出来吧”，可能会引起麻烦。"}}]},"media":{"uk":"media/uk/worst__gb_1.mp3","us":"media/us/worst__us_1.mp3"},"examples":[{"en":"The worst of it is that I can't even be sure if they received my letter.","cn":"最糟糕的是，我甚至不能肯定他们是否收到了我的信。"},{"en":"Let them do their worst — we'll fight them every inch of the way.","cn":"随便他们干什么坏事吧，我们一定和他们拼到底。"}]},"wonderful":{"media":{"uk":"media/uk/wonderful__gb_1.mp3","us":"media/us/wonderful__us_1.mp3"},"oxford":{"phon":"ˈwʌndəfl","pos":"adjective","senses":[{"en":"very good, pleasant or a lot of fun","cn":"精彩的；绝妙的；令人高兴的；使人愉快的","ex":{"en":"This is a wonderful opportunity to invest in new markets.","cn":"这是投资新市场的绝好机会。"}},{"en":"making you feel great surprise and pleasure","cn":"令人惊奇的；令人赞叹的","lab":"especially British English","ex":{"en":"It's wonderful what you can do when you have to.","cn":"在迫不得已时，人的潜能令人惊叹。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"精彩的;绝妙的;极好的","en":"If you describe something or someone as wonderful, you think they are extremely good.","ex":{"en":"The cold, misty air felt wonderful on his face","cn":"雾蒙蒙的寒冷空气使他脸上感觉很舒爽。"}}]},"examples":[{"en":"It's wonderful what you can do when you have to.","cn":"在迫不得已时，人的潜能令人惊叹。"},{"en":"We had a wonderful time last night.","cn":"我们昨天夜里过得非常愉快。"}]},"work":{"media":{"uk":"media/uk/work__gb_1.mp3","us":"media/us/work__us_1.mp3"},"oxford":{"phon":"wɜːk","pos":"verb","senses":[{"en":"to do something that involves physical or mental effort, especially as part of a job","cn":"做体力（或脑力）工作；劳动；干活","g":"[intransitive]","sc":"do job/task","ex":{"en":"I can't work if I'm cold.","cn":"我要是觉得冷就干不了活。"}},{"en":"to have a job","cn":"受雇于；从事…工作","g":"[intransitive]","sc":"do job/task","ex":{"en":"Both my parents work.","cn":"我父母都工作。"}},{"en":"to make efforts to achieve something","cn":"争取；力争；努力取得","g":"[intransitive]","sc":"make effort","ex":{"en":"She dedicated her life to working for peace.","cn":"她为争取和平奉献了自己的一生。"}},{"en":"to make yourself/somebody work, especially very hard","cn":"使工作；（尤指）使卖力干活","g":"[transitive]","sc":"make effort","ex":{"en":"She works herself too hard.","cn":"她工作起来太不辞劳苦了。"}},{"en":"to function; to operate","cn":"运转；运行","g":"[intransitive]","sc":"machine/device/system","ex":{"en":"The printer isn't working.","cn":"这部打印机坏了。"}},{"en":"to make a machine, device, etc. operate","cn":"开动，操作（机器、装置等）；使运作","g":"[transitive]","sc":"machine/device/system","ex":{"en":"Do you know how to work the coffee machine?","cn":"你会使用咖啡机吗？"}},{"en":"to have the result or effect that you want","cn":"奏效；产生预期的结果（或作用）","g":"[intransitive]","sc":"have result/effect","ex":{"en":"The pills the doctor gave me aren't working.","cn":"医生给我的药片不管事。"}},{"en":"to have a particular effect","cn":"产生…作用","g":"[intransitive]","sc":"have result/effect","ex":{"en":"Your age can work against you in this job.","cn":"你的年纪会妨碍你干这个工作。"}},{"en":"to manage or operate something to gain benefit from it","cn":"管理，经营（以获利）","g":"[transitive]","lab":"figurative","sc":"manage","ex":{"en":"to work the land (= grow crops on it, etc.)","cn":"耕种土地"}},{"en":"to make a material into a particular shape or form by pressing, stretching, hitting it, etc.","cn":"（通过压挤、拉长、锤击等）使成形，使定形","g":"[transitive]","sc":"use material","ex":{"en":"to work clay","cn":"制陶"}},{"en":"to use a particular material to produce a picture or other item","cn":"用某种材料作画（或编制、编织等）","g":"[intransitive]","sc":"use material","ex":{"en":"an artist working in oils","cn":"油画画家"}},{"en":"to move violently","cn":"抽动；抽搐；颤动","g":"[intransitive]","lab":"formal","sc":"of part of face/body","ex":{"en":"He stared at me in horror, his mouth working.","cn":"他恐惧地盯着我，嘴在抽搐着。"}},{"en":"to move or pass to a particular place or state, usually gradually","cn":"（逐渐地）移动（到某位置）；（逐步）变成（某状态）","g":"[intransitive, transitive]","lab":"figurative","sc":"move gradually","ex":{"en":"It will take a while for the drug to work out of your system.","cn":"这药需要一段时间才能从你体内排出。"}},{"en":"the job that a person does especially in order to earn money","cn":"工作；职业","g":"[uncountable]","lab":"British English","sc":"job/task","ex":{"en":"He started work as a security guard.","cn":"他开始工作时做保安员。"},"pos":"noun"},{"en":"the place where you do your job; the time that you spend there","cn":"工作场所；工作时间","g":"[uncountable]","sc":"job/task","ex":{"en":"I go to work at 8 o'clock.","cn":"我 8 点钟去上班。"},"pos":"noun"},{"en":"the duties that you have and the activities that you do as part of your job","cn":"职责；工作内容","g":"[uncountable]","sc":"job/task","ex":{"en":"Police work is mainly routine.","cn":"警察的工作主要都是按常规的。"},"pos":"noun"},{"en":"tasks that need to be done","cn":"工作；活计","g":"[uncountable]","sc":"job/task","ex":{"en":"Taking care of a baby is hard work.","cn":"照看婴儿是件苦差。"},"pos":"noun"},{"en":"materials needed or used for doing work, especially books, papers, etc.","cn":"工作所需的材料（或档案等）","g":"[uncountable]","sc":"job/task","ex":{"en":"She often brings work (= for example, files and documents) home with her from the office.","cn":"她经常把办公室里的工作带回家。"},"pos":"noun"},{"en":"the use of physical strength or mental power in order to do or make something","cn":"工作；劳动","g":"[uncountable]","sc":"effort","ex":{"en":"She earned her grades through sheer hard work.","cn":"她的学习成绩完全是靠刻苦用功得来的。"},"pos":"noun"},{"en":"a thing or things that are produced as a result of work","cn":"工作成果；产品；作品","g":"[uncountable]","sc":"product of work","ex":{"en":"She's an artist whose work I really admire.","cn":"她这位艺术家的作品令我赞赏不已。"},"pos":"noun"},{"en":"a book, piece of music, painting, etc.","cn":"著作；作品","g":"[countable]","sc":"book/music/art","ex":{"en":"the collected/complete works of Tolstoy","cn":"托尔斯泰选集／全集"},"pos":"noun"},{"en":"the result of an action; what is done by somebody","cn":"作为；行动结果","g":"[uncountable]","sc":"result of action","ex":{"en":"The damage is clearly the work of vandals.","cn":"这毁损显然是些恣意破坏公物的人所为。"},"pos":"noun"},{"en":"activities involving building or repairing something","cn":"建；修；修建","g":"[plural]","sc":"building/repairing","ex":{"en":"roadworks","cn":"道路施工"},"pos":"noun"},{"en":"a place where things are made or industrial processes take place","cn":"工厂","g":"[countable + singular or plural verb]","sc":"factory","ex":{"en":"an engineering works","cn":"机器制造厂"},"pos":"noun"},{"en":"the moving parts of a machine, etc.","cn":"（机器等的）活动部件","g":"[plural]","sc":"parts of machine","pos":"noun"},{"en":"everything","cn":"所有的事物","g":"[plural]","lab":"informal","sc":"everything","ex":{"en":"We went to the chip shop and had the works: fish, chips, gherkins, mushy peas.","cn":"我们去薯条店吃了套餐：炸鱼、炸薯条、小黄瓜、豆泥。"},"pos":"noun"},{"en":"the use of force to produce movement","cn":"功；做功","g":"[uncountable]","sc":"physics","pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"工作;从业;就职","en":"People who work have a job, usually one which they are paid to do.","ex":{"en":"Weiner works for the US Department of Transport","cn":"韦纳就职于美国交通部。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"工作;职业","en":"People who have work or who are in work have a job, usually one which they are paid to do.","ex":{"en":"Fewer and fewer people are in work","cn":"就业人数越来越少。"}},{"pos":"VERB 动词","cn":"工作;劳动;干活","en":"When you work, you do the things that you are paid or required to do in your job.","ex":{"en":"I can't talk to you right now—I'm working","cn":"这会儿我不能跟你说话——我在干活儿。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"工作;活儿;活计","en":"Your work consists of the things you are paid or required to do in your job.","ex":{"en":"We're supposed to be running a business here. I've got work to do","cn":"我们在这里应该是要经营公司。我有一堆的事情要做。"}},{"pos":"VERB 动词","cn":"努力干;用功","en":"When you work, you spend time and effort doing a task that needs to be done or trying to achieve something.","ex":{"en":"Linda spends all her time working on the garden","cn":"琳达把所有时间都花在打理花园上。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"工作单位;工作地点","en":"Work is the place where you do your job.","ex":{"en":"Many people travel to work by car","cn":"很多人开车去上班。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"工作成果","en":"Work is something which you produce as a result of an activity or as a result of doing your job.","ex":{"en":"It can help to have an impartial third party look over your work","cn":"让客观公正的第三方看一下你的成果会有助益。"}},{"pos":"N-COUNT 可数名词","cn":"(艺术家、作家、作曲家等的)作品；著作","en":"A work is something such as a painting, book, or piece of music produced by an artist, writer, or composer.","ex":{"en":"In my opinion, this is Rembrandt's greatest work","cn":"我认为这是伦勃朗最伟大的作品。"}},{"pos":"VERB 动词","cn":"研究；对…作调查","en":"If someone is working on a particular subject or question, they are studying or researching it.","ex":{"en":"Professor Bonnet has been working for many years on molecules of this type.","cn":"邦尼特教授多年来一直在从事这种分子的研究工作。"}},{"pos":"VERB 动词","cn":"协助;帮助","en":"If you work with a person or a group of people, you spend time and effort trying to help them in some way.","ex":{"en":"She spent a period of time working with people dying of cancer","cn":"她有一段时间曾帮助垂危的癌症患者。"}},{"pos":"VERB 动词","cn":"(机器或设备)运转，运行","en":"If a machine or piece of equipment works, it operates and performs a particular function.","ex":{"en":"The pump doesn't work and we have no running water","cn":"水泵坏了，我们没有自来水了。"}},{"pos":"VERB 动词","cn":"奏效;成功","en":"If an idea, system, or way of doing something works, it is successful, effective, or satisfactory.","ex":{"en":"95 per cent of these diets do not work","cn":"这些节食方法95%都不起作用。"}},{"pos":"VERB 动词","cn":"(药物)起作用，产生疗效","en":"If a drug or medicine works, it produces a particular physical effect.","ex":{"en":"I wake at 6 am as the sleeping pill doesn't work for more than nine hours","cn":"安眠药的药效不会超过9个小时，所以我清晨6点就醒了。"}},{"pos":"VERB 动词","cn":"产生(有利或不利的)影响","en":"If something works in your favour, it helps you in some way. If something works to your disadvantage, it causes problems for you in some way.","ex":{"en":"One factor thought to have worked in his favour is his working class image","cn":"据认为，一个帮上了他的因素就是他的工人阶级形象。"}},{"pos":"VERB 动词","cn":"对…产生(神奇的影响);使…深受（魅力感染）","en":"If something or someone works their magic or works their charms on a person, they have a powerful positive effect on them.","ex":{"en":"Nevertheless, she is always optimistic about the possibilities and can work her charm on the disenchanted","cn":"虽然如此，她总是乐观地抱持希望，并能深深地感染那些心灰意冷的人。"}},{"pos":"VERB 动词","cn":"(脑筋)转动，开动","en":"If your mind or brain is working, you are thinking about something or trying to solve a problem.","ex":{"en":"My mind was working frantically, running over the events of the evening.","cn":"我的大脑疯狂地运转，把那晚发生的事情飞快地一幕幕重演。"}},{"pos":"VERB 动词","cn":"以(某种假定或思想)为基础(或前提)","en":"If you work on an assumption or idea, you act as if it were true or base other ideas on it, until you have more information.","ex":{"en":"We are working on the assumption that it was a gas explosion.","cn":"我们假设这是一场燃气爆炸事故。"}},{"pos":"VERB 动词","cn":"在(某地或某类场所)工作;在…奔波","en":"If you work a particular area or type of place, you travel around that area or work in those places as part of your job, for example trying to sell something there.","ex":{"en":"Brand has been working the clubs and the pubs since 1986, developing her comedy act","cn":"布兰德自1986年以来一直在俱乐部和酒吧表演，提高她的喜剧演技。"}},{"pos":"VERB 动词","cn":"让…干活；让…工作","en":"If you work someone, you make them spend time and effort doing a particular activity or job.","ex":{"en":"They're working me too hard. I'm too old for this","cn":"他们把我用得太狠了，我老了，干不了这种活儿啦。"}},{"pos":"VERB 动词","cn":"(常指政客或艺人)博得，赢得(众人的支持或欢心)","en":"If someone, often a politician or entertainer, works a crowd, they create a good relationship with the people in the crowd and get their support or interest.","ex":{"en":"The Prime Minister has an ability to work a crowd — some might even suggest it is a kind of charm","cn":"首相有种感召人群的本事——有些人甚至认为这是一种魅力。"}},{"pos":"VERB 动词","cn":"种，耕种(地)","en":"When people work the land, they do all the tasks involved in growing crops.","ex":{"en":"Farmers worked the fertile valleys.","cn":"农民们在肥沃的山谷里耕种。"}},{"pos":"VERB 动词","cn":"开采(矿)","en":"When a mine is worked, minerals such as coal or gold are removed from it.","ex":{"en":"The mines had first been worked in 1849, when gold was discovered in California","cn":"1849年加利福尼亚发现金矿时，这些矿第一次被开采。"}},{"pos":"VERB 动词","cn":"使用，操纵(机器或设备)","en":"If you work a machine or piece of equipment, you use or control it.","ex":{"en":"Many adults still depend on their children to work the video.","cn":"很多成年人仍然要靠孩子来操作录像机。"}},{"pos":"VERB 动词","cn":"慢慢变成;逐渐变得","en":"If something works into a particular state or condition, it gradually moves so that it is in that state or condition.","ex":{"en":"A screw had worked loose from my glasses.","cn":"我眼镜上有一个螺丝松了。"}},{"pos":"VERB 动词","cn":"按，压，揉(面团、黏土等)","en":"If you work a substance such as dough or clay, you keep pressing it to make it have a particular texture.","ex":{"en":"Work the dough with the palm of your hand until it is very smooth","cn":"用手掌将面团揉至光滑为止。"}},{"pos":"VERB 动词","cn":"加工;处理","en":"If you work a material such as metal, leather, or stone, you cut, sew, or shape it in order to make something or to create a design.","ex":{"en":"...the machines needed to extract and work the raw stone.","cn":"开采加工原石的机器"}},{"pos":"VERB 动词","cn":"使用，采用(某种材料或物质)","en":"If you work with a particular substance or material, you use it in order to make something or to create a design.","ex":{"en":"He studied sculpture because he enjoyed working with clay.","cn":"他学习雕塑是因为他喜欢玩黏土。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(身体某部分)活动","en":"If you work a part of your body, or if it works, you move it.","ex":{"en":"Each position will work the muscles in a different way","cn":"每种姿势都会以不同方式活动肌肉。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"工厂","en":"A works is a place where something is manufactured or where an industrial process is carried out. Works is used to refer to one or to more than one of these places.","ex":{"en":"The steel works could be seen for miles.","cn":"这个钢厂几英里外都能看见。"}},{"pos":"N-PLURAL 复数名词","cn":"土木工程;建筑工程","en":"Works are activities such as digging the ground or building on a large scale.","ex":{"en":"...six years of disruptive building works, road construction and urban development.","cn":"6年间进行的破坏性的建筑工程、道路修筑和城市扩建"}},{"pos":"N-SING 单数名词","cn":"(某种类型的)全部物件，全套物品","en":"You can say the works after listing things such as someone's possessions or requirements, to emphasize that they possess or require everything you can think of in a particular category.","ex":{"en":"Amazing place he's got there—squash courts, swimming pool, jacuzzi, the works.","cn":"他的那个地方真是太棒了——壁球场、游泳池、按摩浴池，一应俱全。"}},{"pos":"PHRASE 短语","cn":"干活儿;做工作;忙着做事","en":"If someone is at work they are doing their job or are busy doing a particular activity.","ex":{"en":"The salvage teams are already hard at work trying to deal with the spilled oil","cn":"救援队已经在紧张地设法处理溢出的石油。"}},{"pos":"PHRASE 短语","cn":"起作用;发挥效用","en":"If a force or process is at work, it is having a particular influence or effect.","ex":{"en":"The report suggested that the same trend was at work in politics","cn":"这份报告表明，同一趋势也在影响着政治。"}},{"pos":"PHRASE 短语","cn":"(做…)有很大困难，困难重重","en":"If you say that you will have your work cut out to do something, you mean that it will be a very difficult task.","ex":{"en":"The new administration has its work cut out for it. Creating jobs in this kind of environment is not going to be easy","cn":"新一届政府面临重重困难。在这种环境下创造就业机会绝非易事。"}},{"pos":"PHRASE 短语","cn":"已列入计划;已开始","en":"If something is in the works, it has already been planned or begun.","ex":{"en":"He said there were dozens of economic plans in the works","cn":"他说有几十项经济计划已经开始实施。"}},{"pos":"PHRASE 短语","cn":"（费力或轻而易举地）做，完成","en":"You can use work to talk about how easily or quickly a particular task is done. For example, if a person or thing makes short work of doing something or makes light work of it, they do it quickly and easily.","ex":{"en":"An aerosol spray will make short work of painting awkward objects","cn":"用喷罐来喷涂，不好对付的物品也能轻松搞定。"}},{"pos":"PHRASE 短语","cn":"讨厌鬼;恶棍","en":"If you describe someone as a nasty piece of work, you think they are very unpleasant or cruel.","ex":{"en":"Underneath I think he's actually a rather nasty piece of work.","cn":"内心里我觉得他是个非常讨厌的家伙。"}},{"pos":"PHRASE 短语","cn":"让…工作;派给…任务","en":"If you put someone to work or set them to work, you give them a job or task to do.","ex":{"en":"By stimulating the economy, we're going to put people to work","cn":"我们将通过刺激经济让人们实现就业。"}},{"pos":"PHRASE短语","cn":"开始做;着手处理","en":"If you get to work ,go to work, or set to work on a job, task, or problem, you start doing it or dealing with it.","ex":{"en":"He promised to get to work on the state's massive deficit","cn":"他承诺着手解决国家庞大的财政赤字问题。"}},{"pos":"PHRASE 短语","cn":"艰难地移动；缓慢地取得进展","en":"If you work your way somewhere, you move or progress there slowly, and with a lot of effort or work.","ex":{"en":"Rescuers were still working their way towards the trapped men","cn":"营救人员仍在艰难地向被困者靠拢。"}},{"pos":"CONVENTION 惯用语","cn":"干得不错;干得漂亮","en":"You can say to someone 'nice work' or 'good work' in order to thank or praise them for doing something well or quickly.","ex":{"en":"Nice work, Matthew. I knew you could do it.","cn":"干得好，马修。我知道你能行。"}},{"pos":"","cn":"","en":"to throw a spanner in the works→see: ;"},{"pos":"","cn":"","en":"相关词组：work in work off work out work over work up"}]},"examples":[{"en":"You can work miracles with very little money if you follow our home decoration tips.","cn":"你要是按照我们的家居装饰诀窍行事，可以用很少的钱就产生奇妙的效果。"},{"en":"‘Have you sorted out a babysitter yet?’ ‘No, but I'm working on it. ’ “","cn":"你找到临时看孩子的保母了吗？” “还没有，我正在找呢。”"}]},"workshops":{"oxford":{"phon":"ˈwɜːkʃɒp","pos":"noun","senses":[{"en":"a room or building in which things are made or repaired using tools or machinery","cn":"车间；工场；作坊"},{"en":"a period of discussion and practical work on a particular subject, in which a group of people share their knowledge and experience","cn":"研讨会；讲习班"}]}},"workshop":{"oxford":{"phon":"ˈwɜːkʃɒp","pos":"noun","senses":[{"en":"a period of discussion and practical work on a particular subject, in which a group of people share their knowledge and experience","cn":"研讨会；讲习班","lab":"British English","ex":{"en":"There will be the opportunity for practical theatre work in drama workshops.","cn":"戏剧研习班将提供实际戏剧工作的机会。"}},{"en":"a room or building in which things are made or repaired using tools or machines","cn":"车间；工场；作坊","ex":{"en":"The craftsmen worked in a freezing cold workshop.","cn":"工匠在极度寒冷的作坊里干活儿。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"研习班;研讨会","en":"A workshop is a period of discussion or practical work on a particular subject in which a group of people share their knowledge or experience.","ex":{"en":"Trumpeter Marcus Belgrave ran a jazz workshop for young artists","cn":"小号手马库斯·贝尔格雷夫为年轻艺术家办了一个爵士乐研习班。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指使用到木材或金属的)车间，工场，作坊","en":"A workshop is a building which contains tools or machinery for making or repairing things, especially using wood or metal.","ex":{"en":"...a modestly equipped workshop.","cn":"设备简陋的车间"}}]},"media":{"uk":"media/uk/workshop__gb_1.mp3","us":"media/us/workshop__us_1.mp3"},"examples":[{"en":"a drama workshop","cn":"戏剧研讨班"},{"en":"a poetry workshop","cn":"诗歌讲习班"}]},"woodwind":{"oxford":{"phon":"ˈwʊdwɪnd","pos":"noun","senses":[{"en":"the group of musical instruments in an orchestra that are traditionally made of wood and are played by blowing. Flutes, clarinets and bassoons are all woodwind instruments.","cn":"（管弦乐团的）木管乐器，木管乐器组","ex":{"en":"the woodwind section of the orchestra","cn":"管弦乐队的木管乐器组"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"木管乐器","en":"Woodwind instruments are musical instruments such as flutes, clarinets, and recorders that you play by blowing into them."}]},"media":{"img":["media/pic/woodwind_musicalinstruments_comp.jpg","media/thumb/clarinet.jpg"],"uk":"media/uk/woodwind__gb_1.mp3","us":"media/us/woodwind__us_1.mp3"},"examples":[{"en":"the woodwind section of the orchestra","cn":"管弦乐队的木管乐器组"},{"en":"woodwind instruments such as the flute or saxophone","cn":"木管乐器﹐如长笛和萨克斯管"}]},"woodland":{"media":{"uk":"media/uk/woodland__gb_1.mp3","us":"media/us/woodland__us_1.mp3"},"oxford":{"phon":"ˈwʊdlənd","pos":"noun","senses":[{"en":"an area of land that is covered with trees","cn":"树林；林地；林区","ex":{"en":"ancient woodland","cn":"原始林区"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"林地;林区","en":"Woodland is land with a lot of trees."}]},"examples":[{"en":"The house is fringed by fields and woodlands.","cn":"这房子的周围是田地和树林。"},{"en":"ancient woodland","cn":"原始林区"}]},"worldwide":{"oxford":{"phon":"ˌwɜːldˈwaɪd","pos":"adjective, adverb","senses":[{"en":"affecting all parts of the world","cn":"影响全世界的；世界各地的","ex":{"en":"an increase in worldwide sales","cn":"全球销售额的增长"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"遍及全世界地;世界各地地","en":"If something exists or happens worldwide, it exists or happens throughout the world.","ex":{"en":"His books have sold more than 20 million copies worldwide","cn":"他的书在全世界已经售出两千多万本。"}}]},"media":{"uk":"media/uk/worldwide__gb_1.mp3","us":"media/us/worldwide__us_1.mp3"},"examples":[{"en":"We have 2 000 members worldwide.","cn":"我们在全世界有 2 000 名成员。"},{"en":"The story has attracted worldwide attention.","cn":"这件事已经引起了全世界的关注。"}]},"would":{"media":{"uk":"media/uk/would__gb_3.mp3","us":"media/us/would__us_3.mp3"},"oxford":{"phon":"wʊd","pos":"modal verb","senses":[{"en":"used in polite offers or invitations","cn":"（客气地建议或邀请）","ex":{"en":"Would you like a sandwich?","cn":"您来一个三明治好吗？"}},{"en":"used to say what you like, love, hate, etc.","cn":"（表示愿意、喜欢、不愿意等）","ex":{"en":"I'd love a coffee.","cn":"我想喝杯咖啡。"}},{"en":"used as the past form of will when reporting what somebody has said or thought","cn":"（will 的过去式，用于转述）将，将会","ex":{"en":"He said he would be here at eight o'clock (= His words were: ‘I will be there at eight o'clock.’).","cn":"他说他将在八点钟到达这里。"}},{"en":"used for talking about the result of an event that you imagine","cn":"（带出想象的结果）","ex":{"en":"She'd look better with shorter hair.","cn":"她留短发会显得好看些。"}},{"en":"used for describing a possible action or event that did not in fact happen, because something else did not happen first","cn":"（表示可能发生的事情没有发生，是因为之前另一件事没有发生）就会","ex":{"en":"If I had seen the advertisement in time, I would have applied for the job.","cn":"我要是及时看到了这则广告，我就应聘那份工作了。"}},{"en":"used for saying why somebody does something","cn":"（说明动机）","ex":{"en":"She burned the letters so that her husband would never read them.","cn":"她把那些信都烧了以便永远不让她丈夫看见。"}},{"en":"used for saying what you want to happen","cn":"（表达愿望）会，将会","ex":{"en":"I wish that you'd be quiet for a minute.","cn":"我希望你安静一会儿。"}},{"en":"used to show that somebody/something was not willing or refused to do something","cn":"（表示不愿意）","ex":{"en":"She wouldn't change it, even though she knew it was wrong.","cn":"尽管她知道这错了，她也不肯改变。"}},{"en":"used to ask somebody politely to do something","cn":"（客气地请求）","ex":{"en":"Would you mind leaving us alone for a few minutes?","cn":"你不介意让我们单独待一会儿吧？"}},{"en":"used to give opinions that you are not certain about","cn":"（提出拿不准的看法）","ex":{"en":"I would imagine the job will take about two days.","cn":"我猜想这工作大概需要两天左右的时间吧。"}},{"en":"used to give advice","cn":"（提出忠告）","ex":{"en":"I wouldn't have any more to drink, if I were you.","cn":"我要是你的话，我就不会再喝酒了。"}},{"en":"used for talking about things that often happened in the past","cn":"（带出过去常见的情况）总是，老是","ex":{"en":"When my parents were away, my grandmother would take care of me.","cn":"我父母外出的时候，总是祖母照看我。"}},{"en":"used for talking about behaviour that you think is typical","cn":"（带出一贯的行为）总是，爱，好，就","lab":"usually disapproving","ex":{"en":"‘She said it was your fault.’ ‘Well, she would say that, wouldn't she? She's never liked me.’","cn":"“她说这是你的错。”“唉，她总是这么说，不是吗？她从来就没有喜欢过我。”"}},{"en":"used to express a strong wish","cn":"（用以表示强烈的愿望）","lab":"literary","ex":{"en":"Would that he had lived to see it.","cn":"他要是能活到看见这该多好哇。"}}]},"collins":{"senses":[{"pos":"MODAL 情态动词","cn":"(表示曾经相信、希望或期待)将，将会","en":"You use would when you are saying what someone believed, hoped, or expected to happen or be the case.","ex":{"en":"No one believed he would actually kill himself","cn":"没有人相信他真的会自杀。"}},{"pos":"MODAL 情态动词","cn":"(表示曾经打算)将，将会","en":"You use would when saying what someone intended to do.","ex":{"en":"The statement added that although there were a number of differing views, these would be discussed by both sides","cn":"这项声明还称，虽然双方观点存在若干分歧，但将就这些分歧展开讨论。"}},{"pos":"MODAL 情态动词","cn":"(表示可能出现的情况的结果或影响)会，将会","en":"You use would when you are referring to the result or effect of a possible situation.","ex":{"en":"Ordinarily it would be fun to be taken to fabulous restaurants","cn":"一般来说，跟别人去豪华餐馆吃饭会是件乐事。"}},{"pos":"MODAL 情态动词","cn":"(would 或 would have 与过去分词连用，表示有充分理由认为或猜测是某种情况)肯定，一定，应该","en":"You use would, or would have with a past participle, to indicate that you are assuming or guessing that something is true, because you have good reasons for thinking it.","ex":{"en":"You wouldn't know him","cn":"你肯定不认识他。"}},{"pos":"MODAL 情态动词","cn":"(用于if，unless等引导的条件状语从句的主句，表示认为某事不大可能发生)就，该","en":"You use would in the main clause of some 'if' and 'unless' sentences to indicate something you consider to be fairly unlikely to happen.","ex":{"en":"If only I could get some sleep, I would be able to cope","cn":"要是我能睡会儿，我就能够应付。"}},{"pos":"MODAL 情态动词","cn":"肯;愿意","en":"You use would to say that someone was willing to do something. You use would not to indicate that they refused to do something.","ex":{"en":"They said they would give the police their full cooperation","cn":"他们说他们愿意与警方通力合作。"}},{"pos":"MODAL 情态动词","cn":"(表示尽管付出很大努力却没有发生)就(不)，偏(不)","en":"You use would not to indicate that something did not happen, often in spite of a lot of effort.","ex":{"en":"He kicked, pushed, and hurled his shoulder at the door. It wouldn't open","cn":"他冲着门又踢又推，还用肩膀撞，但门就是打不开。"}},{"pos":"MODAL 情态动词","cn":"(尤与like, love 和 wish 连用，表示想做某事或拥有某物，或希望某事发生)要，会","en":"You use would, especially with 'like', 'love', and 'wish', when saying that someone wants to do or have a particular thing or wants a particular thing to happen. would rather→see: ;","ex":{"en":"She asked me what I would like to do and mentioned a particular job","cn":"她问我想干什么，然后提到了一份工作。"}},{"pos":"MODAL 情态动词","cn":"(用于带if从句的疑问句中，表示请求许可做某事)会","en":"You use would with 'if' clauses in questions when you are asking for permission to do something.","ex":{"en":"Do you think it would be all right if I smoked?","cn":"我可以抽烟吗？"}},{"pos":"MODAL 情态动词","cn":"(通常在疑问句中与 like 连用，表示礼貌地给予或邀请)","en":"You use would, usually in questions with 'like', when you are making a polite offer or invitation.","ex":{"en":"Would you like a drink?","cn":"想喝一杯吗?"}},{"pos":"MODAL 情态动词","cn":"(通常用于疑问句中，表示礼貌地请求某人做某事)请","en":"You use would, usually in questions, when you are politely asking someone to do something.","ex":{"en":"Would you do me a favour and get rid of this letter I've just received?","cn":"请帮个忙把我刚刚收到的这封信处理掉行吗?"}},{"pos":"MODAL 情态动词","cn":"(用于批评，表示对某人做某事并不感到意外，此时 would 须重读)","en":"You say that someone would do something when it is typical of them and you are critical of it. You emphasize the word would when you use it in this way.","ex":{"en":"Well, you would say that: you're a man","cn":"呵，你当然会这样说的，因为你是个男的。"}},{"pos":"MODAL 情态动词","cn":"(would 或 would have 与过去分词连用，表示发表看法或了解他人是否赞同自己的看法，尤用于对自己的话没有把握时)","en":"You use would, or sometimes would have with a past participle, when you are expressing your opinion about something or seeing if people agree with you, especially when you are uncertain about what you are saying.","ex":{"en":"I think you'd agree he's a very respected columnist","cn":"我想你得承认他是个备受尊敬的专栏作家。"}},{"pos":"MODAL 情态动词","cn":"(用于以随便的口气向人提出建议)我(就)会","en":"You use I would when you are giving someone advice in an informal way.","ex":{"en":"If I were you I would simply ring your friend's bell and ask for your bike back","cn":"如果我是你,我就会直接去按你朋友的门铃, 把自行车要回来。"}},{"pos":"MODAL 情态动词","cn":"(用于否定句，与 guess, know 等动词连用，表示某事不明显，尤用于某事令人吃惊时)","en":"You use you would in negative sentences with verbs such as 'guess' and 'know' when you want to say that something is not obvious, especially something surprising.","ex":{"en":"Chris is so full of artistic temperament you'd never think she was the daughter of a banker","cn":"克丽丝极富艺术气质，你根本想不到她是银行家的女儿。"}},{"pos":"MODAL 情态动词","cn":"(表示某事过去惯常发生, 而现在不再发生了)就，会","en":"You use would to talk about something which happened regularly in the past but which no longer happens.","ex":{"en":"Sunday mornings my mother would bake. I'd stand by the fridge and help","cn":"星期天早晨，妈妈会烤面包，我就站在冰箱旁帮忙。"}},{"pos":"MODAL 情态动词","cn":"(would have 与过去分词连用，表示某个时间前可能发生的事情)就，会","en":"You use would have with a past participle when you are saying what was likely to have happened by a particular time.","ex":{"en":"Within ten weeks of the introduction, 34 million people would have been reached by our television commercials.","cn":"在推出10周之内，可能会有3,400万人看到我们的电视广告。"}},{"pos":"MODAL 情态动词","cn":"(would have 与过去分词连用，表示过去可能发生的事情的结果或影响)就，会","en":"You use would have with a past participle when you are referring to the result or effect of a possible event in the past.","ex":{"en":"My daughter would have been 17 this week if she had lived","cn":"我女儿要是还活着的话，这周就17岁了。"}},{"pos":"MODAL 情态动词","cn":"原想;本来想","en":"If you say that someone would have liked or preferred something, you mean that they wanted to do it or have it but were unable to.","ex":{"en":"I would have liked a life in politics","cn":"我本想从政的。"}},{"pos":"MODAL 情态动词","cn":"(通常用于否定句，批评某人所为，表示不满)（不）会","en":"You use would, usually in negative sentences, to criticize something that someone has done and to express your disapproval of it.","ex":{"en":"I would never have done what they did.","cn":"他们做的事情我是决不会做的。"}},{"pos":"PHRASE 短语","cn":"但愿","en":"If you say 'would that' something were the case, you are saying that you wish it were the case.","ex":{"en":"Would that he could have listened to his father.","cn":"他要是听了他父亲的话就好了。"}}]},"examples":[{"en":"‘She said it was your fault.’ ‘Well, she would say that, wouldn't she? She's never liked me.’ “","cn":"她说这是你的错。” “唉，她总是这么说，不是吗？她从来就没有喜欢过我。”"},{"en":"If I had seen the advertisement in time I would have applied for the job.","cn":"我要是及时看到了这则广告，我就应聘那份工作了。"}]},"would-be":{"oxford":{"phon":"ˈwʊd biː","pos":"adjective","senses":[{"en":"used to describe somebody who is hoping to become the type of person mentioned","cn":"（形容想要成为…的人）未来的","ex":{"en":"a would-be actor","cn":"想要成为演员的人"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"想要成为…的","en":"You can use would-be to describe someone who wants or attempts to do a particular thing. For example, a would-be writer is someone who wants to be a writer.","ex":{"en":"...a book that provides encouragement for would-be writers who cannot get their novel into print.","cn":"一本勉励想成为作家却不能将小说付梓者的书"}}]},"media":{"uk":"media/uk/would_be_1_gb_1.mp3","us":"media/us/would_be_1_us_1.mp3"},"examples":[{"en":"advice for would-be parents","cn":"对即将成为父母的人的忠告"},{"en":"a would-be actor","cn":"想要成为演员的人"}]},"word":{"media":{"uk":"media/uk/word__gb_1.mp3","us":"media/us/word__us_1.mp3"},"oxford":{"phon":"wɜːd","pos":"noun","senses":[{"en":"a single unit of language that means something and can be spoken or written","cn":"单词；词；字","g":"[countable]","sc":"unit of language","ex":{"en":"Do not write more than 200 words.","cn":"写的东西不要超过 200 字。"}},{"en":"a thing that you say; a remark or statement","cn":"说的话；话语；言语","g":"[countable]","lab":"British English","sc":"something you say","ex":{"en":"Have a word with Pat and see what she thinks.","cn":"和帕特谈一谈，看她是怎么想的。"}},{"en":"a promise or guarantee that you will do something or that something will happen or is true","cn":"诺言；许诺；保证","g":"[singular]","sc":"promise","ex":{"en":"I give you my word that this won't happen again.","cn":"我向你保证这种事不会再次发生。"}},{"en":"a piece of information or news","cn":"信息；消息","g":"[singular]","sc":"information/news","ex":{"en":"There's been no word from them since before Christmas.","cn":"自圣诞节前就一直没有他们的消息。"}},{"en":"the Bible and its teachings","cn":"《圣经》；福音","g":"[singular]","sc":"Bible"},{"en":"to write or say something using particular words","cn":"措辞；用词","ex":{"en":"How was the letter worded (= what did it say exactly)?","cn":"这封信到底写了些什么？"},"pos":"verb"},{"en":"used to show that you accept or agree with what somebody has just said","cn":"（表示接受或同意别人刚说的话）就是，说得对","pos":"exclamation"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"单词;字","en":"A word is a single unit of language that can be represented in writing or speech. In English, a word has a space on either side of it when it is written.","ex":{"en":"The words stood out clearly on the page","cn":"那些字赫然写在纸上。"}},{"pos":"N-PLURAL 复数名词","cn":"话;话语;所写的文字","en":"Someone's words are what they say or write.","ex":{"en":"I was devastated when her words came true","cn":"她的话应验了，我伤心欲绝。"}},{"pos":"N-PLURAL 复数名词","cn":"歌词;唱词","en":"The words of a song consist of the text that is sung, in contrast to the music that is played.","ex":{"en":"Can you hear the words on the album?","cn":"你听得清这张专辑中的歌词吗？"}},{"pos":"N-SING 单数名词","cn":"短时间的谈话;短暂的聊天","en":"If you have a word with someone, you have a short conversation with them.","ex":{"en":"I think it's time you had a word with him","cn":"我觉得你该跟他谈谈了。"}},{"pos":"N-COUNT 可数名词","cn":"(警告、建议、赞扬的)话，话语","en":"If you offer someone a word of something such as warning, advice, or praise, you warn, advise, or praise them.","ex":{"en":"A word of warning. Don't stick too precisely to what it says in the book","cn":"提醒一句：不要过于迷信书上的话。"}},{"pos":"N-SING 单数名词","cn":"一句话，一个字(也没有听到、明白或说)","en":"If you say that someone does not hear, understand, or say a word, you are emphasizing that they hear, understand, or say nothing at all.","ex":{"en":"I can't understand a word she says","cn":"她说的我一点儿也不懂。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"消息;信息","en":"If there is word of something, people receive news or information about it.","ex":{"en":"There is no word from the authorities on the reported attack","cn":"所报道的袭击事件没有得到当局的证实。"}},{"pos":"N-SING 单数名词","cn":"誓言;诺言","en":"If you give your word, you make a sincere promise to someone.","ex":{"en":"...an adult who gave his word the boy would be supervised","cn":"一位承诺监护这个男孩的成年男子"}},{"pos":"N-SING 单数名词","cn":"命令;指示","en":"If someone gives the word to do something, they give an order to do it.","ex":{"en":"I want nothing said about this until I give the word.","cn":"没有我的命令，不准议论这件事。"}},{"pos":"VERB 动词","cn":"措辞表达;用词表达","en":"To word something in a particular way means to choose or use particular words to express it.","ex":{"en":"If I had written the letter, I might have worded it differently.","cn":"如果换作我写这封信，我或许会用不同的措辞。"}},{"pos":"PHRASE 短语","cn":"脏字；粗鄙的字眼","en":"If you say that people consider something to be a dirty word, you mean that they disapprove of it.","ex":{"en":"So many people think feminism is a dirty word.","cn":"这么多人都认为女权主义是个龌龊的字眼。"}},{"pos":"PHRASE 短语","cn":"收回前言，承认说错了话(尤指此举令说话人显得愚蠢时)","en":"If you say that someone has to eat their words, you mean that they have to admit that they were wrong about something they said in the past, especially when this makes them look foolish.","ex":{"en":"He has had to eat his words about the company being recession-proof.","cn":"他不得不收回他说过的公司能免受经济衰退影响的话。"}},{"pos":"PHRASE 短语","cn":"沉默寡言的，少言寡语的，话不多的(尤指不谈及自己的意见和感情)","en":"A person of few words says very little, especially about their opinions or feelings.","ex":{"en":"He's a man of few words, very polite and unassuming.","cn":"他是个沉默寡言的人，彬彬有礼，待人谦和。"}},{"pos":"PHRASE 短语","cn":"从一开始","en":"If you do something from the word go, you do it from the very beginning of a period of time or situation.","ex":{"en":"It's essential you make the right decisions from the word go.","cn":"关键是从一开始就作出正确的决定。"}},{"pos":"PHRASE 短语","cn":"(因为仰慕或尊敬而)仔细倾听，一字不落地认真听","en":"If you hang on someone's every word, you listen very carefully to what they are saying, because you admire or respect them.","ex":{"en":"Melina was hanging on his every word, fascinated.","cn":"梅利娜凝神细听着他的每句话，被深深吸引住了。"}},{"pos":"PHRASE 短语","cn":"从来没一句好话／从来没一句坏话","en":"You can use expressions such as never have a good word to say or never have a bad word to say to emphasize that a person always criticizes someone or something, or that they never criticize them.","ex":{"en":"The press never has a good word to say about them","cn":"新闻界从来没说过他们的好话。"}},{"pos":"PHR-RECIP 相互短语","cn":"(尤指因为一方抱怨了另一方的行为)与…争论,与…严肃讨论","en":"If one person has words with another, or if two or more people have words, they have a serious discussion or argument, especially because one has complained about the other's behaviour.","ex":{"en":"We had words and she stormed out","cn":"我们争执了起来，她夺门而出。"}},{"pos":"PHRASE 短语","cn":"用…的话说;引用…的原话说","en":"You can use in their words or in their own words to indicate that you are reporting what someone said using the exact words that they used.","ex":{"en":"Even the Assistant Secretary of State had to admit that previous policy did not, in his words, produce results.","cn":"就连助理国务卿也不得不承认之前的政策并没有，用他的话说，收到成效。"}},{"pos":"PHRASE 短语","cn":"总而言之;简言之;一句话","en":"You use in a word to indicate that you are giving a summary of what you have just been saying, or are giving a reply, in as brief a way as possible.","ex":{"en":"Victor, in a word, got increasingly fed up","cn":"总而言之，维克多越来越厌倦了。"}},{"pos":"PHRASE 短语","cn":"(讨论、争论、分歧中的)最终决定权","en":"If someone has the last word or the final word in a discussion, argument, or disagreement, they are the one who wins it or who makes the final decision.","ex":{"en":"She does like to have the last word in any discussion","cn":"她确实喜欢商量什么事都最终自己说了算。"}},{"pos":"PHRASE 短语","cn":"(在奢侈、舒适等方面的)极致","en":"If you say that something is the last word in luxury, comfort, or some other quality, you are emphasizing that it has a great deal of this quality.","ex":{"en":"The spa is the last word in luxury and efficiency.","cn":"这家矿泉疗养浴场极尽奢华，功效极高。"}},{"pos":"PHRASE 短语","cn":"(尤指因非常吃惊而)说不出话来，无以言表","en":"If someone is lost for words, they cannot think of anything to say, especially because they are very surprised by something.","ex":{"en":"I'm lost for words — it's fantastic","cn":"我无以言表——太精彩了。"}},{"pos":"PHRASE 短语","cn":"没有直接说;拐弯抹角地说","en":"If you say that someone has said something, but not in so many words, you mean that they said it or expressed it, but in a very indirect way.","ex":{"en":"'And has she agreed to go with you?' — 'Not in so many words. But I read her thoughts'.","cn":"“她同意跟你一起去了吗？”——“没有直接说，但我知道她是怎么想的。”"}},{"pos":"PHRASE 短语","cn":"(用于强调刚刚警告对方的话很可能成真，尤其是认为对方应改变态度或行为予以避免时)你听着，记住我的话","en":"If you say 'mark my words' to someone, you are emphasizing that something you have just warned them about is very likely to happen, especially when you think they should change their attitude or behaviour to prevent it.","ex":{"en":"That's what you'll end up with, you mark my words.","cn":"那就是将来你的下场，记住我的话。"}},{"pos":"PHRASE 短语","cn":"(由)口头","en":"If news or information passes by word of mouth, people tell it to each other rather than it being printed in written form.","ex":{"en":"The story has been passed down by word of mouth.","cn":"这个故事是口头流传下来的。"}},{"pos":"PHRASE 短语","cn":"硬说…说过某些话","en":"If you say that someone is putting words into your mouth or is putting words in your mouth, you mean that they are suggesting that you mean one thing when you really mean something different."},{"pos":"PHRASE 短语","cn":"说话算数的人;一诺千金的人","en":"If you refer to someone as a man of his word or a woman of her word, you mean that they always keep their promises and can be relied on."},{"pos":"PHRASE 短语","cn":"换言之;换句话说;也就是说","en":"You say in other words in order to introduce a different, and usually simpler, explanation or interpretation of something that has just been said.","ex":{"en":"The mobile library services have been reorganised — in other words, they visit fewer places.","cn":"流动图书馆服务重新作了安排——换句话说，他们去的地方减少了。"}},{"pos":"PHRASE 短语","cn":"用…自己的话说","en":"If you say something in your own words, you express it in your own way, without copying or repeating someone else's description.","ex":{"en":"Now tell us in your own words about the events of Saturday.","cn":"现在你来给我们讲讲星期六的活动吧。"}},{"pos":"PHRASE 短语","cn":"传话;递话","en":"If you pass the word, you tell someone something that another person has told you.","ex":{"en":"Friends passed the word that the miners wanted to see him.","cn":"朋友们传话说矿工们想见他。"}},{"pos":"PHRASE 短语","cn":"发话，下令(示意某事应该开始)","en":"If someone says the word, they give their approval as a sign that something should start to happen.","ex":{"en":"When I say the word, follow me down.","cn":"我一发话，就跟着我下来。"}},{"pos":"PHRASE 短语","cn":"散布消息;传播消息","en":"If you spread the word, you tell people about something.","ex":{"en":"The community reacted quickly and spread the word about safe sex.","cn":"社区迅速作出反应，宣传安全性行为。"}},{"pos":"PHRASE 短语","cn":"对…说的话信以为真","en":"If you take someone at their word, you believe what they say, when they did not really mean it or when they meant something slightly different.","ex":{"en":"They're willing to take him at his word when he says, 'Oh, I made mistakes and now I'll change.'","cn":"只要他说“哦，我错了，现在我要改过自新”，他们就愿意当真。"}},{"pos":"PHRASE 短语","cn":"相信…的话;…说的是真话","en":"If you say to someone 'take my word for it', you mean that they should believe you because you are telling the truth.","ex":{"en":"You'll buy nothing but trouble if you buy that house, take my word for it.","cn":"你要是买那栋房子只会买来麻烦，我说的都是真的。"}},{"pos":"PHRASE 短语","cn":"极其愚蠢/荒唐得让人无语","en":"You can use expressions such as too silly for words and too ridiculous for words to emphasize that someone or something is extremely silly or ridiculous.","ex":{"en":"It's too stupid for words not having the machines switched on when they're most needed","cn":"最需要这些机器时却不打开，真是愚蠢至极。"}},{"pos":"PHRASE 短语","cn":"信守诺言;说话算话;说到做到","en":"If you are true to your word or as good as your word, you do what you say you will do.","ex":{"en":"How do I know that he will be true to his word?","cn":"我怎么知道他会信守诺言呢？"}},{"pos":"PHRASE 短语","cn":"逐字;一字不差地","en":"If you repeat something word for word, you repeat it exactly as it was originally said or written.","ex":{"en":"I don't try to memorize speeches word for word.","cn":"我不会试图一字不落地记住讲话要说的内容。"}},{"pos":"","cn":"","en":"not get a word in edgeways→see: ; not mince your words→see: ; the operative word→see: ; actions speak louder than words→see: ; war of words→see: ;"}]},"examples":[{"en":"Who coined the phrase ‘desktop publishing’?","cn":"谁创造了 desktop publishing（桌面出版）这个词组？"},{"en":"‘Let the cat out of the bag’ is an idiom meaning to tell a secret by mistake. * let the cat out of the bag（","cn":"让猫从袋子里跑出来）为成语，意为无意中泄露秘密。"}]},"worryingly":{"oxford":{"phon":"ˈwʌriɪŋli","pos":"adverb","senses":[{"en":"in a way or to a degree that makes you worry","cn":"令人担忧的；令人发愁的","ex":{"en":"worryingly high levels of radiation","cn":"令人担忧的强辐射"}}]},"media":{"uk":"media/uk/worryingly__gb_1.mp3","us":"media/us/worryingly__us_1.mp3"},"examples":[{"en":"Worryingly, the plan contains few details on how spending will be cut.","cn":"令人担忧的是，这项计划中有关如何削减开支的细则很少。"},{"en":"worryingly high levels of radiation","cn":"令人担忧的强辐射"}]},"worse":{"media":{"uk":"media/uk/worse__gb_1.mp3","us":"media/us/worse__us_1.mp3"},"oxford":{"phon":"wɜːs","pos":"adjective","senses":[{"en":"of poorer quality or lower standard; more unpleasant","cn":"更差的；更糟的；更坏的","ex":{"en":"The rooms were awful and the food was worse.","cn":"房间很糟糕，吃的更差。"}},{"en":"more serious or severe","cn":"更严重的；更严厉的","ex":{"en":"They were trying to prevent an even worse tragedy.","cn":"他们正在设法避免更大的悲剧发生。"}},{"en":"more ill or unhappy","cn":"病情更重；健康恶化；更不愉快","g":"[not before noun]","ex":{"en":"If he gets any worse, we'll call the doctor.","cn":"要是他的病情恶化，我们就请医生。"}},{"en":"less well","cn":"更坏；更差；更糟","ex":{"en":"Working-class children fared rather worse.","cn":"工人阶级的孩子的情况则更糟。"},"pos":"adverb"},{"en":"more seriously or severely","cn":"更严重；更厉害","ex":{"en":"It's raining worse than ever.","cn":"雨下得比以往都大。"},"pos":"adverb"},{"en":"used to introduce a statement about something that is more serious or unpleasant than things already mentioned","cn":"更糟的是；更倒霉的是","ex":{"en":"She'd lost her job. Even worse, she'd lost her house and her children, too.","cn":"她丢了工作。更倒霉的是，她还失去了房子和孩子。"},"pos":"adverb"},{"en":"more problems or bad news","cn":"更多的问题；更坏的消息","ex":{"en":"I'm afraid there is worse to come.","cn":"恐怕更糟的还在后头呢。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"","cn":"(bad 的比较级)","en":"Worse is the comparative of bad ."},{"pos":"","cn":"(badly 的比较级)","en":"Worse is the comparative of badly ."},{"pos":"","cn":"(用于构成以 bad 和 badly 开头的复合形容词的比较级，如 badly off 的比较级是 worse off )","en":"Worse is used to form the comparative of compound adjectives beginning with 'bad' and 'badly.' For example, the comparative of 'badly off' is 'worse off'."},{"pos":"PHRASE 短语","cn":"越来越糟;每况愈下","en":"If a situation goes from bad to worse, it becomes even more unpleasant or unsatisfactory.","ex":{"en":"For the past couple of years my life has gone from bad to worse.","cn":"过去几年来，我的生活每况愈下。"}},{"pos":"PHRASE 短语","cn":"不妨(做某事);(做某事)不失明智之举","en":"If you tell someone that they could do worse than do a particular thing, you are advising them that it would be quite a good thing to do.","ex":{"en":"Scientists in search of a challenging career could do worse than consider forensic science.","cn":"寻求富有挑战性的事业的科学家不妨考虑一下法医学。"}},{"pos":"PHRASE 短语","cn":"向着更坏(或更糟的)情况(转变)","en":"If a situation changes for the worse, it becomes more unpleasant or more difficult.","ex":{"en":"The grandparents sigh and say how things have changed for the worse.","cn":"爷爷奶奶叹着气说情况变得如何如何糟糕。"}},{"pos":"PHRASE 短语","cn":"受到/未受到…的伤害(或不良影响)","en":"If a person or thing is the worse for something, they have been harmed or badly affected by it. If they are none the worse for it, they have not been harmed or badly affected by it.","ex":{"en":"Father came home from the pub very much the worse for drink","cn":"父亲从酒吧回到家里，乱撒酒疯。"}},{"pos":"","cn":"","en":"for better or worse→see: ;"}]},"examples":[{"en":"The increase in taxes means that we'll be £30 a month worse off than before.","cn":"税收的增加意味着我们将比以前每月少挣 30 英镑。"},{"en":"If you want a safe investment, you could do a lot worse than put your money in a building society.","cn":"你要想投资而不冒风险，倒不如把钱存到房屋互助协会。"}]},"worry":{"media":{"uk":"media/uk/worry__gb_1.mp3","us":"media/us/worry__us_1.mp3"},"oxford":{"phon":"ˈwʌri","pos":"verb","senses":[{"en":"to keep thinking about unpleasant things that might happen or about problems that you have","cn":"担心；担忧；发愁","g":"[intransitive]","ex":{"en":"Don't worry. We have plenty of time.","cn":"不必担心。我们有很多时间。"}},{"en":"to make somebody/yourself anxious about somebody/something","cn":"使担心；使担忧；使发愁","g":"[transitive]","ex":{"en":"What worries me is how I am going to get another job.","cn":"使我发愁的是如何再找到工作。"}},{"en":"to annoy or upset somebody","cn":"骚扰；烦扰；使不安宁","g":"[transitive]","ex":{"en":"The noise never seems to worry her.","cn":"她好像从不受噪音干扰。"}},{"en":"to attack animals, especially sheep, by running after and/or biting them","cn":"追赶，撕咬（动物，尤指羊）","g":"[transitive]"},{"en":"the state of worrying about something","cn":"担心；忧虑；发愁","g":"[uncountable]","ex":{"en":"The threat of losing their jobs is a constant source of worry to them.","cn":"丢掉工作的威胁时常使他们忧心忡忡。"},"pos":"noun"},{"en":"something that worries you","cn":"令人担忧的事；让人发愁的事","g":"[countable]","ex":{"en":"You need have no worries—everything's been taken care of.","cn":"你不必担心，一切都搞定了。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"担心;忧虑；发愁","en":"If you worry, you keep thinking about problems that you have or about unpleasant things that might happen.","ex":{"en":"Don't worry, your luggage will come on afterwards by taxi","cn":"别担心，你的行李随后会由出租车送过来。"}},{"pos":"VERB 动词","cn":"使担心;使忧虑;使发愁","en":"If someone or something worries you, they make you anxious because you keep thinking about problems or unpleasant things that might be connected with them.","ex":{"en":"I'm still in the early days of my recovery and that worries me","cn":"我还处于恢复的早期阶段，这让我很担心。"}},{"pos":"VERB 动词","cn":"让…厌烦；使不安宁;困扰","en":"If someone or something does not worry you, you do not dislike them or you are not annoyed by them.","ex":{"en":"The cold doesn't worry me","cn":"冷我不怕。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"担心;忧虑;发愁","en":"Worry is the state or feeling of anxiety and unhappiness caused by the problems that you have or by thinking about unpleasant things that might happen.","ex":{"en":"The admission shows the depth of worry among the Tories over the state of the economy","cn":"这一认可表明了保守党党内对经济状况的忧虑之深。"}},{"pos":"N-COUNT 可数名词","cn":"使人担心(或发愁)的问题；烦心事","en":"A worry is a problem that you keep thinking about and that makes you unhappy.","ex":{"en":"My main worry was that Madeleine Johnson would still be there","cn":"我最担心的是马德琳·约翰逊仍会在那儿。"}},{"pos":"CONVENTION 惯用语","cn":"（表示自己并不烦恼或生气）别担心；没关系","en":"You say not to worry to someone to indicate that you are not upset or angry when something has gone wrong.","ex":{"en":"'Not to worry, Baby,' he said, and kissed her tenderly.","cn":"“没关系，宝贝儿。”他说道，然后温柔地吻了她一下。"}}]},"examples":[{"en":"The threat of losing their jobs is a constant source of worry to them.","cn":"丢掉工作的威胁时常使他们忧心忡忡。"},{"en":"It worried me to think what might happen.","cn":"想到可能会发生的事情我就发愁了。"}]},"wooden":{"oxford":{"phon":"ˈwʊdn","pos":"adjective","senses":[{"en":"made of wood","cn":"木制的；木头的","g":"[usually before noun]","ex":{"en":"a wooden box/door/floor","cn":"木箱；木门；木地板"}},{"en":"not showing enough natural expression, emotion or movement","cn":"木头似的；死板的；呆板的；木讷的","ex":{"en":"The actor playing the father was too wooden.","cn":"饰演父亲的演员太呆板。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"木质的;木制的","en":"Wooden objects are made of wood.","ex":{"en":"...the shop's bare brick walls and faded wooden floorboards.","cn":"商店裸露的砖墙和褪色的木地板"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(演员)呆板的，死板的，无活力的","en":"If you describe an actor as wooden, you are critical of them because their performance is not at all lively or natural."}]},"media":{"uk":"media/uk/wooden__gb_1.mp3","us":"media/us/wooden__us_1.mp3","img":["media/ldoce/img/wooden.jpg"]},"examples":[{"en":"The actor playing the father was too wooden.","cn":"饰演父亲的演员太呆板。"},{"en":"She speaks her lines very woodenly.","cn":"她台词念得毫无表情。"}]},"wool":{"media":{"uk":"media/uk/wool__gb_1.mp3","us":"media/us/wool__us_1.mp3","img":["media/ldoce/img/needle_knitting.jpg"]},"oxford":{"phon":"wʊl","pos":"noun","senses":[{"en":"the soft hair that covers the body of sheep and some other animals","cn":"（羊等的）绒，毛","ex":{"en":"Sheep were kept for their wool and meat.","cn":"养羊是为了生产羊毛和羊肉。"}},{"en":"long, thick thread made from animal’s wool, used for knitting (= making clothing with wool using two long needles or a machine)","cn":"毛线；绒线","ex":{"en":"a ball of wool","cn":"一团毛线"}},{"en":"cloth made from animal’s wool, used for making clothes, etc.","cn":"毛料；毛织物","ex":{"en":"This scarf is 100% wool.","cn":"这条披肩是纯毛的。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(羊等的)毛","en":"Wool is the hair that grows on sheep and on some other animals."},{"pos":"N-MASS 物质名词","cn":"羊毛织物;毛料","en":"Wool is a material made from animal's wool that is used to make things such as clothes, blankets, and carpets.","ex":{"en":"...a wool overcoat","cn":"羊毛大衣"}},{"pos":"PHRASE 短语","cn":"蒙骗；欺骗","en":"If you say that someone is pulling the wool over your eyes, you mean that they are trying to deceive you, in order to have an advantage over you.","ex":{"en":"Stop trying to pull the wool over my eyes! What were you two fighting about just now?","cn":"休想蒙我！你们俩刚才在争执什么呢？"}}]},"examples":[{"en":"This scarf is 100% wool.","cn":"这条披肩是全毛的。"},{"en":"a ball of wool","cn":"一团毛线"}]},"worthwhile":{"media":{"uk":"media/uk/worthwhile__gb_1.mp3","us":"media/us/worthwhile__us_1.mp3"},"oxford":{"phon":"ˌwɜːθˈwaɪl","pos":"adjective","senses":[{"en":"important, pleasant, interesting, etc.; worth spending time, money or effort on","cn":"重要的；令人愉快的；有趣的；值得花时间（或花钱、努力等）","ex":{"en":"It was in aid of a worthwhile cause (= a charity, etc.).","cn":"这是在为高尚的事业尽一份力。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有价值的;令人愉快的；值得花费时间（或金钱、精力）的","en":"If something is worthwhile, it is enjoyable or useful, and worth the time, money, or effort that is spent on it.","ex":{"en":"The President's trip to Washington this week seems to have been worthwhile","cn":"总统本周的华盛顿之行看来是有价值的。"}}]},"examples":[{"en":"High prices in the UK make it worthwhile for buyers to look abroad.","cn":"英国的高价足以使买主把视线转向国外。"},{"en":"It is worthwhile to include really high-quality illustrations.","cn":"把真正高质量的插图包括进去是值得的。"}]},"works":{"oxford":{"phon":"wɜːk","pos":"verb","senses":[{"en":"to do sth that involves physical or mental effort, especially as part of a job","cn":"做体力（或脑力）工作；劳动；干活"},{"en":"to have a job","cn":"受雇于；从事 … 工作"}]},"media":{"uk":"media/uk/works__gb_1.mp3","us":"media/us/works__us_1.mp3"}},"workday":{"oxford":{"phon":"ˈwɜːkdeɪ","pos":"noun","senses":[{"en":"the part of a day during which you work","cn":"一天中的工作时间","lab":"North American English","ex":{"en":"an 8-hour workday","cn":"8 小时工作日"}},{"en":"a day on which you usually work or on which most people usually work","cn":"工作日","lab":"more frequent","ex":{"en":"workday traffic","cn":"平日的交通"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一天的工作时间","en":"A workday is the amount of time during a day which you spend doing your job.","ex":{"en":"His workday starts at 3.30 a.m. and lasts 12 hours.","cn":"他凌晨3点半开始工作，一直持续12小时。"}},{"pos":"N-COUNT 可数名词","cn":"工作日","en":"A workday is a day on which people go to work.","ex":{"en":"What's he doing home on a workday?","cn":"该上班的日子，他在家干什么？"}}]},"media":{"uk":"media/uk/workday__gb_1.mp3","us":"media/us/workday__us_1.mp3"},"examples":[{"en":"an 8-hour workday * 8","cn":"小时工作日"},{"en":"workday traffic","cn":"平日的交通"}]},"world":{"media":{"uk":"media/uk/world__gb_1.mp3","us":"media/us/world__us_1.mp3"},"oxford":{"phon":"wɜːld","pos":"noun","senses":[{"en":"the earth, with all its countries, peoples and natural features","cn":"世界；地球；天下","g":"[singular]","sc":"the earth/its people","ex":{"en":"a map of the world","cn":"世界地图"}},{"en":"used before another noun to describe one of the most important people or things of their type in the world","cn":"（用于名词前，描述世界上同类中最重要的人或事物）","g":"[singular]","sc":"the earth/its people","ex":{"en":"the world champion/championship/record/title","cn":"世界冠军／锦标赛／纪录／冠军"}},{"en":"a particular part of the earth; a particular group of countries or people; a particular period of history and the people of that period","cn":"某地域（或民族、历史时期等）的人类社会；世界","g":"[countable, usually singular]","sc":"the earth/its people","ex":{"en":"the Arab world","cn":"阿拉伯世界"}},{"en":"the people or things belonging to a particular group or connected with a particular interest, job, etc.","cn":"按性质（或职业等）划分的类别；界；界别","g":"[countable]","sc":"type of life","ex":{"en":"the animal/plant/insect world","cn":"动物界；植物界；昆虫界"}},{"en":"everything that exists of a particular kind; a particular kind of life or existence","cn":"某领域的一切事物；自然界","g":"[usually singular]","sc":"type of life","ex":{"en":"the natural world (= animals, plants, minerals, etc.)","cn":"自然界"}},{"en":"our society and the way people live and behave; the people in the world","cn":"社会；世情；世故；世人","g":"[singular]","sc":"society","ex":{"en":"We live in a rapidly changing world.","cn":"我们生活在瞬息万变的社会里。"}},{"en":"a way of life where possessions and physical pleasures are important, rather than spiritual values","cn":"尘世；世俗；世事；世情","g":"[singular]","sc":"society","ex":{"en":"monks and nuns renouncing the world","cn":"弃绝俗世享乐的修士和修女"}},{"en":"a person’s environment, experiences, friends and family, etc.","cn":"生活环境；阅历；生活圈子","g":"[singular]","sc":"person’s life","ex":{"en":"Parents are the most important people in a child's world.","cn":"父母在儿童的天地里是最重要的人。"}},{"en":"an environment that is imagined or constructed, for example in a computer game","cn":"（电脑游戏等中的）幻想世界，虚拟世界","g":"[countable]","sc":"imagined environment","ex":{"en":"Computer games create whole virtual worlds.","cn":"电脑游戏创造出完整的虚拟世界。"}},{"en":"a planet like the earth","cn":"（像地球的）星球，天体","g":"[countable]","sc":"another planet","ex":{"en":"There may be other worlds out there.","cn":"那里可能有其他星球。"}},{"en":"the state of human existence","cn":"人世；今世；来世","g":"[singular]","sc":"human existence","ex":{"en":"this world and the next (= life on earth and existence after death)","cn":"今世和来世"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"世界;地球","en":"The world is the planet that we live on.","ex":{"en":"It's a beautiful part of the world","cn":"这是世界上很美的一个地区。"}},{"pos":"N-SING 单数名词","cn":"人类;社会;生活","en":"The world refers to all the people who live on this planet, and our societies, institutions, and ways of life.","ex":{"en":"The world was, and remains, shocked","cn":"世人当时感到震惊，现在仍然如此。"}},{"pos":"ADJ 形容词","cn":"世界上最重要的;举世瞩目的","en":"You can use world to describe someone or something that is one of the most important or significant of its kind on earth.","ex":{"en":"Abroad, Mr Bush was seen as a world statesman","cn":"在国外，布什先生被看作一位国际上举足轻重的政治家。"}},{"pos":"N-SING 单数名词","cn":"(指某一群国家或历史时期)世界，国家，时代","en":"You can use world in expressions such as the Arab world ,the western world, and the ancient world to refer to a particular group of countries or a particular period in history.","ex":{"en":"Athens had strong ties to the Arab world.","cn":"雅典与阿拉伯世界关系密切。"}},{"pos":"N-COUNT 可数名词","cn":"人生；生活圈子；阅历","en":"Someone's world is the life they lead, the people they have contact with, and the things they experience.","ex":{"en":"His world seemed so different from mine","cn":"他的生活圈子和我的似乎有天壤之别。"}},{"pos":"N-SING 单数名词","cn":"(人们活动的)领域，界，圈子","en":"You can use world to refer to a particular field of activity, and the people involved in it.","ex":{"en":"The publishing world had certainly never seen an event quite like this.","cn":"出版界以前确实没有遇见过类似这样的事。"}},{"pos":"N-COUNT 可数名词","cn":"（有某种特色的）地方，环境；（某种生活的）世界，境况","en":"You can use world to refer to a place or way of life by describing its strongest features.","ex":{"en":"...a golf course set in a hidden world of parkland, forest and lakes","cn":"位于一处有公共绿地、森林和湖泊的隐秘之地的高尔夫球场"}},{"pos":"N-SING 单数名词","cn":"今世/来世","en":"You can use world in expressions such as this world ,the next world, and the world to come to refer to the state of being alive or a state of existence after death.","ex":{"en":"Good fortune will follow you, both in this world and the next.","cn":"无论今世还是来生，好运都会伴随你。"}},{"pos":"N-SING 单数名词","cn":"（生物的）界","en":"You can use world to refer to a particular group of living things, for example the animal world ,the plant world, and the insect world."},{"pos":"N-COUNT 可数名词","cn":"星球;天体","en":"A world is a planet.","ex":{"en":"He looked like something from another world","cn":"他看上去像是从另一个星球来的。"}},{"pos":"PHRASE 短语","cn":"大相径庭;迥然不同","en":"If you say that two people or things are worlds apart, you are emphasizing that they are very different from each other.","ex":{"en":"Intellectually, this man and I are worlds apart","cn":"在智力上，我和这个男子有天壤之别。"}},{"pos":"PHRASE 短语","cn":"两头受益;两全其美","en":"If you say that someone has the best of both worlds, you mean that they have only the benefits of two things and none of the disadvantages.","ex":{"en":"Her living room provides the best of both worlds, with an office at one end and comfortable sofas at the other.","cn":"她家客厅一头是办公处，一头是舒适的沙发，真是两全其美。"}},{"pos":"PHRASE 短语","cn":"生（孩子）","en":"If a woman brings a child into the world, she gives birth to it.","ex":{"en":"I never felt I achieved a great deal in my life, apart from bringing my children into the world.","cn":"除了生了几个孩子，我从未觉得自己这辈子取得了很大成就。"}},{"pos":"PHRASE 短语","cn":"(表示强调)天壤之别","en":"If you say that there is a world of difference between one thing and another, you are emphasizing that they are very different from each other.","ex":{"en":"There's a world of difference between an amateur video and a slick Hollywood production.","cn":"业余制作的录像短片与好莱坞制作精湛的电影作品有天壤之别。"}},{"pos":"PHRASE 短语","cn":"决不；无论如何也不","en":"If you say that you would not do something for the world, you are emphasizing that you definitely would not do it.","ex":{"en":"I wouldn't have missed this for the world.","cn":"我决不会错过这个。"}},{"pos":"PHRASE 短语","cn":"让…感觉好很多；对…大有好处","en":"If you say that something has done someone the world of good or a world of good, you mean that it has made them feel better or improved their life.","ex":{"en":"A sleep will do you the world of good.","cn":"睡一觉你就会感觉舒服多了。"}},{"pos":"PHRASE 短语","cn":"(用于加强语气)","en":"You use in the world to emphasize a statement that you are making.","ex":{"en":"The saddest thing in the world is a little baby nobody wants","cn":"世上最让人难受的莫过于小婴儿遭到遗弃。"}},{"pos":"PHRASE 短语","cn":"(尤用于强调惊讶或愤怒)究竟，到底","en":"You can use in the world in expressions such as what in the world and who in the world to emphasize a question, especially when expressing surprise or anger.","ex":{"en":"What in the world is he doing?","cn":"他究竟在干什么？"}},{"pos":"PHRASE 短语","cn":"在理想（或完美）的世界中；在理想状况下","en":"You can use in an ideal world or in a perfect world when you are talking about things that you would like to happen, although you realize that they are not likely to happen.","ex":{"en":"In an ideal world Karen Stevens says she would love to stay at home with her two-and-half-year old son","cn":"卡伦·史蒂文斯说在理想的生活中，她非常愿意呆在家里照料两岁半的儿子。"}},{"pos":"PHRASE 短语","cn":"认为（自己）生来就该享福","en":"If you say that someone thinks that the world owes them a living, you are criticizing them because they think it is their right to have a comfortable life without having to make any effort at all.","ex":{"en":"All young people must face up to reality and not kid themselves that the world owes them a living.","cn":"所有的年轻人都必须接受现实，不要自欺欺人，觉得生来就该享清福。"}},{"pos":"PHRASE 短语","cn":"阅历丰富的人;见过世面的人；老成稳重的人","en":"If you say that someone is a man of the world or a woman of the world, you mean that they are experienced and know about the practical or social aspects of life, and are not easily shocked by immoral or dishonest actions.","ex":{"en":"Look, we are both men of the world, would anyone really mind?","cn":"听着，我们都是见过世面的人，真有人会介意吗？"}},{"pos":"PHRASE 短语","cn":"极好的;一流的；非常棒的","en":"If you say that something is out of this world, you are emphasizing that it is extremely good or impressive.","ex":{"en":"These new trains are out of this world.","cn":"这些新火车太棒了。"}},{"pos":"PHRASE 短语","cn":"外面的世界;外界","en":"You can use the outside world to refer to all the people who do not live in a particular place or who are not involved in a particular situation.","ex":{"en":"For many, the post office is the only link with the outside world","cn":"对很多人来说，这个邮局是与外界联系的唯一纽带。"}},{"pos":"PHRASE 短语","cn":"全世界;世界各地","en":"If you say that something happens or exists the world over, you mean that it happens or exists in every part of the world.","ex":{"en":"Some problems are the same the world over","cn":"有些问题在全世界都一样。"}},{"pos":"PHRASE 短语","cn":"在自己的世界里;在自己的小天地里","en":"If you say that someone is in a world of their own, you mean that they seem not to notice other people or the things going on around them.","ex":{"en":"When I'm swimming I'm in a world of my own","cn":"游泳的时候，我沉浸在自己的世界里。"}},{"pos":"PHRASE 短语","cn":"非常喜欢；非常在乎","en":"If you think the world of someone, you like them or care about them very much.","ex":{"en":"I think the world of him, but something tells me it's not love","cn":"我很在乎他，但是某种感觉告诉我这不是爱。"}},{"pos":"PHRASE 短语","cn":"发迹/落魄;飞黄腾达/潦倒","en":"If you say that someone has gone up in the world, you mean they have become richer or have a higher social status than before. If you say they have come down in the world, you mean they have become poorer or have a lower social status.","ex":{"en":"When they started to go up in the world, they moved to a flat in London.","cn":"他们开始发家的时候，搬进了伦敦的一所公寓。"}},{"pos":"","cn":"","en":"not be the end of the world→see: ; the world is your oyster→see: ; on top of the world→see: ;"}]},"examples":[{"en":"If you enjoy the coast and the country, you'll get the best of both worlds on this walk.","cn":"你要是喜欢海滨和乡村，那么这次散步你会一举两得。"},{"en":"In an ideal world we would be recycling and reusing everything.","cn":"我们要是能回收并再利用所有的东西就再理想不过了。"}]},"wolf":{"oxford":{"phon":"wʊlf","pos":"noun","senses":[{"en":"a large wild animal of the dog family, that lives and hunts in groups","cn":"狼","ex":{"en":"She compared the media to a pack of ravening/ravenous wolves.","cn":"她把媒体比作一群饿狼。"}},{"en":"to eat food very quickly, especially by putting a lot of it in your mouth at once","cn":"大口地快吃；狼吞虎咽","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"狼","en":"A wolf is a wild animal that looks like a large dog."},{"pos":"VERB 动词","cn":"狼吞虎咽地吃","en":"If someone wolfs their food, they eat it all very quickly and greedily.","ex":{"en":"I was back in the changing room wolfing tea and sandwiches.","cn":"我回到更衣室，狼吞虎咽地喝茶、吃三明治。"}},{"pos":"PHRASE 短语","cn":"喊“狼来了”;发假警报","en":"If someone cries wolf, they say that there is a problem when there is not, with the result that people do not believe them when there really is a problem."},{"pos":"PHRASE 短语","cn":"勉强度日;糊口","en":"If you keep the wolf from the door, you succeed in providing food and other necessary things for yourself or your family.","ex":{"en":"A lot of the lads took small jobs to help keep the wolf from the door.","cn":"很多少年打零工帮补家里维持生计。"}},{"pos":"","cn":"","en":"相关词组：wolf down"}]},"media":{"uk":"media/uk/wolf__gb_1.mp3","us":"media/us/wolf__us_1.mp3","img":["media/ldoce/img/wolf.jpg"]},"examples":[{"en":"a pack of wolves","cn":"一群狼"},{"en":"I work part-time in a coffee shop just to keep the wolf from the door.","cn":"我在一家咖啡馆打零工﹐勉强糊口。"}]},"wood":{"media":{"img":["media/pic/tree_bark_comp.jpg","media/thumb/log.jpg","media/ldoce/img/carpenter.jpg"],"uk":"media/uk/wood__gb_1.mp3","us":"media/us/wood__us_1.mp3"},"oxford":{"phon":"wʊd","pos":"noun","senses":[{"en":"the hard material that the trunk and branches of a tree are made of; this material when it is used to build or make things with, or as a fuel","cn":"木；木头；木料；木柴","g":"[uncountable, countable]","ex":{"en":"He chopped some wood for the fire.","cn":"他劈了些柴烧火。"}},{"en":"an area of trees, smaller than a forest","cn":"树林；林地","g":"[countable]","ex":{"en":"a large wood","cn":"一大片树林"}},{"en":"a heavy wooden ball used in the game of bowls","cn":"（草地滚球运动的）木瓶","g":"[countable]"},{"en":"a golf club with a large head, that was usually made of wood in the past","cn":"木头球杆（旧时通常有木制顶部的高尔夫球棒）","g":"[countable]"}]},"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"木材;木料；木头","en":"Wood is the material which forms the trunks and branches of trees.","ex":{"en":"Their dishes were made of wood","cn":"他们的盘子是木制的。"}},{"pos":"N-COUNT 可数名词","cn":"树林，林子（美国英语通常用woods）","en":"A wood is a fairly large area of trees growing near each other. You can refer to one or several of these areas as woods, and this is the usual form in American English.","ex":{"en":"After dinner Alice slipped away for a walk in the woods with Artie","cn":"晚餐后艾利斯溜出去跟阿蒂到林子里散步。"}},{"pos":"PHRASE 短语","cn":"仍未摆脱困境(或问题)","en":"If something or someone is not out of the woods yet, they are still having difficulties or problems.","ex":{"en":"The nation's economy is not out of the woods yet.","cn":"该国经济尚未摆脱困境。"}},{"pos":"CONVENTION 惯用语","cn":"上天保佑(表示希望继续走好运)","en":"You can say 'touch wood' in British English, or 'knock on wood' in American English, to indicate that you hope to have good luck in something you are doing, usually after saying that you have been lucky with it so far.","ex":{"en":"She's never even been to the doctor's, touch wood","cn":"她从未看过病，希望她一直好运。"}},{"pos":"","cn":"","en":"your neck of the woods→see: ; can't the wood for the trees→see: ;"}]},"examples":[{"en":"All the furniture was made of wood.","cn":"这里所有的家具都是用木料制作的。"},{"en":"furniture made of a variety of different woods","cn":"用各种不同的木材制作的家具"}]},"wooded":{"media":{"uk":"media/uk/wooded__gb_1.mp3","us":"media/us/wooded__us_1.mp3"},"oxford":{"phon":"ˈwʊdɪd","pos":"adjective","senses":[{"en":"covered with trees","cn":"长满树木的；树木茂盛的","ex":{"en":"a thickly wooded area","cn":"林木茂密的地区"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"树木覆盖的;林木茂盛的","en":"A wooded area is covered in trees.","ex":{"en":"...a wooded valley.","cn":"树木茂盛的峡谷"}}]},"examples":[{"en":"the wooded hills of northern Virginia","cn":"北弗吉尼亚林木茂盛的丘陵"},{"en":"a thickly wooded area","cn":"树木茂密的地区"}]},"worried":{"media":{"uk":"media/uk/worried__gb_1.mp3","us":"media/us/worried__us_1.mp3"},"oxford":{"phon":"ˈwʌrid","pos":"adjective","senses":[{"en":"thinking about unpleasant things that have happened or that might happen and therefore feeling unhappy and afraid","cn":"担心的；担忧的；发愁的","ex":{"en":"Don't look so worried!","cn":"别这么愁眉苦脸的！"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"担心的;发愁的;焦虑的","en":"When you are worried, you are unhappy because you keep thinking about problems that you have or about unpleasant things that might happen in the future.","ex":{"en":"He seemed very worried","cn":"他好像非常担心。"}}]},"examples":[{"en":"You had me worried for a moment — I thought you were going to resign!","cn":"你可让我担心了一阵子，我原以为你要辞职呢！"},{"en":"The police are worried that the man may be armed.","cn":"警方担心那个人可能携带着武器。"}]},"wound":{"media":{"uk":"media/uk/wound__gb_2.mp3","us":"media/us/wound__us_2.mp3"},"oxford":{"phon":"wuːnd","pos":"noun","senses":[{"en":"an injury to part of the body, especially one in which a hole is made in the skin using a weapon","cn":"（身体上的）伤，伤口；（武器造成的）伤","lab":"especially British English","ex":{"en":"a gunshot/stab wound","cn":"枪伤；刺伤"}},{"en":"mental or emotional pain caused by something unpleasant that has been said or done to you","cn":"（心灵上的）伤，创伤","ex":{"en":"Seeing him again opened up old wounds.","cn":"再次见到他打开了旧的创伤。"}},{"en":"to injure part of the body, especially by making a hole in the skin using a weapon","cn":"使（身体）受伤；（用武器）伤害","ex":{"en":"He had been wounded in the arm.","cn":"他的手臂受过伤。"},"pos":"verb"},{"en":"to hurt somebody’s feelings","cn":"使（心灵）受伤；伤感情","ex":{"en":"She had been deeply wounded by his remarks.","cn":"他的话使她深受伤害。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(刀、枪或其他武器所致的)创伤，伤口","en":"A wound is damage to part of your body, especially a cut or a hole in your flesh, which is caused by a gun, knife, or other weapon.","ex":{"en":"The wound is healing nicely","cn":"伤口愈合得很好。"}},{"pos":"VERB 动词","cn":"（武器或其他利器）伤害，使受伤","en":"If a weapon or something sharp wounds you, it damages your body.","ex":{"en":"A bomb exploded in a hotel, killing six people and wounding another five","cn":"一枚炸弹在一家旅馆爆炸，造成6人死亡，5人受伤。"}},{"pos":"N-COUNT 可数名词","cn":"(思想或感情上的)伤害，创伤","en":"A wound is a lasting bad effect on someone's mind or feelings caused by a very upsetting experience.","ex":{"en":"She has been so deeply hurt it may take forever for the wounds to heal.","cn":"她内心受伤太深，也许再也无法愈合。"}},{"pos":"VERB 动词","cn":"(在感情上)伤害，使受创伤","en":"If you are wounded by what someone says or does, your feelings are deeply hurt.","ex":{"en":"He was deeply wounded by the treachery of close aides","cn":"他被亲密助手的背叛深深地伤害了。"}},{"pos":"PHRASE 短语","cn":"（失败或被羞辱后）舔伤，重整旗鼓","en":"If you say that someone is licking their wounds, you mean that they are recovering after being defeated or made to feel ashamed or unhappy.","ex":{"en":"The British team was returning home yesterday to lick its wounds after defeat by India.","cn":"英国队负于印度队后，昨日回国休整。"}},{"pos":"PHRASE 短语","cn":"揭旧伤疤(指重提他人不愿提起的痛苦往事)","en":"Something that opens old wounds or reopens old wounds reminds someone about an upsetting experience in the past which they would prefer to forget.","ex":{"en":"Courts have been reluctant to reopen old wounds by trying crimes that are decades old.","cn":"法院不愿重揭旧伤疤，去审理几十年前的罪案。"}},{"pos":"","cn":"","en":"to rub salt into the wound→see: ;"}]},"examples":[{"en":"After a serious argument, it can take some time for the wounds to heal.","cn":"激烈争吵之后的感情创伤需要一些时间才能愈合。"},{"en":"She felt deeply wounded by his cruel remarks.","cn":"他那刻薄的话语使她感到深受伤害。"}]},"woman":{"media":{"uk":"media/uk/woman__gb_1.mp3","us":"media/us/woman__us_1.mp3"},"oxford":{"phon":"ˈwʊmən","pos":"noun","senses":[{"en":"an adult female human","cn":"成年女子；妇女","g":"[countable]","ex":{"en":"a 54-year-old woman","cn":"一位54岁的女性"}},{"en":"female humans in general","cn":"（泛指）女性","g":"[uncountable]","lab":"informal","ex":{"en":"She's all woman! (= has qualities that are typical of women)","cn":"她是典型的女人！"}},{"en":"a woman who comes from the place mentioned or whose job or interest is connected with the thing mentioned","cn":"来自…（或做…、喜欢…等）的女子","g":"[countable]","lab":"British English","ex":{"en":"an Englishwoman","cn":"英格兰女人"}},{"en":"a female worker, especially one who works with her hands","cn":"（尤指做手工劳动的）女工","g":"[countable]","ex":{"en":"We used to have a woman to do the cleaning.","cn":"我们曾雇过一位女工打扫卫生。"}},{"en":"a rude way of addressing a female person, especially when telling her what to do","cn":"臭娘儿们","g":"[singular]","lab":"old-fashioned, offensive，，","ex":{"en":"Be quiet, woman!","cn":"安静，你这个臭娘儿们！"}},{"en":"a person's wife, girlfriend or female partner","cn":"妻子；女朋友；女相好","g":"[countable]","lab":"sometimes disapproving","ex":{"en":"He's got a new woman in his life.","cn":"他生命中又有了一个女人。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"成年女子;妇女","en":"A woman is an adult female human being.","ex":{"en":"...a young Lithuanian woman named Dayva.","cn":"名叫戴娃的立陶宛年轻女子"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(泛指)女性，女子","en":"You can refer to women in general as woman .","ex":{"en":"...the oppression of woman.","cn":"对妇女的压迫"}},{"pos":"N-COUNT 可数名词","cn":"爱好…的女人;喜欢做…的女子","en":"If you say that a woman is, for example, a gambling woman or an outdoors woman, you mean that she likes gambling or outdoor activities. a woman about town→see: ;","ex":{"en":"She is an avid outdoors woman","cn":"她酷爱户外运动。"}},{"pos":"N-COUNT 可数名词","cn":"来自…的女人;在…上大学的女子","en":"If you say that a woman is, for example, a London woman or an Oxford woman, you mean that she comes from London or Oxford, or went to university there.","ex":{"en":"...a 38-year-old London woman","cn":"38岁的伦敦女子"}},{"pos":"N-COUNT 可数名词","cn":"妻子;情人;女友","en":"Some people refer to a man's wife, lover, or girlfriend as his woman .","ex":{"en":"I know my woman will never leave me.","cn":"我知道我的女人永远不会离开我。"}},{"pos":"N-COUNT 可数名词","cn":"(公司或组织的)女代表，女代理人","en":"You can refer to a female representative of a company or organization as that company or organization's woman .","ex":{"en":"Yet another successful Labour woman took her seat","cn":"又有一位成功的工党女代表就任议员。"}},{"pos":"N-VOC 称呼名词","cn":"(命令性的或生气、不耐烦时的称呼)婆娘，娘儿们","en":"People sometimes address a woman as woman when they are ordering her to do something or when they are angry or impatient with her. This use could cause offence.","ex":{"en":"Do you realize, woman, the scandal and publicity that will be involved?","cn":"臭婆娘，你知不知道这会恶名远扬？"}},{"pos":"PHRASE 短语","cn":"独立自主;做独立女性","en":"If you say that a woman is her own woman, you approve of the fact that she makes her plans and decisions herself, and does not depend on other people.","ex":{"en":"She knew she had made the right decision. She was her own woman again.","cn":"她知道她作了一个正确的决定。她又独立自主了。"}},{"pos":"","cn":"","en":"woman of the world→see: ;"}]},"examples":[{"en":"We used to have a woman to do the cleaning.","cn":"我们曾雇过一位女工打扫卫生。"},{"en":"Working for herself meant that she could be her own woman.","cn":"独立工作意味着她能够自主。"}]},"worrying":{"oxford":{"phon":"ˈwʌriɪŋ","pos":"adjective","senses":[{"en":"that makes you worry","cn":"令人担忧的；令人发愁的","ex":{"en":"a worrying development","cn":"令人担忧的发展"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人担心的;使人发愁的","en":"If something is worrying, it causes people to worry. →see usage note at:","ex":{"en":"It's worrying that they're doing things without training.","cn":"他们没经过培训就做这些事情，这让人很担心。"}}]},"media":{"uk":"media/uk/worrying__gb_1.mp3","us":"media/us/worrying__us_1.mp3"},"examples":[{"en":"Worryingly, the plan contains few details on how spending will be cut.","cn":"令人担忧的是，这项计划中有关如何削减开支的细则很少。"},{"en":"It is particularly worrying that nobody seems to be in charge.","cn":"特别令人担忧的是，似乎没有任何人在负责。"}]},"worth":{"media":{"uk":"media/uk/worth__gb_1.mp3","us":"media/us/worth__us_1.mp3"},"oxford":{"phon":"wɜːθ","pos":"adjective","senses":[{"en":"having a value in money, etc.","cn":"有…价值；值…钱","ex":{"en":"Our house is worth about £100 000.","cn":"我们的房子大约值 10 万英镑。"}},{"en":"used to recommend the action mentioned because you think it may be useful, pleasant, etc.","cn":"（指行动）值得，有价值","ex":{"en":"The museum is certainly worth a visit.","cn":"这家博物馆的确值得参观。"}},{"en":"important, good or pleasant enough to make somebody feel satisfied, especially when difficulty or effort is involved","cn":"值得（费周折）","ex":{"en":"Was it worth the effort?","cn":"这值得花费力气吗？"}},{"en":"having money and possessions of a particular value","cn":"拥有…价值的财产","ex":{"en":"He's worth £10 million.","cn":"他拥有 1 000 万英镑的财产。"}},{"en":"an amount of something that has the value mentioned","cn":"价值（十美元、40 英镑等）的东西","ex":{"en":"The winner will receive fifty pounds' worth of books.","cn":"获胜者将得到价值五十英镑的书。"},"pos":"noun"},{"en":"an amount of something that lasts a week, etc.","cn":"能用（一个星期、一个月等）的东西","pos":"noun"},{"en":"the financial, practical or moral value of somebody/something","cn":"价值；意义；作用","ex":{"en":"Their contribution was of great worth.","cn":"他们的贡献具有伟大的意义。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"v-link worth amount","cn":"价值;值…钱","en":"If something is worth a particular amount of money, it can be sold for that amount or is considered to have that value.","ex":{"en":"These books might be worth £80 or £","cn":"90 or more to a collector... 这些书对收藏家而言可能值八九十英镑或更多。"}},{"pos":"COMB in QUANT 与数量词构成的词","cn":"(与金额连用)价值…","en":"Worth combines with amounts of money, so that when you talk about a particular amount of money's worth of something, you mean the quantity of it that you can buy for that amount of money.","ex":{"en":"I went and bought about six dollars' worth of potato chips","cn":"我去买了大约6美元的薯条。"}},{"pos":"COMB in QUANT 与数量词构成的词","cn":"(与时间连用)可维持…（时间）","en":"Worth combines with time expressions, so you can use worth when you are saying how long an amount of something will last. For example, a week's worth of food is the amount of food that will last you for a week.","ex":{"en":"You've got three years' worth of research money to do what you want with","cn":"你有可维持3年的研究经费去做自己想做的事。"}},{"pos":"v-link worth -ing","cn":"值得(拥有)","en":"If you say that something is worth having, you mean that it is pleasant or useful, and therefore a good thing to have.","ex":{"en":"He's decided to get a look at the house and see if it might be worth buying","cn":"他决定去瞧瞧那座房子，看是否值得买下。"}},{"pos":"v-link worth n/-ing","cn":"具有(某一行动)的价值;值得(做)","en":"If something is worth a particular action, or if an action is worth doing, it is considered to be important enough for that action.","ex":{"en":"No one is worth a great deal of sacrifice","cn":"没有谁值得付出重大的牺牲。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(某人的)价值，用处，重要性","en":"Someone's worth is the value, usefulness, or importance that they are considered to have.","ex":{"en":"He had never had a woman of her worth as a friend","cn":"他从来没有过像她这样值得交往的女性朋友。"}},{"pos":"PHRASE 短语","cn":"拼命地; 全力以赴地；热情高涨地","en":"If you do something for all you are worth, you do it with a lot of energy and enthusiasm.","ex":{"en":"We both began waving to the crowd for all we were worth","cn":"我们俩开始使劲地朝人群挥手。"}},{"pos":"PHRASE 短语","cn":"尽可能地利用;充分利用","en":"If someone does something for all it is worth, they do it as much as possible and for as long as they can get benefit from it.","ex":{"en":"You get anywhere with legal aid only by playing the system for all it is worth.","cn":"你若想让法律援助多少发挥点作用，只有充分利用这一制度。"}},{"pos":"PHRASE 短语","cn":"(尤为避免显得傲慢)不管好坏，不管有没有用","en":"If you add for what it's worth to something that you say, you are suggesting that what you are saying or referring to may not be very valuable or helpful, especially because you do not want to appear arrogant.","ex":{"en":"For what it's worth, my feeling is that ice in whisky is fine","cn":"不管怎么样，我觉得威士忌放冰很好。"}},{"pos":"PHRASE 短语","cn":"(行为或活动)值得…去做，对…有好处","en":"If an action or activity is worth someone's while, it will be helpful, useful, or enjoyable for them if they do it, even though it requires some effort.","ex":{"en":"It might be worth your while to go to court and ask for the agreement to be changed","cn":"上法庭要求对协议进行改动也许对你有益。"}},{"pos":"","cn":"","en":"worth your weight in gold→see: ;"}]},"examples":[{"en":"The trip was expensive but it was worth every penny.","cn":"这次旅行花费很大，但是花的每一分钱都不冤枉。"},{"en":"He'll do the job if you make it worth his while (= pay him well).","cn":"你要是给他的报酬丰厚，他会做这份工作的。"}]},"won't":{"media":{"uk":"media/uk/won_t_1_gb_2.mp3","us":"media/us/won_t_1_us_2.mp3"},"oxford":{"phon":"wəʊnt","pos":"short form","senses":[{"en":"will not","cn":""}]},"collins":{"senses":[{"pos":"","cn":"（will not 的常用口语形式）","en":"Won't is the usual spoken form of 'will not'.","ex":{"en":"His parents won't let him come.","cn":"她父母不会让他来的。"}}]}},"wore":{"collins":{"senses":[{"pos":"","cn":"","en":"Wore is the past tense of wear."}]},"media":{"uk":"media/uk/wore__gb_1.mp3","us":"media/us/wore__us_1.mp3"}},"woke":{"collins":{"senses":[{"pos":"","cn":"","en":"Woke is the past tense of wake."}]},"media":{"uk":"media/uk/woke__gb_1.mp3","us":"media/us/woke__us_1.mp3"},"oxford":{"phon":"wəʊk","pos":"adjective","senses":[{"en":"aware of social and political issues, especially racism","cn":"（对于社会和政治问题，尤其是种族主义）清醒明白的，觉醒的","ex":{"en":"We need to stay woke and keep fighting for what's right.","cn":"我们要保持清醒，坚持为正义而斗争。"}}]}},"worn":{"media":{"uk":"media/uk/worn__gb_2.mp3","us":"media/us/worn__us_2.mp3"},"oxford":{"phon":"wɔːn","pos":"adjective","senses":[{"en":"damaged or thinner than normal because it is old and has been used a lot","cn":"用坏的；用旧的；磨薄的","g":"[usually before noun]","ex":{"en":"an old pair of worn jeans","cn":"一条破旧的牛仔裤"}},{"en":"looking very tired","cn":"疲惫的；筋疲力尽的","ex":{"en":"She came out of the ordeal looking thin and worn.","cn":"她经历过这场苦难后显得憔悴不堪。"}}]},"collins":{"senses":[{"pos":"","cn":"","en":"Worn is the past participle of wear ."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"破旧的；磨损的;陈旧的","en":"Worn is used to describe something that is damaged or thin because it is old and has been used a lot.","ex":{"en":"Worn rugs increase the danger of tripping","cn":"磨损的小地毯会使人更容易绊倒。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"憔悴的；疲惫的;苍老的","en":"If someone looks worn, they look tired and old.","ex":{"en":"She was looking very haggard and worn.","cn":"她看上去非常憔悴和疲惫。"}}]},"examples":[{"en":"She came out of the ordeal looking thin and worn.","cn":"她经历过这场苦难后显得憔悴不堪。"},{"en":"The stone steps were worn and broken.","cn":"这些石头台阶被磨平破裂了。"}]},"worker":{"media":{"uk":"media/uk/worker__gb_1.mp3","us":"media/us/worker__us_1.mp3"},"oxford":{"phon":"ˈwɜːkə(r)","pos":"noun","senses":[{"en":"a person who works, especially one who does a particular kind of work","cn":"工作者；人员","lab":"British English","ex":{"en":"farm/factory/office workers","cn":"农场／工厂工人；职员"}},{"en":"a person who is employed in a company or industry, especially somebody who does physical work rather than organizing things or managing people","cn":"雇员；（尤指）劳工，工人","g":"[usually plural]","ex":{"en":"Conflict between employers and workers intensified and the number of strikes rose.","cn":"劳资矛盾加剧，罢工次数增多。"}},{"en":"a person who works in a particular way","cn":"干活…的人","ex":{"en":"a hard/fast/quick/slow worker","cn":"做事努力／快／麻利／慢的人"}},{"en":"a female bee that helps do the work of the group of bees but does not produce young","cn":"工蜂"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"从事…工作的人;工作者","en":"A particular kind of worker does the kind of work mentioned.","ex":{"en":"...office workers","cn":"办公室职员"}},{"pos":"N-COUNT 可数名词","cn":"工人;雇员","en":"Workers are people who are employed in industry or business and who are not managers.","ex":{"en":"Wages have been frozen and workers laid off.","cn":"工资被冻结，工人下岗。"}},{"pos":"N-COUNT 可数名词","cn":"工作做得…的人","en":"You can use worker to say how well or badly someone works.","ex":{"en":"He is a hard worker and a skilled gardener","cn":"他工作很努力，对园艺很在行。"}}]},"examples":[{"en":"Conflict between employers and workers intensified and the number of strikes rose.","cn":"劳资矛盾加剧，罢工次数增多。"},{"en":"manual/skilled/unskilled workers","cn":"体力劳动者；熟练/非熟练工人"}]},"working-class":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the group of people in society who traditionally do physical work and do not have much money or power","cn":""}]},"examples":[{"en":"Marx wrote about the political struggles of the working class.","cn":"","src":"ld"}],"media":{"uk":"media/uk/working_class_1_gb_1.mp3","us":"media/us/working_class_1_us_1.mp3"},"oxford":{"phon":"ˌwɜːkɪŋ ˈklɑːs","pos":"adjective","senses":[{"en":"from or connected with the social class whose members do not have much money or power and are usually employed to do manual work (= physical work using their hands)","cn":"工人阶级的","ex":{"en":"a working-class background","cn":"工人阶级出身"}}]}},"worthless":{"media":{"uk":"media/uk/worthless__gb_1.mp3","us":"media/us/worthless__us_1.mp3"},"oxford":{"phon":"ˈwɜːθləs","pos":"adjective","senses":[{"en":"having no practical or financial value","cn":"没用的；无价值的","ex":{"en":"Critics say his paintings are worthless.","cn":"评论家说他的画毫无价值。"}},{"en":"having no good qualities or useful skills","cn":"品质坏的；不中用的","ex":{"en":"He's just a worthless individual.","cn":"他实在是个品质坏的人。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"无价值的;不值钱的;没用处的","en":"Something that is worthless is of no real value or use.","ex":{"en":"The guarantee could be worthless if the firm goes out of business","cn":"如果厂家倒闭，保修单就会变得毫无用处。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"一无是处的；不中用的","en":"Someone who is described as worthless is considered to have no good qualities or skills.","ex":{"en":"You feel you really are completely worthless and unlovable.","cn":"你会觉得自己真是毫无价值，一点也不讨人喜欢。"}}]},"examples":[{"en":"Constant rejections made him feel worthless.","cn":"不断地遭到拒绝使他觉得一无是处。"},{"en":"Critics say his paintings are worthless.","cn":"批评家说他的画毫无价值。"}]},"workplace":{"media":{"uk":"media/uk/workplace__gb_1.mp3","us":"media/us/workplace__us_1.mp3"},"oxford":{"phon":"ˈwɜːkpleɪs","pos":"noun","senses":[{"en":"the office, factory, etc. where people work","cn":"工作场所","ex":{"en":"the introduction of new technology into the workplace","cn":"把新技术引进工厂"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"工作场所","en":"Your workplace is the place where you work.","ex":{"en":"...the difficulties facing women in the workplace","cn":"女性在工作场所面临的种种困难"}}]},"examples":[{"en":"the introduction of new technology into the workplace","cn":"把新技术引进工厂"},{"en":"a report into discrimination in the workplace","cn":"调查职场歧视的报告"}]},"working":{"media":{"uk":"media/uk/working__gb_1.mp3","us":"media/us/working__us_1.mp3"},"oxford":{"phon":"ˈwɜːkɪŋ","pos":"adjective","senses":[{"en":"having a job for which you are paid","cn":"有工作的；有职业的","ex":{"en":"the working population","cn":"劳动人口"}},{"en":"having a job that involves hard physical work rather than office work, studying, etc.","cn":"做工的；从事体力劳动的","ex":{"en":"a working man","cn":"工人"}},{"en":"connected with your job and the time you spend doing it","cn":"工作上的；工作时间的","ex":{"en":"long working hours","cn":"长的工作时间"}},{"en":"a working breakfast or lunch is one at which you discuss business","cn":"（早餐或午餐等）边吃边谈公事的"},{"en":"used as a basis for work, discussion, etc. but likely to be changed or improved in the future","cn":"初步的；暂定的","ex":{"en":"a working theory","cn":"初步的理论"}},{"en":"if you have a working knowledge of something, you can use it at a basic level","cn":"尚可应付工作的；基本够用的"},{"en":"the working parts of a machine are the parts that move in order to make it function","cn":"（机械部件）操纵用的，用于启动的"},{"en":"a working majority is a small majority that is enough to enable a government to win votes in parliament and make new laws","cn":"（议会票数）足够多数的"},{"en":"the action of doing work","cn":"工作","g":"[uncountable]","ex":{"en":"Working with animals requires patience.","cn":"与动物打交道需要耐心。"},"pos":"noun"},{"en":"the way in which a machine, a system, an organization, etc. works","cn":"（机器、系统、组织等的）运作，工作方法","g":"[countable, usually plural]","ex":{"en":"an introduction to the workings of Congress","cn":"对国会运作方式的介绍"},"pos":"noun"},{"en":"the parts of a mine or quarry where coal, metal, stone, etc. is or has been dug from the ground","cn":"（矿山或采石场的）矿，巷道，作业区","g":"[countable, usually plural]","ex":{"en":"A pump was used to remove water from the old workings.","cn":"一台泵被用来从旧矿井中抽水。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"有工作的;有职业的","en":"Working people have jobs which they are paid to do.","ex":{"en":"Like working women anywhere, Asian women are buying convenience foods.","cn":"像其他地方的职业女性一样，亚洲女性也购买方便食品。"}},{"pos":"ADJ 形容词","cn":"从事普通工作的","en":"Working people are ordinary people who do not have professional or very highly paid jobs.","ex":{"en":"The needs and opinions of ordinary working people were ignored","cn":"普通劳动者的需求和意见遭到忽视。"}},{"pos":"ADJ 形容词","cn":"上班时间的;工作时间的","en":"A working day or week is the amount of time during a normal day or week which you spend doing your job.","ex":{"en":"For doctors the working day often has no end","cn":"医生常常没有下班的时候。"}},{"pos":"ADJ 形容词","cn":"工作日的;上班的","en":"A working day is a day on which people go to work.","ex":{"en":"The full effect will not be apparent until Tuesday, the first working day after the three day holiday weekend.","cn":"周二是周末3天假期后的第一个工作日，到那时效果才会完全显现出来。"}},{"pos":"ADJ 形容词","cn":"（人生阶段）工作的，处于就业年龄的","en":"Your working life is the period of your life in which you have a job or are of a suitable age to have a job.","ex":{"en":"He started his working life as a truck driver.","cn":"他的工作生涯是从当卡车司机开始的。"}},{"pos":"ADJ 形容词","cn":"(某一地区的人口)就业的，处于就业年龄的","en":"The working population of an area consists of all the people in that area who have a job or who are of a suitable age to have a job.","ex":{"en":"Almost 13 per cent of the working population is already unemployed.","cn":"就业人口中有将近13%已失业。"}},{"pos":"ADJ 形容词","cn":"（条件或常规做法）工作的，工作上的","en":"Working conditions or practices are ones which you have in your job.","ex":{"en":"The strikers are demanding higher pay and better working conditions.","cn":"罢工者要求加薪并改善工作环境。"}},{"pos":"ADJ 形容词","cn":"（衣服）工作时穿的","en":"Working clothes are designed for doing work in, and are intended to be practical rather than attractive."},{"pos":"ADJ 形容词","cn":"（关系）工作上的，同事间的","en":"A working relationship is the relationship you have with someone when you work with them.","ex":{"en":"A working relationship turned into a very close friendship","cn":"同事关系变成了非常亲密的友谊。"}},{"pos":"ADJ 形容词","cn":"(农场或企业)经营性的，营利性的","en":"A working farm or business exists to do normal work and make a profit, and not only for tourists or as someone's hobby."},{"pos":"ADJ 形容词","cn":"(机器零部件)能运转的，用于操作的","en":"The working parts of a machine are the parts which move and operate the machine, in contrast to the outer case or container in which they are enclosed."},{"pos":"ADJ 形容词","cn":"(模型)活动的，可操作的","en":"A working model is one that has parts that move."},{"pos":"ADJ 形容词","cn":"(知识)够用的;（多数票）有效的","en":"A working knowledge or majority is not very great, but is enough to be useful.","ex":{"en":"This book was designed in order to provide a working knowledge of finance and accounts","cn":"本书旨在提供金融和会计方面的实用知识。"}},{"pos":"ADJ 形容词","cn":"(题目或定义)暂用的，暂定的","en":"A working title or definition is one which you use when starting to make or do something, but which you are likely to change or improve.","ex":{"en":"His working title for the script was 'Trust the People'.","cn":"他给这个剧本暂定的标题是《相信人民》。"}},{"pos":"N-PLURAL 复数名词","cn":"(设备、组织或系统的)工作方式，运行方式","en":"The workings of a piece of equipment, an organization, or a system are the ways in which it operates and the processes which are involved in it.","ex":{"en":"Neural networks are computer systems which mimic the workings of the brain","cn":"神经网络是模拟大脑工作方式的计算机系统。"}},{"pos":"N-PLURAL 复数名词","cn":"矿坑;巷道","en":"You can use workings to refer to deep tunnels or holes which have been dug in the ground in order to remove coal, metal, or stone.","ex":{"en":"...housing which was built above old mine workings.","cn":"修建在老矿坑上的房屋"}},{"pos":"","cn":"","en":"in working order→see: ;"}]},"examples":[{"en":"She spent most of her working life as a teacher.","cn":"她一生中大部分工作时间都当教师。"},{"en":"I have a good working relationship with my boss.","cn":"我和老板的工作关系很好。"}]},"won":{"collins":{"senses":[{"pos":"","cn":"","en":"Won is the past tense and past participle of win."}]},"media":{"uk":"media/uk/won__gb_1.mp3","us":"media/us/won__us_1.mp3"},"oxford":{"phon":"wɒn","pos":"noun","senses":[{"en":"the unit of money in North and South Korea","cn":"圆（韩国和朝鲜的本位货币单位）","ex":{"en":"The fall in the value of the South Korean won has led to a boom in exports.","cn":"韩元贬值导致出口繁荣。"}}]}},"worms":{"oxford":{"phon":"wɜːm","pos":"noun","senses":[{"en":"a long thin creature with no bones or legs, that lives in soil","cn":"蠕虫"},{"en":"long thin creatures that live inside the bodies of humans or animals and can cause illness （","cn":"人或动物体内的）寄生虫；肠虫"}]}},"wouldn't":{"collins":{"senses":[{"pos":"","cn":"（would not 的常用口语形式）","en":"Wouldn't is the usual spoken form of 'would not'.","ex":{"en":"They wouldn't allow me to smoke.","cn":"他们不会让我抽烟的。"}}]},"media":{"uk":"media/ldoce/hwd/bre/2/wouldn_t0205.mp3","us":"media/ldoce/hwd/ame/e/wouldn_t.mp3"}},"wonders":{"oxford":{"phon":"ˈwʌndə(r)","pos":"verb","senses":[{"en":"to think about sth and try to decide what is true, what will happen, what you should do, etc.","cn":"想知道；想弄明白；琢磨"},{"en":"used as a polite way of asking a question or asking sb to do sth （","cn":"礼貌地提问或请人做事时说）"}]}},"workers":{"oxford":{"phon":"ˈwɜːkə(r)","pos":"noun","senses":[{"en":"( often in compounds","cn":"常构成复合词 ) a person who works, especially one who does a particular kind of work 工作者；人员"},{"en":"a person who is employed in a company or industry, especially sb who does physical work rather than organizing things or managing people","cn":"雇员；（尤指）劳工，工人"}]}},"words":{"oxford":{"phon":"wɜːd","pos":"noun","senses":[{"en":"a single unit of language which means sth and can be spoken or written","cn":"单词；词；字"},{"en":"a thing that you say; a remark or statement","cn":"说的话；话语；言语"}]}},"worries":{"oxford":{"phon":"ˈwʌri","pos":"verb","senses":[{"en":"to keep thinking about unpleasant things that might happen or about problems that you have","cn":"担心；担忧；发愁"},{"en":"to make sb/yourself anxious about sb/sth","cn":"使担心；使担忧；使发愁"}]}},"wondering":{"oxford":{"phon":"ˈwʌndə(r)","pos":"verb","senses":[{"en":"to think about sth and try to decide what is true, what will happen, what you should do, etc.","cn":"想知道；想弄明白；琢磨"},{"en":"used as a polite way of asking a question or asking sb to do sth （","cn":"礼貌地提问或请人做事时说）"}]}},"women":{"oxford":{"phon":"ˈwʊmən","pos":"noun","senses":[{"en":"an adult female human","cn":"成年女子；妇女"},{"en":"female humans in general （","cn":"泛指）女性"}]},"collins":{"senses":[{"pos":"","cn":"（woman 的复数）","en":"Women is the plural of woman."}]},"media":{"uk":"media/ldoce/hwd/bre/6/women0205.mp3","us":"media/ldoce/hwd/ame/0/laadwomen.mp3"}},"workstations":{"oxford":{"phon":"ˈwɜːksteɪʃn","pos":"noun","senses":[{"en":"the desk and computer at which a person works; one computer that is part of a computer network （","cn":"计算机）工作站"}]}},"worshipping":{"oxford":{"phon":"ˈwɜːʃɪp","pos":"noun","senses":[{"en":"the practice of showing respect for God or a god, by saying prayers, singing with others, etc; a ceremony for this （","cn":"对上帝或神的）崇拜，敬仰，礼拜"},{"en":"a strong feeling of love and respect for sb/sth","cn":"崇拜；崇敬；爱慕"}]}},"wondered":{"oxford":{"phon":"ˈwʌndə(r)","pos":"verb","senses":[{"en":"to think about sth and try to decide what is true, what will happen, what you should do, etc.","cn":"想知道；想弄明白；琢磨"},{"en":"used as a polite way of asking a question or asking sb to do sth （","cn":"礼貌地提问或请人做事时说）"}]}},"woolens":{"oxford":{"phon":"ˈwʊlənz","pos":"noun","senses":[{"en":"clothes made of wool, especially knitted clothes （","cn":"尤指针织的）毛衣"}]}},"workplaces":{"oxford":{"phon":"ˈwɜːkpleɪs","pos":"noun","senses":[{"en":"the office, factory, etc. where people work","cn":"工作场所"}]}},"worthies":{"oxford":{"phon":"ˈwɜːði","pos":"adjective","senses":[{"en":"( formal ) having the qualities that deserve sb/sth","cn":"值得（或应得）… 的"},{"en":"having qualities that deserve your respect, attention or admiration","cn":"值得尊敬的；值得注意的；值得敬仰的"}]}},"woods":{"oxford":{"phon":"wʊd","pos":"noun","senses":[{"en":"the hard material that the trunk and branches of a tree are made of; this material when it is used to build or make things with, or as a fuel","cn":"木；木头；木料；木材；木柴"},{"en":"an area of trees, smaller than a forest","cn":"树林；林地"}]}},"worked":{"oxford":{"phon":"wɜːk","pos":"verb","senses":[{"en":"to do sth that involves physical or mental effort, especially as part of a job","cn":"做体力（或脑力）工作；劳动；干活"},{"en":"to have a job","cn":"受雇于；从事 … 工作"}]}},"worrisome":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人担忧的;使人发愁的","en":"Something that is worrisome causes people to worry."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"making you anxious","cn":"令人焦虑的"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41worrisome.mp3","us":"media/ldoce/hwd/ame/f/worrisome.mp3"},"examples":[{"en":"a worrisome problem","cn":"一个令人担心的问题"}],"oxford":{"phon":"ˈwʌrisəm","pos":"adjective","senses":[{"en":"that makes you worry","cn":"令人担心的；使人担忧的"}]}},"womanhood":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"女人;成年女性;女子成年期","en":"Womanhood is the state of being a woman rather than a girl, or the period of a woman's adult life.","ex":{"en":"Here she is on the threshold of womanhood","cn":"现在她将迈入成年期。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(泛指)女性；(某个国家或群体的)妇女","en":"You can refer to women in general or the women of a particular country or community as womanhood .","ex":{"en":"She symbolised for me the best of Indian womanhood.","cn":"在我看来，她代表着最优秀的印度女性。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the state of being a woman, not a man or a girl","cn":"女子成年〔的状态〕"},{"en":"women in general 〔","cn":"泛称〕女人"}]},"media":{"uk":"media/ldoce/hwd/bre/2/womanhood0205.mp3","us":"media/ldoce/hwd/ame/a/womanhood.mp3"},"examples":[{"en":"He watched his daughters grow to womanhood.","cn":"他看着自己的女儿们都长大成人了。"},{"en":"the womanhood of this country","cn":"这个国家的妇女"}],"oxford":{"phon":"ˈwʊmənhʊd","pos":"noun","senses":[{"en":"the state of being a woman, rather than a girl","cn":"成年女子的状态","ex":{"en":"He watched his daughters grow to womanhood.","cn":"他看着自己的女儿们都长大成人了。"}},{"en":"women in general","cn":"（统称）女人，女性","ex":{"en":"the womanhood of this country","cn":"这个国家的妇女"}}]}},"wondrous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"奇异的;美妙的;令人惊叹的","en":"If you describe something as wonderous, you mean it is strange and beautiful or impressive.","ex":{"en":"We were driven across this wondrous vast land of lakes and forests.","cn":"我们乘车穿越这片有着湖泊及森林的广袤而神奇的土地。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"good or impressive in a surprising way","cn":"奇妙的﹔令人惊叹的"}]},"vocab":{"pos":"adj adv","senses":[{"en":"The adjective wondrous is a great word to use when you're describing something amazing or delightful. You could talk about the wondrous view of the ocean from the cliffs where you're standing."}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41wondrous.mp3","us":"media/ldoce/hwd/ame/e/wondrous.mp3"},"oxford":{"phon":"ˈwʌndrəs","pos":"adjective","senses":[{"en":"strange, beautiful and impressive","cn":"奇异的；美好的；了不起的","ex":{"en":"It was a wondrous thing to see the sea for the first time.","cn":"第一次见到大海真是一件奇妙的事。"}}]}},"workaday":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"平凡的;平淡的","en":"Workaday means ordinary and not especially interesting or unusual.","ex":{"en":"Enough of fantasy, the workaday world awaited him.","cn":"天马行空地幻想了一番之后，等待他的是平淡无奇的现实世界。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"ordinary and not interesting","cn":"平凡的﹔平淡的"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41workaday.mp3","us":"media/ldoce/hwd/ame/d/workaday.mp3"},"examples":[{"en":"He promised to tackle the workaday matters affecting people’s daily lives.","cn":"他承诺要解决影响人们日常生活的一般问题。"}],"oxford":{"phon":"ˈwɜːkədeɪ","pos":"adjective","senses":[{"en":"ordinary; not very interesting","cn":"普通的；平凡的；平淡无奇的","ex":{"en":"This was a far cry from her normal workaday world.","cn":"这与她通常的平淡无奇的世界大不相同。"}}]}},"worsen":{"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"（使）变得更坏(或更糟);（使）恶化","en":"If a bad situation worsens or if something worsens it, it becomes more difficult, unpleasant, or unacceptable.","ex":{"en":"The security forces had to intervene to prevent the situation worsening","cn":"安全部队不得不介入，以防止局势进一步恶化。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to gradually become worse","cn":""},{"en":"to become gradually worse - use this especially about the quality or standard of something","cn":""},{"en":"if a bad situation worsens , or something worsens it, it becomes worse","cn":""}]},"collocations":{"phrases":["ADV. considerably, dramatically, markedly, significantly The problem has worsened considerably in recent months. | steadily | rapidly | sudd","VERB + WORSEN continue to The economic recession has continued to worsen."]},"media":{"uk":"media/ldoce/hwd/bre/c/worsen0205.mp3","us":"media/ldoce/hwd/ame/7/worsen.mp3"},"examples":[{"en":"Her health has worsened considerably since we last saw her.","cn":"自从我们上次见到她以来，她的身体差多了。"},{"en":"Staff shortages were worsened by the flu epidemic.","cn":"由于流感，职员短缺的情况更加严重了。"}],"oxford":{"phon":"ˈwɜːsn","pos":"verb","senses":[{"en":"to become or make something worse than it was before","cn":"（使）变得更坏，变得更糟，恶化","ex":{"en":"The political situation is steadily worsening.","cn":"政治局势在持续恶化。"}}]}},"woodcutter":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"伐木工；樵夫","en":"A woodcutter is someone who cuts down trees or who chops wood as their job."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone whose job is to cut down trees in a forest","cn":"伐木者"}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41woodcutter.mp3","us":"media/ldoce/hwd/ame/6/woodcutter.mp3"},"oxford":{"phon":"ˈwʊdkʌtə(r)","pos":"noun","senses":[{"en":"a person whose job is cutting down trees","cn":"伐木工"}]}},"wont":{"collins":{"senses":[{"pos":"","cn":"经常的;惯常的","en":"If someone is wont to do something, they often or regularly do it.","ex":{"en":"Both have committed their indiscretions, as human beings are wont to do.","cn":"两人都有失慎重，此乃人之常情。"}},{"pos":"","cn":"按惯常的做法;常常","en":"If someone does a particular thing as is their wont, they do that thing often or regularly.","ex":{"en":"Paul woke early, as was his wont.","cn":"保罗醒得很早，历来如此。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"used to say that it is someone’s habit to do something","cn":"就像某人惯常那样"},{"en":"to be likely to do something","cn":"有可能做某事"}]},"vocab":{"pos":"n","senses":[{"en":"A wont is a custom or habit, like my wont to drink at least ten cups of coffee a day. (In this particular example, some people might call my wont an addiction .)"}]},"media":{"uk":"media/ldoce/hwd/bre/6/wont_adj0205.mp3","us":"media/ldoce/hwd/ame/6/l2wont.mp3"},"examples":[{"en":"He was wont to fall asleep after supper.","cn":"他习惯吃完晚饭就睡觉。"},{"en":"She got up early, as was her wont.","cn":"她像惯常一样起得很早。"}],"oxford":{"phon":"wəʊnt","pos":"adjective","senses":[{"en":"in the habit of doing something","cn":"习惯于","ex":{"en":"He was wont to fall asleep after supper.","cn":"他习惯吃完晚饭就打盹。"}},{"en":"something a person often does","cn":"惯常做法；习惯","ex":{"en":"She got up early, as was her wont.","cn":"她像惯常一样起得很早。"},"pos":"noun"}]}},"world-weary":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"厌世的；对一切不感兴趣的","en":"A world-weary person no longer feels excited or enthusiastic about anything."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not feeling excited about anything anymore","cn":"厌世的"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41world-weary.mp3","us":"media/ldoce/hwd/ame/9/world-weary.mp3"},"oxford":{"phon":"ˈwɜːld wɪəri","pos":"adjective","senses":[{"en":"no longer excited by life; showing this","cn":"厌世的；厌弃人生的","ex":{"en":"a world-weary look","cn":"厌世的表情"}}]}},"wordplay":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"双关语;文字游戏","en":"Wordplay involves making jokes by using the meanings of words in an amusing or clever way."}]},"oxford":{"phon":"ˈwɜːdpleɪ","pos":"noun","senses":[{"en":"making jokes by using words in a clever and humorous way, especially by using a word that has two meanings, or different words that sound the same","cn":"巧妙的应答；双关语"}]}},"woebegone":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"悲伤的;忧伤的;哀伤的","en":"Someone who is woebegone is very sad.","ex":{"en":"She sniffed and looked woebegone.","cn":"她抽泣着，神情忧伤。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"looking very sad","cn":"愁眉苦脸的"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41woebegone.mp3","us":"media/ldoce/hwd/ame/7/woebegone.mp3"},"examples":[{"en":"a woebegone expression","cn":"悲伤的表情"},{"en":"her woebegone expression","cn":"她满脸的愁容"}],"oxford":{"phon":"ˈwəʊbɪɡɒn","pos":"adjective","senses":[{"en":"looking very sad","cn":"（神情）悲伤的，忧伤的；愁眉苦脸的","ex":{"en":"a woebegone expression","cn":"悲伤的表情"}}]}},"wormwood":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"蒿，洋艾，苦艾(味苦，可入药及制酒)","en":"Wormwood is a plant that has a very bitter taste and is used in making medicines and alcoholic drinks."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a plant with a bitter taste","cn":"苦艾〔一种植物〕"}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun wormwood to describe a strong-smelling, shrubby plant of the genus Artemisia."}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld41wormwood.mp3","us":"media/ldoce/hwd/ame/6/wormwood.mp3"},"oxford":{"phon":"ˈwɜːmwʊd","pos":"noun","senses":[{"en":"a plant with a bitter taste, used in making alcoholic drinks and medicines","cn":"蒿，洋艾（有些具苦味，可入药或用来制苦艾酒等）"}]}},"workstation":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（计算机）工作站","en":"A workstation is a screen and keyboard that are part of an office computer system."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"computer equipment, rather than the programs that make it work","cn":""},{"en":"an electronic machine that uses programs to store and deal with large amounts of information quickly, and which is used for a wide range of different jobs","cn":""},{"en":"personal computer; a computer that is usually used by one person in an office, at home, or in a school","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/workstation0205.mp3","us":"media/ldoce/hwd/ame/5/workstation.mp3"},"oxford":{"phon":"ˈwɜːksteɪʃn","pos":"noun","senses":[{"en":"the desk and computer at which a person works; one computer that is part of a computer network","cn":"个人工作区；（计算机）工作站"}]}},"worldly-wise":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"练达的;老于世故的；老成稳重的","en":"If you describe someone as worldly-wise, you mean they are experienced and know about the practical or social aspects of life, and are not easily shocked or impressed."}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"having a lot of experience and knowledge about life so that you are not easily shocked or deceived","cn":"老于世故的﹔善于处世的"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41worldly-wise.mp3","us":"media/ldoce/hwd/ame/9/worldly-wise.mp3"},"oxford":{"phon":"ˌwɜːldli ˈwaɪz","pos":"adjective","senses":[{"en":"having a lot of experience of life and therefore not easily shocked","cn":"善于处世的；老于世故的","ex":{"en":"She’s not as worldly-wise as she would have you believe.","cn":"她并不像她想让你相信的那样世故。"}}]}},"world-beater":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone or something that is the best at a particular activity","cn":"举世无双的人[物]﹔天下无敌的人[物]"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41world-beater.mp3","us":"media/ldoce/hwd/ame/f/world-beater.mp3"},"oxford":{"phon":"ˈwɜːld biːtə(r)","pos":"noun","senses":[{"en":"a person or thing that is better than all others","cn":"天下无双的人（或事物）"}]}},"womb":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"子宫","en":"A woman's womb is the part inside her body where a baby grows before it is born."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the part of a woman’s or female animal’s body where her baby grows before it is born","cn":"子宫"}]},"collocations":{"phrases":["ADJ. fertile | barren","VERB + WOMB carry sth in the nine months for which we are carried in our mothers' wombs | emerge from The baby's head was starting to emerge","WOMB + NOUN lining","PREP. in the/your ~ A scan determines the position of the baby in the womb.","PHRASES the lining/neck/wall of the womb"]},"media":{"uk":"media/ldoce/hwd/bre/9/womb0205.mp3","us":"media/ldoce/hwd/ame/2/womb.mp3"},"oxford":{"phon":"wuːm","pos":"noun","senses":[{"en":"the organ in women and female animals in which babies or young animals develop before they are born","cn":"子宫","ex":{"en":"A scan determines the position of the baby in the womb.","cn":"扫描检查可以确定胎儿在子宫中的位置。"}}]}},"workmanlike":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"出自匠人之手的；技艺纯熟但无创意的","en":"If you describe something as workmanlike, you mean that it has been done quite well and sensibly, but not in a particularly imaginative or original way.","ex":{"en":"Really it's a workmanlike conference rather than a dramatic one","cn":"会议的确开得有板有眼，但谈不上激动人心。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"done in a way which shows skill and hard work, but may not be exciting","cn":"娴熟卖力的〔但可能平淡无奇〕"}]},"media":{"uk":"media/ldoce/hwd/bre/4/brelasdeworkmanlike.mp3","us":"media/ldoce/hwd/ame/4/workmanlike.mp3"},"examples":[{"en":"The team put up a good workmanlike performance to win 1–0.","cn":"该队技术娴熟﹐表现卖力﹐以一比零获胜。"}],"oxford":{"phon":"ˈwɜːkmənlaɪk","pos":"adjective","senses":[{"en":"done, made, etc. in a way that is careful and complete and shows skill but is not usually very original or exciting","cn":"技术娴熟（但无新意）的","ex":{"en":"They’ve done a workmanlike job.","cn":"他们活儿做得很精细。"}}]}},"wobble":{"collins":{"senses":[{"pos":"VERB 动词","cn":"摇摆;摇晃","en":"If something or someone wobbles, they make small movements from side to side, for example because they are unsteady.","ex":{"en":"The table wobbled when I leaned on it","cn":"我往桌上一靠，桌子就摇晃了起来。"}},{"pos":"VERB 动词","cn":"(人或政府)动摇，摇摆不定","en":"If a person or government wobbles, they suddenly appear less secure or less sure about something.","ex":{"en":"The coach began to wobble when some of his team selections provoked much baffled comment.","cn":"当一些队员的入选招致许多不解的非议时，教练开始动摇了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to go to a different place, or change the position of your body","cn":""},{"en":"to move slowly from one side to the other","cn":""},{"en":"to move repeatedly from one side to another, with small gentle movements","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/wobble0205.mp3","us":"media/ldoce/hwd/ame/d/wobble.mp3"},"examples":[{"en":"Yesterday the president showed the first signs of wobbling over the issue.","cn":"昨天总统第一次在这个问题上表现得有些摇摆不定。"},{"en":"The team is experiencing a mid-season wobble.","cn":"这支队正处于赛季中期的不稳定状态。"}],"oxford":{"phon":"ˈwɒbl","pos":"verb","senses":[{"en":"to move from side to side in an unsteady way; to make something do this","cn":"（使）摇摆，摇晃","g":"[intransitive, transitive]","lab":"figurative","ex":{"en":"This chair wobbles.","cn":"这把椅子不稳。"}},{"en":"to go in a particular direction while moving from side to side in an unsteady way","cn":"一摇一摆地走","g":"[intransitive]","ex":{"en":"He wobbled off on his bike.","cn":"他摇摇晃晃地骑着自行车走了。"}},{"en":"to hesitate or lose confidence about doing something","cn":"犹豫不决；信心动摇","g":"[intransitive]","ex":{"en":"Yesterday the president showed the first signs of wobbling over the issue.","cn":"昨天总统第一次在这个问题上表现得有些摇摆不定。"}},{"en":"a slight unsteady movement from side to side","cn":"松动；摇晃","g":"[usually singular]","ex":{"en":"The handlebars developed a wobble.","cn":"这车把松动摇晃了。"},"pos":"noun"},{"en":"a moment when you hesitate or lose confidence about something","cn":"犹豫不决；信心动摇","ex":{"en":"The team is experiencing a mid-season wobble.","cn":"这支队正处于赛季中期的不稳定状态。"},"pos":"noun"}]}},"woollen":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"毛料的；羊毛制的;羊毛混纺的","en":"Woollen clothes or materials are made from wool or from a mixture of wool and artificial fibres.","ex":{"en":"...thick woollen socks.","cn":"厚厚的羊毛袜"}},{"pos":"N-PLURAL 复数名词","cn":"毛料衣服;(尤指)毛衣,羊毛衫","en":"Woollens are clothes, especially sweaters, that are made of wool.","ex":{"en":"...winter woollens.","cn":"冬天穿的毛衣"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"made of wool","cn":"羊毛制的﹐毛料的"},{"en":"relating to making cloth from wool","cn":"毛纺的﹔毛纺业的"}]},"media":{"uk":"media/ldoce/hwd/bre/c/woollen0205.mp3","us":"media/ldoce/hwd/ame/1/laadwoollen.mp3"},"examples":[{"en":"the woollen industry","cn":"毛纺业"},{"en":"a woollen blanket","cn":"毛毯"}],"oxford":{"phon":"ˈwʊlən","pos":"adjective","senses":[{"en":"made of wool","cn":"毛纺的；羊毛的；毛料的；毛线的","g":"[usually before noun]","ex":{"en":"a woollen blanket","cn":"毛毯"}},{"en":"involved in making cloth from wool","cn":"毛纺的；毛纺织业的","g":"[only before noun]","ex":{"en":"a woollen mill","cn":"毛纺厂"}}]}},"workhouse":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(英国17至19世纪的)济贫院，劳动救济所","en":"In Britain, in the seventeenth to nineteenth centuries, a workhouse was a place where very poor people could live and do unpleasant jobs in return for food. People use the workhouse to refer to these places in general.","ex":{"en":"...a struggling Shropshire family which lived in fear of the workhouse.","cn":"生活在对济贫院的恐惧之中、艰苦挣扎着的什罗普郡一家人"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a building in Britain in the past where very poor people lived if they had nowhere else to go","cn":"济贫院﹐救贫院〔英国旧时供无家可归的赤贫之人居住之处〕"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41workhouse.mp3","us":"media/ldoce/hwd/ame/a/workhouse.mp3"},"oxford":{"phon":"ˈwɜːkhaʊs","pos":"noun","senses":[{"en":"(in England and Wales in the past) a building where very poor people were sent to live and given work to do","cn":"（英国旧时的）济贫院，劳动救济所"}]}},"workings":{"collocations":{"phrases":["ADJ. inner, internal the inner workings of a watch the internal workings of Parliament | basic | complex, detailed | financial","VERB + WORKINGS analyse, explore, investigate | lay bare, reveal, shed light on Their research aims to shed light on the workings of the hum"]}},"womankind":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(总称)女人，女子，女性","en":"You can refer to all women as womankind when considering them as a group."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"women considered together as a group","cn":"女性﹐妇女〔总称〕"}]},"media":{"uk":"media/ldoce/hwd/bre/5/womankind0205.mp3","us":"media/ldoce/hwd/ame/e/womankind.mp3"},"oxford":{"phon":"ˈwʊmənkaɪnd","pos":"noun","senses":[{"en":"women in general","cn":"（统称）女人，女性"}]}},"woo":{"collins":{"senses":[{"pos":"VERB 动词","cn":"寻求,争取(支持、选票等)","en":"If you woo people, you try to encourage them to help you, support you, or vote for you, for example by promising them things which they would like.","ex":{"en":"They wooed customers by offering low interest rates","cn":"他们靠提供低息来招揽客户。"}},{"pos":"VERB 动词","cn":"追求(女人);向(女人)求爱（或求婚）","en":"If a man woos a woman, he spends time with her and tries to persuade her to marry him.","ex":{"en":"The penniless author successfully wooed and married Fanny.","cn":"这位一文不名的作家向范妮求爱成功，和她结了婚。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to try to persuade someone to do something such as buy something from you, vote for you, or work for you – used in news reports","cn":"极力劝说〔某人做某事〕﹐争取…的支持﹐拉拢〔用于新闻报道〕"},{"en":"to try to persuade a woman to love you and marry you","cn":"向〔女子〕求爱[求婚]"}]},"vocab":{"pos":"v","senses":[{"en":"When you woo someone, you are being charming because you think that it will make them love you more. You want to win their heart, so you woo them, you flirty dog you."}]},"media":{"uk":"media/ldoce/hwd/bre/6/woo0205.mp3","us":"media/ldoce/hwd/ame/c/woo.mp3"},"examples":[{"en":"Voters are being wooed with promises of lower taxes.","cn":"通过许诺减低税收争取选民。"},{"en":"the Party’s efforts to woo working class voters","cn":"该党拉拢工薪阶层选民的努力"}],"oxford":{"phon":"wuː","pos":"verb","senses":[{"en":"to try to get the support of somebody","cn":"争取…的支持；寻求…的赞同","ex":{"en":"Voters are being wooed with promises of lower taxes.","cn":"通过许诺减低税收争取选民。"}},{"en":"to try to persuade a woman to love him and marry him","cn":"追求（异性）；求爱","lab":"old-fashioned"}]}},"wonderland":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(童话中的)仙境，奇境","en":"Wonderland is an imaginary world that exists in fairy stories."},{"pos":"N-COUNT 可数名词","cn":"非常奇妙的地方;极美丽的地方","en":"You can refer to a place as a wonderland when it is strange and very beautiful or exciting.","ex":{"en":"Children find Lake George Village a wonderland of amusement parks.","cn":"孩子们觉得乔治湖村是个绝妙的游乐园。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an imaginary place in stories 〔","cn":"故事中的〕仙境﹐奇境"}]},"media":{"uk":"media/ldoce/hwd/bre/4/ld41wonderland.mp3","us":"media/ldoce/hwd/ame/f/wonderland.mp3"},"oxford":{"phon":"ˈwʌndəlænd","pos":"noun","senses":[{"en":"an imaginary place in children’s stories","cn":"（童话中的）仙境，奇境"},{"en":"a place that is exciting and full of beautiful and interesting things","cn":"非常奇妙的地方；极为美丽的地方","ex":{"en":"a winter wonderland (= a beautiful scene with fresh snow)","cn":"冬雪仙境"}}]}},"workroom":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指制作东西的)工作间；作坊","en":"A person's workroom is a room where they work, especially when their work involves making things."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a room that you work in, especially making things, often in your home 〔","cn":"常指设在家中的〕工作室"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41workroom.mp3","us":"media/ldoce/hwd/ame/a/workroom.mp3"},"examples":[{"en":"The jeweller has a workroom at the back of his shop.","cn":"珠宝商在他的店铺后面有一间工场。"}],"oxford":{"phon":"ˈwɜːkruːm","pos":"noun","senses":[{"en":"a room in which work is done, especially work that involves making things","cn":"工作室；工场间；作坊","ex":{"en":"The jeweller has a workroom at the back of his shop.","cn":"珠宝商在他的店铺后面有一间作坊。"}}]}},"wombat":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(澳大利亚的)毛鼻袋熊","en":"A wombat is a type of furry animal which has very short legs and eats plants. Wombats are found in Australia."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an Australian animal like a small bear whose babies live in a pocket of skin on its body","cn":"袋熊〔产于澳大利亚〕"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41wombat.mp3","us":"media/ldoce/hwd/ame/7/wombat.mp3"},"oxford":{"phon":"ˈwɒmbæt","pos":"noun","senses":[{"en":"an Australian animal like a small bear, that carries its young in a pouch (= a pocket of skin) on the front of the mother’s body","cn":"毛鼻袋熊（体形像熊的澳大利亚有袋动物）"}]}},"wog":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"外国佬(对有色人种的蔑称)","en":"Wog is an extremely offensive word for anyone whose skin is not white."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very offensive word for a black person. Do not use this word.","cn":"黑鬼"}]},"media":{"uk":"media/ldoce/hwd/bre/8/ld41wog.mp3","us":"media/ldoce/hwd/ame/8/ld41wog.mp3"},"examples":[{"en":"A flu wog struck.","cn":"突患流感。"}],"oxford":{"phon":"wɒɡ","pos":"noun","senses":[{"en":"a very offensive word for a person who does not have white skin","cn":"外国佬（对有色人种的蔑称）","lab":"British English, taboo, offensive, slang，，，，，，"},{"en":"an offensive word for a person from southern Europe or whose parents came from southern Europe","cn":"南蛮子（对南欧人或其后裔的蔑称）","lab":"Australian English, taboo, offensive, slang，，，，，，"},{"en":"an illness, usually one that is not very serious","cn":"病；小病","lab":"Australian English, informal，，","ex":{"en":"A flu wog struck.","cn":"突患流感。"}}]}},"worm":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"蠕虫","en":"A worm is a small animal with a long thin body, no bones and no legs."},{"pos":"N-PLURAL 复数名词","cn":"(动物或人体内的)寄生虫，肠虫","en":"If animals or people have worms, worms are living in their intestines."},{"pos":"VERB 动词","cn":"给(动物)驱寄生虫","en":"If you worm an animal, you give it medicine in order to kill the worms that are living in its intestines.","ex":{"en":"I worm all my birds in early spring","cn":"早春的时候我给我所有的鸟打虫。"}},{"pos":"VERB 动词","cn":"艰难地移动；蜷缩着身子走","en":"If you worm your way somewhere, you move there with difficulty, twisting or bending your body or making it narrow.","ex":{"en":"I had to worm my way out sideways from the bench in a ridiculous, undignified fashion","cn":"我侧着身子艰难地从长凳上移开，那个样子很可笑，很不雅观。"}},{"pos":"VERB 动词","cn":"(通常为欺骗别人或得到好处)逐渐取得(成功或好感)","en":"If you say that someone is worming their way to success, or is worming their way into someone else's affection, you disapprove of the way that they are gradually making someone trust them or like them, often in order to deceive them or gain some advantage.","ex":{"en":"She never misses a chance to worm her way into the public's hearts","cn":"她从不放过任何博取公众欢心的机会。"}},{"pos":"N-SING 单数名词","cn":"可怜虫;软蛋;卑鄙的家伙","en":"If you call a person a worm, you are insulting them by saying that they have a very weak or unpleasant character and you have no respect for them."},{"pos":"N-COUNT 可数名词","cn":"“蠕虫”病毒","en":"A worm is a computer program that contains a virus which duplicates itself many times in a network."},{"pos":"PHRASE 短语","cn":"极为棘手的问题","en":"If you say that someone is opening a can of worms, you are warning them that they are planning to do or talk about something which is much more complicated, unpleasant, or difficult than they realize and which might be better left alone.","ex":{"en":"You've opened up a whole new can of worms here I think. We could have a whole debate on student loans and grants","cn":"我认为你在此引发了一个极为棘手的全新问题，我们可能会就学生贷款和助学金展开一次大辩论。"}},{"pos":"PHRASE 短语","cn":"蠕虫被踩，也会翻腾；兔子急了也咬人","en":"If you say that the worm turns, you mean that someone who usually obeys another person or accepts their bad behaviour unexpectedly starts resisting that person or expresses their anger.","ex":{"en":"Now the worm turns, and his wife Elizabeth chucks him out and takes a lover herself.","cn":"现在他妻子伊丽莎白被逼急了，把他撵了出去，自己找了个情人。"}},{"pos":"","cn":"","en":"相关词组：worm out of"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"full of problems and difficult to deal with","cn":""},{"en":"use this about an activity or plan that is full of unexpected problems which make it very difficult","cn":""},{"en":"an activity or subject where you have to be very careful, because it is full of hidden problems and risks, so that it is very easy to make mistakes or upset people","cn":""}]},"collocations":{"phrases":["WORM + VERB burrow, crawl Worms burrow down through the soil. | wriggle, writhe The worm was wriggling on the hook.","WORM + NOUN cast"]},"media":{"uk":"media/ldoce/hwd/bre/b/brelasdeworm.mp3","us":"media/ldoce/hwd/ame/0/worm1.mp3"},"examples":[{"en":"She wormed her way through the crowd to the reception desk.","cn":"她在人群中左拐右绕走到服务台。"},{"en":"He managed to worm his way into her life.","cn":"他设法骗取信任进入了她的生活。"}],"oxford":{"phon":"wɜːm","pos":"noun","senses":[{"en":"a long, thin creature with a soft body and no bones or legs","cn":"蠕虫","g":"[countable]","ex":{"en":"birds looking for worms","cn":"觅食蠕虫的鸟"}},{"en":"long, thin creatures that live inside the bodies of humans or animals and can cause illness","cn":"（人或动物体内的）寄生虫；肠虫","g":"[plural]","ex":{"en":"The dog has worms.","cn":"这条狗体内有寄生虫。"}},{"en":"the young form of an insect when it looks like a short worm","cn":"（昆虫的）幼虫","g":"[countable]","ex":{"en":"This apple is full of worms.","cn":"这个苹果生满了虫子。"}},{"en":"a computer program that is a type of virus and that spreads across a network by copying itself","cn":"蠕虫；蠕虫程序；蠕虫病毒","g":"[countable]","lab":"computing"},{"en":"a person you do not like or respect, especially because they have a weak character and do not behave well towards other people","cn":"懦夫；可怜虫","g":"[countable, usually singular]","lab":"informal, disapproving，，"},{"en":"to use a twisting and turning movement, especially to move through a narrow or crowded place","cn":"蠕动，曲折行进（尤指通过狭窄或拥挤的地方）","ex":{"en":"She wormed her way through the crowd to the reception desk.","cn":"她在人群中左拐右绕走到服务台。"},"pos":"verb"},{"en":"to give an animal medicine that makes worms pass out of its body in the faeces","cn":"给（动物）驱肠虫","pos":"verb"}]}},"worksheet":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"活页练习题","en":"A worksheet is a specially prepared page of exercises designed to improve your knowledge or understanding of a particular subject."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of paper with questions and exercises for students","cn":"活页练习题"}]},"media":{"uk":"media/ldoce/hwd/bre/7/brelasdeworksheet.mp3","us":"media/ldoce/hwd/ame/8/laadworksheet.mp3"},"oxford":{"phon":"ˈwɜːkʃiːt","pos":"noun","senses":[{"en":"a piece of paper or an electronic document on which there is a series of questions and exercises to be done by a student","cn":"（学生做的）活页练习题，电子作业文档"},{"en":"a piece of paper or an electronic document on which work that has been done or has to be done is recorded","cn":"工作记录（或进度）表；电子工作记录（或进度）表"}]}},"workman":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(建造、维修房屋等的)工匠，工人","en":"A workman is a man who works with his hands, for example building or repairing houses or roads.","ex":{"en":"In University Square workmen are building a steel fence","cn":"在大学广场上，工人们正在修建钢栅栏。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who does physical work such as building, repairing things etc 〔","cn":"建筑﹑维修等的〕工匠﹐工人"}]},"collocations":{"phrases":["ADJ. good, skilled | council","QUANT. gang A gang of council workmen has been digging a hole in the road."]},"media":{"uk":"media/ldoce/hwd/bre/3/workman0205.mp3","us":"media/ldoce/hwd/ame/e/workman.mp3"},"examples":[{"en":"a good/bad workman","cn":"工作好的/差的人"}],"oxford":{"phon":"ˈwɜːkmən","pos":"noun","senses":[{"en":"a man who is employed to do physical work","cn":"男工人；工匠","ex":{"en":"A gang of workmen were shovelling rubble into a truck.","cn":"一群工人正往卡车上铲碎石子。"}},{"en":"a person who works in the way mentioned","cn":"工作…的人","ex":{"en":"a good/bad workman","cn":"工作好的／差的人"}}]}},"woe":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"悲痛;悲哀;哀伤","en":"Woe is very great sadness.","ex":{"en":"He listened to my tale of woe","cn":"他听我诉说悲伤的故事。"}},{"pos":"N-PLURAL 复数名词","cn":"麻烦;问题;困难","en":"You can refer to someone's problems as their woes .","ex":{"en":"He did not tell his relatives and friends about his woes.","cn":"他没有告诉亲友自己的烦恼。"}},{"pos":"","cn":"","en":"woe betide→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the problems and troubles affecting someone","cn":"困难﹔难题"},{"en":"great sadness","cn":"哀伤﹐悲痛"},{"en":"used to say that you are extremely unhappy or in a difficult situation","cn":"我好苦啊"}]},"vocab":{"pos":"n","senses":[{"en":"\"O, woe is me!\" This line is from Shakespeare. When Hamlet scorns Ophelia, she utters these words to express the grief and despair that will soon drive her to suicide."}]},"media":{"uk":"media/ldoce/hwd/bre/7/woe0205.mp3","us":"media/ldoce/hwd/ame/c/woe.mp3"},"examples":[{"en":"Thanks for listening to my woes.","cn":"谢谢您听我诉说不幸的遭遇。"},{"en":"Woe betide anyone who gets in her way!","cn":"谁挡住她的路谁就会遭殃！"}],"oxford":{"phon":"wəʊ","pos":"noun","senses":[{"en":"the troubles and problems that somebody has","cn":"麻烦；问题；困难","g":"[plural]","ex":{"en":"financial woes","cn":"财政困难"}},{"en":"great unhappiness","cn":"痛苦；苦恼；悲伤；悲哀","g":"[uncountable]","ex":{"en":"a tale of woe","cn":"悲惨的故事"}}]}},"woodpile":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"柴火堆","en":"A woodpile is a pile of wood that is intended to be burnt on a fire as fuel."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a pile of wood to be burned in a fire","cn":"木柴堆"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41woodpile.mp3","us":"media/ldoce/hwd/ame/c/woodpile.mp3"},"oxford":{"phon":"ˈwʊdpaɪl","pos":"noun","senses":[{"en":"a pile of wood that will be used for fuel","cn":"木柴堆"}]}},"woeful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人或事物）悲惨的，忧伤的，哀伤的","en":"If someone or something is woeful, they are very sad.","ex":{"en":"...a woeful ballad.","cn":"忧伤的情歌"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"恶劣的;糟糕的;不合意的","en":"You can use woeful to emphasize that something is very bad or undesirable.","ex":{"en":"Such attitudes are the product of woeful ignorance.","cn":"这样的态度是极度无知造成的。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very bad or serious","cn":"极坏的﹐糟透的﹔极严重的"},{"en":"very sad","cn":"哀伤的"}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41woeful.mp3","us":"media/ldoce/hwd/ame/4/woeful.mp3"},"examples":[{"en":"She displayed a woeful ignorance of the rules.","cn":"她对这些条例表现出可悲的无知。"},{"en":"woeful tales of broken romances","cn":"破裂爱情的悲惨故事"}],"oxford":{"phon":"ˈwəʊfl","pos":"adjective","senses":[{"en":"very bad or serious; that you disapprove of","cn":"糟糕的；严重的；不合意的","g":"[usually before noun]","ex":{"en":"She displayed a woeful ignorance of the rules.","cn":"她对这些条例表现出可悲的无知。"}},{"en":"very sad","cn":"悲惨的；忧伤的","lab":"literary or formal","ex":{"en":"a woeful face","cn":"忧伤的面孔"}}]}},"wordy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"啰唆的；冗长的；堆砌词藻的","en":"If you describe a person's speech or something that they write as wordy, you disapprove of the fact that they use too many words, especially words which are very long, formal, or literary.","ex":{"en":"The chapter is mostly wordy rhetoric.","cn":"这一章多为冗长的华丽词藻。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"using too many words","cn":"话太多的﹐冗长的"}]},"media":{"uk":"media/ldoce/hwd/bre/7/wordy0205.mp3","us":"media/ldoce/hwd/ame/6/wordy.mp3"},"examples":[{"en":"a wordy and repetitive essay","cn":"一篇冗长繁复的文章"},{"en":"a wordy explanation","cn":"冗长的解释"}],"oxford":{"phon":"ˈwɜːdi","pos":"adjective","senses":[{"en":"using too many words, especially formal ones","cn":"话多的；冗长的；啰嗦的","ex":{"en":"a wordy and repetitive essay","cn":"一篇冗长繁复的文章"}}]}},"woozy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"眩晕的;头昏脑胀的","en":"If you feel woozy, you feel rather weak and unsteady and cannot think clearly.","ex":{"en":"The fumes made them woozy.","cn":"烟熏得他们头晕。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"feeling weak and unsteady","cn":"虚弱的﹔眩晕的"}]},"media":{"uk":"media/ldoce/hwd/bre/a/woozy0205.mp3","us":"media/ldoce/hwd/ame/c/woozy.mp3"},"examples":[{"en":"Giving blood makes me feel really woozy.","cn":"献血后我会觉得头晕目眩。"}],"oxford":{"phon":"ˈwuːzi","pos":"adjective","senses":[{"en":"feeling unsteady, confused and unable to think clearly","cn":"眩晕的；头昏的；晕头涨脑的"},{"en":"feeling as though you might vomit","cn":"恶心的；要呕吐的","lab":"especially North American English"}]}},"wolfhound":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"猎狼犬","en":"A wolfhound is a type of very large dog."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of extremely large dog","cn":"猎狼犬"}]},"media":{"uk":"media/ldoce/hwd/bre/e/ld41wolfhound.mp3","us":"media/ldoce/hwd/ame/7/wolfhound.mp3"},"examples":[{"en":"an Irish wolfhound","cn":"爱尔兰猎狼犬"}],"oxford":{"phon":"ˈwʊlfhaʊnd","pos":"noun","senses":[{"en":"a very large, tall dog with long hair and long legs, originally used for hunting wolves","cn":"猎狼犬","ex":{"en":"an Irish wolfhound","cn":"爱尔兰猎狼犬"}}]}},"woodworm":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"木蛀虫;木蠹","en":"Woodworm are very small creatures which make holes in wood by eating it."},{"pos":"N-UNCOUNT 不可数名词","cn":"（尤指房子木建部分或家具的）木蛀虫害，木蠹虫害","en":"Woodworm is damage caused to wood, especially to the wooden parts of a house or to furniture, by woodworm making holes in the wood.","ex":{"en":"...treating the ground floor of a house for woodworm.","cn":"处理房子一层的木蛀虫害"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small insect that makes holes in wood","cn":"木蛀虫﹐木蠹"},{"en":"the damage that is caused to wood by this creature","cn":"木蛀虫害"}]},"media":{"uk":"media/ldoce/hwd/bre/a/woodworm0205.mp3","us":"media/ldoce/hwd/ame/2/woodworm.mp3"},"examples":[{"en":"The beams are riddled with woodworm.","cn":"这些木梁被蛀虫蛀得都是洞。"}],"oxford":{"phon":"ˈwʊdwɜːm","pos":"noun","senses":[{"en":"a small worm that eats wood, making a lot of small holes in it","cn":"木蛀虫；木蠹","g":"[countable]"},{"en":"the damage caused by woodworms","cn":"木蛀虫害；木蠹虫害","g":"[uncountable]","ex":{"en":"The beams are riddled with woodworm.","cn":"这些木梁被蛀虫蛀得都是洞。"}}]}},"wow":{"collins":{"senses":[{"pos":"EXCLAM 感叹语","cn":"(表示赞叹、非常吃惊或喜悦)哇，呀","en":"You can say 'wow' when you are very impressed, surprised, or pleased.","ex":{"en":"I thought, 'Wow, what a good idea'.","cn":"我想：“哇，多好的主意呀。”"}},{"pos":"VERB 动词","cn":"使叫绝;博得…的称赞","en":"You say that someone wows people when they give an impressive performance and fill people with enthusiasm and admiration.","ex":{"en":"Ben Tankard wowed the crowd with his jazz.","cn":"本·坦卡德的爵士乐使众人为之叫绝。"}}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"used when you think something is very impressive or surprising","cn":"呀﹐哇〔表示非常赞叹或惊奇〕"},{"en":"to make people admire you a lot","cn":"使喝彩﹐博得…的称赞"},{"en":"a great success","cn":"极大的成功"}]},"vocab":{"pos":"v n","senses":[{"en":"When you wow your teacher, you get him really excited about your three paragraph essay. To wow is to impress."}]},"media":{"uk":"media/ldoce/hwd/bre/e/wow_interjecti0205.mp3","us":"media/ldoce/hwd/ame/4/wow1.mp3"},"examples":[{"en":"He wowed audiences around the country with his new show.","cn":"他以他的新节目博得了全国各地观众的交口称赞。"},{"en":"Don't worry. You'll be a wow.","cn":"别担心。你会一鸣惊人的。"}],"oxford":{"phon":"waʊ","pos":"exclamation","senses":[{"en":"used to show that you are very surprised or impressed by somebody/something","cn":"（表示极为惊奇或钦佩）哇，呀","ex":{"en":"Wow! You look terrific!","cn":"哇！你的样子太酷了！"}},{"en":"to impress somebody very much, especially with a performance","cn":"（尤指以表演）博得…的称赞，使喝彩，使叫绝","ex":{"en":"He wowed audiences around the country with his new show.","cn":"他以他的新节目博得了全国各地观众的交口称赞。"},"pos":"verb"},{"en":"a great success","cn":"极大的成功；一鸣惊人之举","g":"[singular]","lab":"informal","ex":{"en":"Don't worry. You'll be a wow.","cn":"别担心。你会一鸣惊人的。"},"pos":"noun"},{"en":"slow changes in the pitch of sound played in a sound recording","cn":"（录音中缓慢出现的）走调，失真，颤动","g":"[uncountable]","lab":"specialist","pos":"noun"}]}},"workmate":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同事;工友","en":"Your workmates are the people you work with.","ex":{"en":"My workmates, and, even more, the management, didn't want me to leave.","cn":"我的同事，甚至包括管理层都不想让我离开。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who you work with in a company or organization, for example someone working in the same office, or someone teaching in the same school","cn":""},{"en":"someone who you work with. Workmate is more informal than colleague","cn":""},{"en":"someone who you work with","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41workmate.mp3","us":"media/ldoce/hwd/ame/d/ld41workmate.mp3"},"oxford":{"phon":"ˈwɜːkmeɪt","pos":"noun","senses":[{"en":"a person that you work with, often doing the same job, in an office, a factory, etc.","cn":"一起工作的人；同事；工友","ex":{"en":"Her workmates organized a leaving party for her last day in the office.","cn":"同事为她举办了欢送会，纪念她在办公室工作的最后一天。"}}]}},"work-shy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"懒惰的;不愿工作的","en":"If you describe someone as work-shy, you disapprove of them because you think they are lazy and do not want to work.","ex":{"en":"He is a morose, work-shy layabout.","cn":"他是个整天垂头丧气、游手好闲的人。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not liking work or physical activity, or not making any effort to do anything","cn":""},{"en":"lazy and not doing enough work. Idle sounds rather formal and is becoming old-fashioned. In everyday English, people usually use lazy","cn":""},{"en":"lazy and living a comfortable life","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41work-shy.mp3","us":"media/ldoce/hwd/ame/1/ld41work-shy.mp3"},"oxford":{"phon":"ˈwɜːk ʃaɪ","pos":"adjective","senses":[{"en":"unwilling to work","cn":"不愿工作的；怕干活的；懒惰的"}]}},"workmanship":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"工艺;手艺","en":"Workmanship is the skill with which something is made and which affects the appearance and quality of the finished object.","ex":{"en":"The problem may be due to poor workmanship","cn":"问题可能在于工艺太差。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"skill in making things, especially in a way that makes them look good 〔","cn":"尤指精细的〕工艺﹐手艺"}]},"vocab":{"pos":"n","senses":[{"en":"The noun workmanship can describe the hard work and skill that go into making something or working at a task — and it can also describe a quality of a handmade object that is skillfully crafted."}]},"collocations":{"phrases":["ADJ. exquisite, fine, good, quality | bad, crude, defective, faulty, poor, shoddy","VERB + WORKMANSHIP admire I was admiring the exquisite workmanship in the mosaic. | criticise","PREP. ~ on He accused the garage of shoddy workmanship on the bodywork.","PHRASES the quality/standard of workmanship"]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdeworkmanship.mp3","us":"media/ldoce/hwd/ame/f/workmanship.mp3"},"examples":[{"en":"Our buyers insist on high standards of workmanship and materials.","cn":"我们的买主对工艺和材料坚持要高标准。"}],"oxford":{"phon":"ˈwɜːkmənʃɪp","pos":"noun","senses":[{"en":"the skill with which somebody makes something, especially when this affects the way it looks or works","cn":"手艺；技艺；工艺","ex":{"en":"Our buyers insist on high standards of workmanship and materials.","cn":"我们的买主对工艺和材料坚持要高标准。"}}]}},"workaholic":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"工作狂","en":"A workaholic is a person who works most of the time and finds it difficult to stop working in order to do other things."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who wants to work all the time and who cannot relax when they are not working","cn":""},{"en":"someone who is industrious works hard and effectively","cn":""},{"en":"someone who is dedicated works very hard at something because they care about it a lot, even though the job is difficult or does not earn them much money","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A workaholic is someone who can't stop working. Workaholics are obsessed with working to an unhealthy degree."}]},"media":{"uk":"media/ldoce/hwd/bre/7/workaholic0205.mp3","us":"media/ldoce/hwd/ame/3/workaholic.mp3"},"oxford":{"phon":"ˌwɜːkəˈhɒlɪk","pos":"noun","senses":[{"en":"a person who works very hard and finds it difficult to stop working and do other things","cn":"工作狂；工作迷；醉心于工作的人"}]}},"womanly":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"成熟女子特有的;有女人味儿的；适合女人的","en":"People describe a woman's behaviour, character, or appearance as womanly when they like it because they think it is typical of, or suitable for, a woman rather than a man or girl.","ex":{"en":"She had a classical, womanly shape.","cn":"她拥有典型的熟女身材。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"relating to women or girls","cn":""},{"en":"used about qualities that are considered to be typical of women","cn":""},{"en":"behaving, dressing etc in a way that is thought to be typical of or suitable for a woman – used to show approval 〔","cn":"行为﹑衣着等〕有女子气质的﹐有女人味的〔含褒义〕"}]},"media":{"uk":"media/ldoce/hwd/bre/7/womanly0205.mp3","us":"media/ldoce/hwd/ame/3/womanly.mp3"},"examples":[{"en":"a soft womanly figure","cn":"婀娜多姿的体态"},{"en":"womanly qualities","cn":"女子的特性"}],"oxford":{"phon":"ˈwʊmənli","pos":"adjective","senses":[{"en":"behaving, dressing, etc. in a way that people think is typical of or very suitable for a woman","cn":"女性特有的；女子般的；适合女人的","ex":{"en":"womanly qualities","cn":"女子的特性"}}]}},"woodlouse":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"潮虫","en":"A woodlouse is a very small grey creature with a hard body and fourteen legs. Woodlice live in damp places."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small grey creature like an insect that lives under wood, stones etc 〔","cn":"生活在木头﹑石块等下面的〕潮虫"}]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41woodlouse.mp3","us":"media/ldoce/hwd/ame/0/ld41woodlouse.mp3","img":["media/thumb/woodlouse.jpg"]},"oxford":{"phon":"ˈwʊdlaʊs","pos":"noun","senses":[{"en":"a small grey creature like an insect, with a hard shell, that lives in decaying wood or wet soil","cn":"潮虫"}]}},"worthy":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"值得…的;应该获得…的","en":"If a person or thing is worthy of something, they deserve it because they have the qualities or abilities required.","ex":{"en":"The bank might think you're worthy of a loan","cn":"银行也许会认为你具备贷款的条件。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"值得尊敬的;可敬的；令人称许的","en":"A worthy person or thing is approved of by most people in society and considered to be morally respectable or correct.","ex":{"en":"...worthy members of the community","cn":"团体中德高望重者"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"deserving respect from people","cn":"值得尊敬的﹔值得赞赏的"},{"en":"to deserve to be thought about or treated in a particular way","cn":"值得…的"},{"en":"to be as good as something that a particular person would do","cn":"可与某人相媲美"}]},"vocab":{"pos":"n adj","senses":[{"en":"Use the adjective worthy to describe the good causes to which you donate a little money each year. Their admirable qualities are what make them worthy ."}]},"collocations":{"phrases":["VERBS be, seem | consider sth, deem sth, judge sth, think sth","ADV. most, very, well | entirely, wholly | hardly, scarcely The matter is scarcely worthy of the managing director's time. | enough We thoug","PREP. of It's a matter worthy of our attention."]},"media":{"uk":"media/ldoce/hwd/bre/b/worthy_n0205.mp3","us":"media/ldoce/hwd/ame/3/worthy1.mp3"},"examples":[{"en":"He gave a speech that was worthy of Martin Luther King.","cn":"他做了一次典型的马丁 · 路德 · 金式的演讲。"},{"en":"No composer was considered worthy of the name until he had written an opera.","cn":"作曲家直到写出一部歌剧来才被认为是名副其实。"}],"oxford":{"phon":"ˈwɜːði","pos":"adjective","senses":[{"en":"having the qualities that deserve somebody/something","cn":"值得（或应得）…的","lab":"formal","ex":{"en":"Very few of his ideas are worthy of further attention.","cn":"他的想法中很少有值得进一步关注的。"}},{"en":"having qualities that deserve your respect or attention","cn":"值得尊敬的；值得注意的","g":"[usually before noun]","ex":{"en":"The money we raise will be going to a very worthy cause.","cn":"我们筹集的钱款将用于非常崇高的事业。"}},{"en":"having good qualities but not very interesting or exciting","cn":"值得尊敬的，有价值的（但不太令人感兴趣或激动的）","ex":{"en":"her worthy but dull husband","cn":"她那为人正派却呆板的丈夫"}},{"en":"typical of what a particular person or thing might do, give, etc.","cn":"有（某人或事物）的典型特征","ex":{"en":"He gave a speech that was worthy of Martin Luther King.","cn":"他作了一次典型的马丁·路德·金式的演讲。"}},{"en":"deserving, or suitable for, the thing mentioned","cn":"值得…的；适于…的","ex":{"en":"trustworthy","cn":"值得信任的"}},{"en":"an important person","cn":"要人；大人物；知名人士","ex":{"en":"a meeting attended by local worthies","cn":"当地知名人士参加的会议"},"pos":"noun"}]}},"workload":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(人或组织的)工作量，工作负荷","en":"The workload of a person or organization is the amount of work that has to be done by them.","ex":{"en":"The sudden cancellation of Mr Blair's trip was due to his heavy workload","cn":"布莱尔先生因为工作繁重而突然取消行程。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the amount of work that a person or organization has to do 〔","cn":"人或组织的〕工作量﹐工作负荷"}]},"collocations":{"phrases":["ADJ. enormous, heavy, huge | excessive | additional, extra, increased | lighter, reduced | administrative","VERB + WORKLOAD have She's got an increased workload this year. | expand, increase | ease, lighten, reduce An assistant one day a week would","WORKLOAD + VERB expand, increase Doctors are having to cope with an ever-expanding workload."]},"media":{"uk":"media/ldoce/hwd/bre/0/workload0205.mp3","us":"media/ldoce/hwd/ame/4/workload.mp3"},"examples":[{"en":"We have taken on extra staff to cope with the increased workload.","cn":"我们已经额外雇用员工来应付增加了的工作量。"},{"en":"a heavy workload","cn":"沉重的工作负担"}],"oxford":{"phon":"ˈwɜːkləʊd","pos":"noun","senses":[{"en":"the amount of work that has to be done by a particular person or organization","cn":"（某人或某组织的）工作量","lab":"British English","ex":{"en":"a heavy workload","cn":"沉重的工作负担"}}]}},"woodpecker":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"啄木鸟","en":"A woodpecker is a type of bird with a long sharp beak. Woodpeckers use their beaks to make holes in tree trunks."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a bird with a long beak that it uses to make holes in trees","cn":"啄木鸟"}]},"media":{"uk":"media/ldoce/hwd/bre/7/woodpecker0205.mp3","us":"media/ldoce/hwd/ame/7/woodpecker.mp3"},"oxford":{"phon":"ˈwʊdpekə(r)","pos":"noun","senses":[{"en":"a bird with a long beak that it uses to make holes in trees when it is looking for insects to eat","cn":"啄木鸟"}]}},"woof":{"collins":{"senses":[{"pos":"N-SING; SOUND 单数名词；声音词","cn":"（狗叫声）汪汪","en":"Woof is the sound that a dog makes when it barks.","ex":{"en":"The dogs sat there without even a woof","cn":"狗坐在那里，叫都没叫一声。"}}]},"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a word used for describing the sound a dog makes","cn":"汪汪〔形容狗吠声〕"},{"en":"the weft","cn":"纬纱﹐纬线"}]},"media":{"uk":"media/ldoce/hwd/bre/3/woof_interject0205.mp3","us":"media/ldoce/hwd/ame/b/l3woof.mp3"},"examples":[{"en":"‘Woof! Woof!’ he barked.","cn":""},{"en":"‘Woof! Woof!’ he barked. “","cn":"汪！汪！”它叫着。"}],"oxford":{"phon":"wʊf","pos":"exclamation","senses":[{"en":"a word used to describe the loud noise that a dog makes","cn":"（狗叫声）汪汪","ex":{"en":"‘Woof! Woof!’ he barked.","cn":"“汪！汪！”它叫着。"}},{"en":"to make the loud noise that a dog makes","cn":"（狗叫声）汪汪","pos":"verb"},{"en":"the loud noise that a dog makes","cn":"汪汪叫","g":"[countable]","lab":"informal","ex":{"en":"the distant woof of a dog","cn":"远处传来狗的叫声"},"pos":"noun"},{"en":"the threads that are twisted under and over the threads that are held on a loom (= a frame or machine for making cloth)","cn":"（织布机上的）纬线，纬纱","g":"[singular]","lab":"more frequent","pos":"noun"}]}},"wonky":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不直的；不平的；歪斜的","en":"If something is wonky, it is not straight or level.","ex":{"en":"...a tiny house with lots of little rooms, wonky floors and doors","cn":"有很多小房间、地板凹凸不平、门歪歪斜斜的小房子"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"unsteady or not straight or level","cn":"不稳的﹔歪斜的﹔不平的"}]},"vocab":{"pos":"adj","senses":[{"en":"Things that are wonky are a little bit crooked or wobbly — a table that isn't balanced right, a nose that's a bit out of place. Something that’s wonky isn’t necessarily broken; it’s just slightly “off.”"}]},"media":{"uk":"media/ldoce/hwd/bre/f/wonky0205.mp3","us":"media/ldoce/hwd/ame/1/ld41wonky.mp3"},"examples":[{"en":"a wonky chair","cn":"摇摇晃晃的椅子"},{"en":"a wonky table","cn":"摇摇晃晃的桌子"}],"oxford":{"phon":"ˈwɒŋki","pos":"adjective","senses":[{"en":"not steady; not straight","cn":"不稳的；摇晃的；歪斜的","ex":{"en":"a wonky chair","cn":"摇摇晃晃的椅子"}}]}},"worldly":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"尘世的;世俗的；现实的","en":"Worldly is used to describe things relating to the ordinary activities of life, rather than to spiritual things.","ex":{"en":"I think it is time you woke up and focused your thoughts on more worldly matters","cn":"我认为是该你清醒过来把思想集中到更为现实的问题上的时候了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"世故的;老成练达的","en":"Someone who is worldly is experienced and knows about the practical or social aspects of life.","ex":{"en":"He was different from anyone I had known, very worldly, everything that Dermot was not","cn":"他不同于我认识的任何一个人，非常老成，与德莫特完全相反。"}},{"pos":"ADJ 形容词","cn":"名利的","en":"Worldly is used to describe things relating to success, wealth, and possessions.","ex":{"en":"Today the media drive athletes to the view that the important thing is to gain worldly success.","cn":"现在，媒体使得运动员认为追名逐利是很重要的。"}},{"pos":"ADJ 形容词","cn":"物质的","en":"You can refer to someone's possessions as their worldly goods or possessions.","ex":{"en":"...a man who had given up all his worldly goods","cn":"放弃了所有财产的男子"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if you say that someone has been around , you mean that they have had experience of many different situations and many different types of people and so they can deal with new situations confidently and easily","cn":""},{"en":"to be someone who knows a lot about life, has had a lot of different experiences etc and is not easily shocked by things","cn":""},{"en":"someone who is sophisticated has a lot of knowledge and experience of clever, fashionable things, and shows this by the way they talk and behave","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"You can use the adjective worldly to describe people who have knowledge of many topics or experience in many areas. You don't have to travel the globe to be worldly ; reading and talking about many things with knowledge and enthusiasm is worldly too."}]},"media":{"uk":"media/ldoce/hwd/bre/8/worldly0205.mp3","us":"media/ldoce/hwd/ame/2/worldly.mp3"},"examples":[{"en":"At 15, he was more worldly than his older cousins who lived in the country.","cn":"他 15 岁时就比他那些居住在乡村的表兄们懂人情世故了。"},{"en":"your worldly goods (= the things that you own)","cn":"你个人的物品"}],"oxford":{"phon":"ˈwɜːldli","pos":"adjective","senses":[{"en":"connected with the world in which we live rather than with spiritual things","cn":"尘世的；世俗的；世事的","g":"[only before noun]","ex":{"en":"worldly success","cn":"世俗的成就"}},{"en":"having a lot of experience of life and therefore not easily shocked","cn":"生活经验丰富的；老成持重的；世故的","ex":{"en":"At 15, he was more worldly than his older cousins who lived in the country.","cn":"他 15 岁时就比他那些居住在乡村的表兄们懂人情世故了。"}}]}},"worrier":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"多虑的人;经常发愁的人","en":"If you describe someone as a worrier, you mean that they spend a lot of time thinking about problems that they have or unpleasant things that might happen."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the type of person who worries a lot, even when they do not need to","cn":""},{"en":"someone who worries too much","cn":""},{"en":"always very worried and nervous about unimportant things or about dangers that do not really exist","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/d/worrier0205.mp3","us":"media/ldoce/hwd/ame/b/laadworrier.mp3"},"examples":[{"en":"Her mother was a born worrier.","cn":"她母亲天生爱发愁。"}],"oxford":{"phon":"ˈwʌriə(r)","pos":"noun","senses":[{"en":"a person who worries a lot about unpleasant things that have happened or that might happen","cn":"爱担忧的人；常发愁的人","ex":{"en":"He’s such a worrier.","cn":"她发现他在欺骗她。更恶劣的是，她的朋友们知道这点却从没告诉过她。"}}]}},"woolly":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"毛料的；羊毛制的;像羊毛的","en":"Something that is woolly is made of wool or looks like wool.","ex":{"en":"She wore this woolly hat with pompoms.","cn":"她戴着这顶有小绒球的毛绒帽子。"}},{"pos":"N-COUNT 可数名词","cn":"毛料衣服；(尤指)毛衣，羊毛衫","en":"A woolly is a woollen piece of clothing, especially a sweater."},{"pos":"N-PLURAL 复数名词","cn":"内衣;(尤指)长袖毛线衣裤","en":"You can refer to underwear as woollies, especially when it is knitted from wool, and has long legs or long sleeves."},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人或观点）混乱的，糊涂的，不明确的","en":"If you describe a person or their ideas as woolly, you are criticizing them for being confused or vague.","ex":{"en":"...a weak and woolly Government","cn":"软弱、糊涂的政府"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"made of or feeling like wool","cn":"羊毛制的﹔像羊毛的"},{"en":"not showing clear thinking 〔","cn":"思想〕不清楚的﹐混乱的"},{"en":"a sweater or similar piece of knitted clothing","cn":"毛线衣﹔毛料服装"}]},"media":{"uk":"media/ldoce/hwd/bre/1/woolly_adj0205.mp3","us":"media/ldoce/hwd/ame/9/woolly1.mp3"},"examples":[{"en":"woolly monkeys","cn":"毛茸茸的猴子"},{"en":"a woolly hat","cn":"毛质的帽子"}],"oxford":{"phon":"ˈwʊli","pos":"adjective","senses":[{"en":"covered with wool or with hair like wool","cn":"有毛覆盖的；毛状物覆盖的","ex":{"en":"woolly monkeys","cn":"毛茸茸的猴子"}},{"en":"made of wool; like wool","cn":"毛制的；毛的；似毛的","lab":"informal, especially British English，，","ex":{"en":"a woolly hat","cn":"毛质的帽子"}},{"en":"not thinking clearly; not clearly expressed","cn":"糊涂的；混乱的；模糊的","ex":{"en":"woolly arguments","cn":"混乱的论点"}},{"en":"a piece of clothing made of wool, especially one that has been knitted","cn":"毛料衣服；（尤指针织的）毛线衣","lab":"British English, becoming old-fashioned，，","pos":"noun"},{"en":"a sheep","cn":"羊","lab":"Australian English, New Zealand English，，","pos":"noun"}]}},"worsted":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"精纺毛料","en":"Worsted is a kind of woollen cloth."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a type of woollen cloth","cn":"精纺毛料"}]},"media":{"uk":"media/ldoce/hwd/bre/a/ld41worsted.mp3","us":"media/ldoce/hwd/ame/0/worsted.mp3"},"examples":[{"en":"a grey worsted suit","cn":"一套灰色的精纺毛料西服"}],"oxford":{"phon":"ˈwʊstɪd","pos":"noun","senses":[{"en":"a type of cloth made of wool with a smooth surface, used for making clothes","cn":"精纺毛料","ex":{"en":"a grey worsted suit","cn":"一套灰色的精纺毛料西服"}}]}},"workbench":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"工作台","en":"A workbench is a heavy wooden table on which people use tools such as a hammer and nails to make or repair things."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a strong table used for working on with tools","cn":"工作台"}]},"media":{"img":["media/ldoce/img/workbench.jpg"],"uk":"media/ldoce/hwd/bre/6/ld41workbench.mp3","us":"media/ldoce/hwd/ame/b/workbench.mp3"},"oxford":{"phon":"ˈwɜːkbentʃ","pos":"noun","senses":[{"en":"a long, heavy table used for doing practical jobs, working with tools, etc.","cn":"工作台"}]}},"woody":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(植物)木本的，木质的","en":"Woody plants have very hard stems.","ex":{"en":"Care must be taken when trimming around woody plants like shrubs and trees","cn":"修剪灌木和乔木这样的木本植物时必须小心。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"长满树木的;林木覆盖的","en":"A woody area has a lot of trees in it.","ex":{"en":"...the wet and woody Vosges mountains.","cn":"湿润葱郁的孚日山脉"}},{"pos":"ADJ 形容词","cn":"木头味的；木香的","en":"Something that smells woody smells like wood.","ex":{"en":"This oil has a lovely woody fragrance.","cn":"这种精油散发着怡人的木香。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a woody plant has a stem like wood 〔","cn":"植物〕木本的﹐木质的"},{"en":"a woody area of land has a lot of trees growing on it 〔","cn":"某地〕树木茂盛的"}]},"media":{"uk":"media/ldoce/hwd/bre/b/woody0205.mp3","us":"media/ldoce/hwd/ame/6/woody.mp3"},"examples":[{"en":"a woody valley","cn":"树木茂盛的山谷"}],"oxford":{"phon":"ˈwʊdi","pos":"adjective","senses":[{"en":"having a thick, hard stem like wood","cn":"木本的；木质的"},{"en":"covered with trees","cn":"长满树木的；树木茂盛的","ex":{"en":"a woody valley","cn":"树木茂盛的山谷"}},{"en":"having a smell like wood","cn":"像木头味的","ex":{"en":"This new fragrance has woody notes.","cn":"这种新香水有点儿木香味。"}}]}},"woodshed":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"柴房；柴棚","en":"A woodshed is a small building which is used for storing wood for a fire."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a place for storing wood for burning","cn":"柴棚﹐柴房"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41woodshed.mp3","us":"media/ldoce/hwd/ame/3/woodshed.mp3"},"oxford":{"phon":"ˈwʊdʃed","pos":"noun","senses":[{"en":"a small building for storing wood in, especially for fuel","cn":"木料间；（尤指）柴房，柴棚"}]}},"woodwork":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(房子的)木构件，木建部分","en":"You can refer to the doors and other wooden parts of a house as the woodwork .","ex":{"en":"I love the living room, with its dark woodwork, oriental rugs, and chunky furniture","cn":"我喜欢起居室那深色的木构件、东方地毯和厚重的家具。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"木工;木匠活；木工手艺","en":"Woodwork is the activity or skill of making things out of wood.","ex":{"en":"I have done woodwork for many years","cn":"我做木工好多年了。"}},{"pos":"PHRASE 短语","cn":"突然跳出来;突然冒出来","en":"If you say that people are coming out of the woodwork, you are criticizing them for suddenly appearing in public or revealing their opinions when previously they did not make themselves known.","ex":{"en":"When a song gets to the top, someone will come out of the woodwork and claim to have written it.","cn":"当一首歌非常流行的时候，有人就会跳出来，说是自己写的。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the skill or activity of making wooden objects","cn":"木工手艺﹔木工活"},{"en":"the parts of a house or room that are made of wood 〔","cn":"房屋或房间的〕木建部分"},{"en":"if someone crawls out of the woodwork, they suddenly and unexpectedly appear in order to take advantage of a situation, express their opinion etc – used to show disapproval 〔","cn":"为得到好处﹑发表意见等而〕突然冒出来﹐突然露面〔含贬义〕"}]},"collocations":{"phrases":["ADJ. exterior, interior | polished","VERB + WOODWORK paint, treat, varnish | polish | strip | clean, wash | hit He hit the woodwork (= the wooden frame of the goal) twice before","PREP. in the ~ There were cracks in the woodwork."]},"media":{"uk":"media/ldoce/hwd/bre/0/woodwork0205.mp3","us":"media/ldoce/hwd/ame/5/woodwork.mp3"},"examples":[{"en":"When he won the lottery, all sorts of distant relatives came out of the woodwork.","cn":"他博彩中奖后，八杆子打不着的亲戚都突然来登门造访。"},{"en":"( BrE ) He hit the woodwork (= the wooden frame of the goal in the game of football/ soccer , etc.) twice before scoring.","cn":"他两次射门击中球门框之后，终得进球。"}],"oxford":{"phon":"ˈwʊdwɜːk","pos":"noun","senses":[{"en":"things made of wood in a building or room, such as doors and stairs","cn":"（建筑物或房间的）木建部分，木构件，木制品","ex":{"en":"The woodwork needs painting.","cn":"木建部分需要上油漆。"}},{"en":"the activity or skill of making things from wood","cn":"木工活；木工手艺","lab":"British English"}]}},"womanizer":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"玩弄女性的人;风流坯子;色鬼","en":"If you describe a man as a womanizer, you disapprove of him because he likes to have many short sexual relationships with women."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a man who has sexual relationships with many different women – used to show disapproval","cn":"玩弄女性的男人〔含贬义〕"}]},"vocab":{"pos":"n","senses":[{"en":"If you've ever known a man who can't keep his eyes off every single woman who walks by, you can call him a womanizer — especially if he's constantly handing out his phone number."}]},"media":{"uk":"media/ldoce/hwd/bre/c/brelasdewomanizer.mp3","us":"media/ldoce/hwd/ame/a/laadwomanizer.mp3"},"oxford":{"phon":"ˈwʊmənaɪzə(r)","pos":"noun","senses":[{"en":"a man who has sexual relationships with many different women","cn":"玩弄女性者","ex":{"en":"He has a reputation for being a womanizer.","cn":"他以玩弄女性出名。"}}]}},"wobbly":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"摇摆的;晃动的","en":"Something that is wobbly moves unsteadily from side to side.","ex":{"en":"I was sitting on a wobbly plastic chair.","cn":"我正坐在一把摇摇晃晃的塑料椅上。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(尤指因为害怕、生病或筋疲力尽而)颤抖的，打战的，颤巍巍的，站不稳的","en":"If you feel wobbly or if your legs feel wobbly, you feel weak and have difficulty standing up, especially because you are afraid, ill, or exhausted.","ex":{"en":"She could not maintain her balance and moved in a wobbly fashion","cn":"她无法保持平衡，走路颤颤巍巍。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(声音)发抖的，发颤的，颤抖的","en":"If a person's voice is wobbly, it sounds weak and keeps varying in pitch, for example because the person is about to cry.","ex":{"en":"'So that's why I want to go home,' he said in a wobbly voice.","cn":"“所以这就是我要回家的原因，”他声音颤抖地说。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(组织、经济或计划)不稳的，动荡的","en":"If you describe an organization, economy, or plan as wobbly, you think it is not very good or will not be successful.","ex":{"en":"...cheap deals on wobbly airlines","cn":"搭乘处于风雨飘摇的航空公司的航班的便宜买卖"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"something that is loose is not firmly fixed in the place where it should be","cn":""},{"en":"something that is wobbly shakes or moves from side to side because it is not fixed as firmly as it should be","cn":""},{"en":"moving unsteadily from side to side","cn":"摇摆的﹐摇晃的"}]},"collocations":{"phrases":["VERBS be, feel, look | become, go When I stood up my legs went all wobbly.","ADV. all (informal) , very | a bit, a little, rather, slightly The chair looked a bit wobbly."]},"media":{"uk":"media/ldoce/hwd/bre/1/ld41wobbly.mp3","us":"media/ldoce/hwd/ame/d/wobbly.mp3"},"examples":[{"en":"He's still a bit wobbly after the operation (= not able to stand firmly).","cn":"他动了手术之后仍然有点儿站不稳。"},{"en":"The evening got off to a wobbly start.","cn":"这次晚会一开始就不顺当。"}],"oxford":{"phon":"ˈwɒbli","pos":"adjective","senses":[{"en":"not properly fixed in place so that it moves from side to side","cn":"松动的；摇晃的","ex":{"en":"a chair with a wobbly leg","cn":"一条腿不稳的椅子"}},{"en":"weak and unsteady because you are ill or tired","cn":"（因生病或疲劳而）颤巍巍的，站不稳的","ex":{"en":"He's still a bit wobbly after the operation.","cn":"他动了手术之后仍然有点儿站不稳。"}},{"en":"not certain or confident","cn":"不稳的；拿不准的；没把握的；不自信的","ex":{"en":"the wobbly singing of the choir","cn":"唱诗班发颤的歌声"}}]}},"workbook":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"练习册;作业本","en":"A workbook is a book to help you learn a particular subject which has questions in it with spaces for the answers."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a school book containing questions and exercises","cn":"练习册"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41workbook.mp3","us":"media/ldoce/hwd/ame/6/workbook.mp3"},"oxford":{"phon":"ˈwɜːkbʊk","pos":"noun","senses":[{"en":"a book with exercises in it, often with spaces for students to write answers in, to help them practise what they have learnt","cn":"练习册；作业本"}]}},"wonderment":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"惊喜;惊叹","en":"Wonderment is a feeling of great surprise and pleasure.","ex":{"en":"His big blue eyes opened wide in wonderment.","cn":"他蓝色的大眼睛睁得大大的，透着惊喜。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a feeling of pleasant surprise or admiration","cn":"惊叹﹔惊奇"}]},"vocab":{"pos":"n","senses":[{"en":"Wonderment is a feeling of surprise, awe, and joy. People felt wonderment when Neil Armstrong walked on the moon."}]},"media":{"uk":"media/ldoce/hwd/bre/2/ld41wonderment.mp3","us":"media/ldoce/hwd/ame/5/wonderment.mp3"},"oxford":{"phon":"ˈwʌndəmənt","pos":"noun","senses":[{"en":"a feeling of pleasant surprise or wonder","cn":"惊喜；惊叹","ex":{"en":"She looked at her daughter in wonderment.","cn":"她惊讶地看着女儿。"}}]}},"workable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(思想或系统)实际的，可行的","en":"A workable idea or system is realistic and practical, and likely to be effective.","ex":{"en":"Investors can simply pay cash, but this isn't a workable solution in most cases.","cn":"投资者可以直接付现金，但这个办法在大多数情况下都不可行。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something is possible, it can be done or achieved","cn":""},{"en":"if an idea or plan is feasible, it is possible and you can find a practical way of doing it","cn":""},{"en":"possible and likely to be successful, and therefore worth doing","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/b/workable0205.mp3","us":"media/ldoce/hwd/ame/9/workable.mp3"},"examples":[{"en":"Add more water until the dough is workable.","cn":"往面团里再加点儿水，直到能揉成形为止。"},{"en":"a workable plan","cn":"切实可行的计划"}],"oxford":{"phon":"ˈwɜːkəbl","pos":"adjective","senses":[{"en":"that can be used successfully and effectively","cn":"可行的；行得通的","ex":{"en":"a workable plan","cn":"切实可行的计划"}},{"en":"that you can shape, spread, dig, etc.","cn":"可成形（或延长、挖掘等）的","ex":{"en":"Add more water until the dough is workable.","cn":"往面团里再加点儿水，直到能揉成形为止。"}},{"en":"that can still be used and will make a profit","cn":"可开采的；可开发的"}]}},"wok":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(做中餐用的)锅，炒锅","en":"A wok is a large bowl-shaped pan which is used for Chinese-style cooking."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a wide pan shaped like a bowl, used in Chinese cooking 〔","cn":"中国烹饪中使用的〕铁锅﹐镬子"}]},"media":{"uk":"media/ldoce/hwd/bre/4/wok0205.mp3","us":"media/ldoce/hwd/ame/0/walk1.mp3"},"oxford":{"phon":"wɒk","pos":"noun","senses":[{"en":"a large pan like a bowl in shape, used for cooking food, especially Chinese food","cn":"炒菜锅；镬子","ex":{"en":"Heat a wok or large frying pan until hot and add the oil.","cn":"将炒锅或平底大煎锅加热后放油。"}}]}},"wordless":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(尤指期待某人说话时)无言的，沉默的","en":"You say that someone is wordless when they do not say anything, especially at a time when they are expected to say something.","ex":{"en":"She stared back, now wordless","cn":"她凝视着后面，一时无语。"}},{"pos":"ADJ 形容词","cn":"(声音)无言的，不含词语的","en":"If someone makes a wordless sound, they make a sound that does not seem to contain any words.","ex":{"en":"...a wordless chant","cn":"没有歌词的咏唱"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"without using words","cn":"无话的﹔默默无言的"}]},"media":{"uk":"media/ldoce/hwd/bre/6/ld41wordless.mp3","us":"media/ldoce/hwd/ame/4/wordless.mp3"},"examples":[{"en":"a wordless cry/prayer","cn":"无言的痛哭；默默的祷告"},{"en":"She threw her arms around him in wordless grief.","cn":"她张开双臂一把抱住他﹐满怀无言的悲痛。"}],"oxford":{"phon":"ˈwɜːdləs","pos":"adjective","senses":[{"en":"without saying any words; silent","cn":"默默无言的；沉默的","g":"[usually before noun]","ex":{"en":"a wordless cry/prayer","cn":"无言的痛哭；默默的祷告"}},{"en":"not saying anything","cn":"不语的；沉默寡言的","ex":{"en":"They stood wordless, like friends consoling the bereaved.","cn":"他们一言不发地站着，就像朋友在安慰失去亲人的人一样。"}}]}},"workhorse":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"役马;耕马","en":"A workhorse is a horse which is used to do a job, for example to pull a plough."},{"pos":"N-COUNT 可数名词","cn":"吃苦耐劳的人;老黄牛;重负荷机器","en":"If you describe a person or a machine as a workhorse, you mean that they can be relied upon to do a large amount of work, especially work that is dull or routine.","ex":{"en":"...the Wellington bomber, the great workhorse of the war","cn":"在战争中立下汗马功劳的威灵顿轰炸机"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a person, machine, or vehicle that does a lot of work, especially when it is hard or boring","cn":"吃苦耐劳的人﹐老黄牛﹔重负荷机器[运载工具]"}]},"media":{"uk":"media/ldoce/hwd/bre/d/ld41workhorse.mp3","us":"media/ldoce/hwd/ame/9/workhorse.mp3"},"examples":[{"en":"The Hercules aircraft has been the workhorse of the air force for over 25 years. 25","cn":"年来﹐大力神运输机为空军立下了汗马功劳。"}],"oxford":{"phon":"ˈwɜːkhɔːs","pos":"noun","senses":[{"en":"a person or machine that you can rely on to do hard and/or boring work","cn":"埋头苦干的人；老黄牛（指吃苦耐劳的人）；耐用的机器"}]}},"wolf-whistle":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(挑逗地)吹口哨","en":"If someone wolf-whistles, they make a whistling sound with a short rising note and a longer falling note. Some men wolf-whistle at a woman to show that they think she is attractive, and some women find this offensive.","ex":{"en":"They wolf-whistled at me, and I was so embarrassed I tripped up.","cn":"他们吹口哨挑逗我，我窘迫之下绊了一跤。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a way of whistling that men sometimes use to show that they think a woman is attractive","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/9/ld41wolf_whistle.mp3","us":"media/ldoce/hwd/ame/b/wolf_whistle.mp3"},"oxford":{"phon":"ˈwʊlf wɪsl","pos":"noun","senses":[{"en":"a whistle with a short rising note and a long falling note, made by somebody, usually a man, to show that they find somebody else attractive, especially somebody passing in the street","cn":"挑逗呼哨（尤指男子在街上向美貌女子吹的）","ex":{"en":"She was fed up with the builders' wolf whistles each morning.","cn":"每天早上都有建筑工人冲她挑逗地吹口哨，她都烦死了。"}},{"en":"to whistle at somebody with a short rising note and a long falling note to show that you find them attractive","cn":"（尤指挑逗性地）吹口哨","pos":"verb"}]}},"workflow":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the way that a particular project is organized by a company, including which part of a project someone is going to do, and when they are supposed to do it","cn":"工作流程"}]},"media":{"uk":"media/ldoce/hwd/bre/c/ld42workflow.mp3","us":"media/ldoce/hwd/ame/c/ld42workflow.mp3"},"oxford":{"phon":"ˈwɜːkfləʊ","pos":"noun","senses":[{"en":"the series of stages that a particular piece or type of work passes through from the beginning until it is finished; the rate at which it passes through these stages","cn":"工作流程；工作流","ex":{"en":"He was responsible for managing the workflows of a department of 400.","cn":"他负责管理 400 人的部门的工作流程。"}}]}}});
